window.__D("text/torat-shmuel/c030",{"p":[[2000450397,"שענין קטן וגדול זהו מצד הגבלת הכלים שזה משיג יותר ועובד יותר וזה פחות שכ\"ז אינו שייך אלא בבחי' הגבלה אבל למעלה מהגבלת הכלי אינו שייך כלל חילוקי' אלו ונמצא כי קטן וגדול שוה בזה, ולכן ה\"ז בחי' העלאות מ\"ן לבחי' שופט צדק שמשוה קטן וגדול כו', וזהו דכתי' ממעמקי' קראתיך ה'<sup data-n=\"4221\">12</sup>, שבעשי\"ת טוב לומר מזמור זה, כי עומק בגימ' רי\"ו<sup data-n=\"4222\">14</sup>, שבכ\"י מעשי\"ת מתעורר עומק א'<sup data-n=\"4223\">15</sup> מעשרה עומקים הנז' בס\"י<sup data-n=\"4224\">16</sup>, כמ\"ש בסידור האריז\"ל<sup data-n=\"4225\">13</sup>, והיינו ע\"י התשובה מעומקא דליבא שז\"ע ממעמקי' קראתיך מתוך עומק פנימיות נקודת לבבי משם קראתיך כו'.\n<b>ולהבין</b><sup data-n=\"4226\">17</sup> שרש ענין התשובה במ\"ש ממעמקים קראתיך הוי' כו' שהוא תשוב ה\"י<sup data-n=\"4227\">18</sup> במלוי יו\"ד כו', הנה הה\"י במילוי יו\"ד הן בחי' ב' יסודות דאו\"א כו', וידוע דיסוד אבא שהוא היו\"ד גנוז ומלובש ביסוד אימא ע\"כ הוא<sup data-n=\"4228\">21</sup><sup data-n=\"4229\">19</sup> ה\"י במלוי יו\"ד כו' והן ב' עומקים דממעמקים<sup data-n=\"4230\">20</sup> קראתיך כו' (שע\"י בחי' ב' עומקים אלו מעוררי' ב\"פ אנכי להיות הוא מוחה פשעיך, דפי' הוא י\"ל שזהו עוד גבוה יותר מבחי' ב\"פ אנכי, והיינו כמ\"ש בשל\"ה הוא ר\"ת<sup data-n=\"4231\">22</sup> הוא ושמו אחד והיינו בחי' עד שנה\"ע<sup data-n=\"4232\">23</sup> הי' הוא ושמו בלבד, ובעה\"ק עד שלא נאצל אצי' העליון<sup data-n=\"4233\">24</sup> ופי' אצי' העליון י\"ל שא\"ק נק' אדם דבריאה<sup data-n=\"4234\">25</sup> דכלליות ואצי' דכלליות<sup data-n=\"4235\">26</sup> זהו כמ\"ש בס' ק<sup data-n=\"4236\">28</sup> זהר הרקיע מהאריז\"ל פ' בראשית דט\"ו<sup data-n=\"4237\">27</sup> שיש כדוגמת עתיק לעילא מגלגלתא דא\"ק וז\"ע אצי' דכלליות, ועד שלא נאצל אצילות זו הי' הוא ושמו בלבד, והיינו ש'",[["4221","12","<b>ממעמקי' קראתיך הוי'</b>: תהלים קל, א."],["4222","14","<b>עומק בגימ' רי\"ו</b>: סידור קול יעקב (ושם: עמוק) ור\"ש רשקוב־ שער הכוונות דרושי ר\"ה קודם דרוש א־ פע\"ח שער תפילות ר\"ה שכ\"ה, פ\"ז־ ועד\"ז במשנת חסידים מסכת יום ר\"ה פ\"ב, מ\"א."],["4223","15","<b>שבכ\"י מעשי\"ת מתעורר עומק א'</b>: סידור ר\"ש רשקוב ופע\"ח שם."],["4224","16","<b>מעשרה עומקים הנז' בס\"י</b>: פ\"א, מ\"ה."],["4225","13","<b>שבעשי\"ת טוב לומר מזמור זה. . בסידור האריז\"ל</b>: לר\"ש רשקוב במקומו (תפלת הבריאה — שחרית — אחר ברכו). וסידור קול יעקב לר' יעקב קאפיל כוונת תפלת יום ב דר\"ה (ע' קנו). ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתמא ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ג ע' תתסט וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540705\" data-slug=\"torat-chaim\" data-id=\"2300540705\">תו\"ח בשלח רכט ב</a> וש\"נ."],["4226","17","<b>ולהבין</b>: במאמרי אדה\"ז תקס\"ה כאן ע' תתקמג: ד) ועתה יש להבין. וכן העתיק הר\"ש סופר (בלי ציון הפרק). ותיקן כ\"ק אדמו\"ר מהר\"ש כבפנים."],["4227","18","<b>התשובה. . תשוב ה\"י</b>: ראה זהר רע\"מ נשא קכב, א."],["4228","21","<b>הוא</b>: ניתוסף בגוכתי\"ק."],["4229","19","<b>ה\"י במלוי יו\"ד</b>: ראה גם לעיל המשך חייב אדם לברך פי\"ט ובהערה 676."],["4230","20","<b>ה\"י במלוי יו\"ד. . ב' יסודות. . דממעמקים</b>: ראה לקמן מאמר ד\"ה שיר המעלות ממעמקים בתחלתו שמציין בסידור האריז\"ל. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתפד."],["4231","22","<b>כמ\"ש בשל\"ה הוא ר\"ת</b>: בית ה' ד, א."],["4232","23","<b>עד שנה\"ע</b>: ראה פדר\"א פ\"ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540053\" data-slug=\"torat-chaim\" data-id=\"2300540053\">תו\"ח וארא ח\"א נג, ב</a> הערה 6."],["4233","24","<b>ובעה\"ק עד. . אצי' העליון</b>: חלק היחוד פ\"ב [ושם: קודם שנאצל האצילות הנעלם]. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460024\" data-slug=\"or-hatorah-hb\" data-id=\"8316460024\">אוה\"ת יתרו ע' תתלט</a>."],["4234","25","<b>שא\"ק נק' אדם דבריאה</b>: ראה ע\"ח שער סדר אצי' ש\"ג, פ\"א. לעיל המשך חייב אדם לברך פל\"ז ובהערה 1538."],["4235","26","<b>ואצי' דכלליות</b>: ראה מאמר ד\"ה מה רבו מעשיך תרמ\"ד נדפס בקונט' בר מצוה תרנ\"ג ע' נא."],["4236","28","<b>ק</b>: ד: ליתא."],["4237","27","<b>בס' זהר הרקיע. . דט\"ו</b>: לזהר בראשית. ובדפי הספר יט, ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380705\" data-slug=\"likkutei-torah\" data-id=\"4001380705\">לקו\"ת מסעי צה, ב</a>. המשך תער\"ב ח\"ג ע' א'שצז."]]],[2000450398,"הוי' במילוי אלפין<sup data-n=\"4238\">29</sup> כמו שהוא בעצמותו לפני הצמצום וכמשי\"ת, ולכן ע\"י ב' עומקים שמעוררים ב\"פ אנכי, מתעלי' ב\"פ אנכי בבחי' הוא ר\"ת הוא ושמו אחד היינו מ\"ה שלפני הצמצום והקו שהוא בחי' ב\"ן כמשי\"ת וזהו הוא להיות מוחה פשעיך כו').\n<b>וביאור</b> הדברים וגם להבין איך שב' עומקים דאו\"א הן שיקראו לשם הוי' כו', הנה תחלה יש להקדים כלל אחד והוא כלל גדול כולל<sup data-n=\"4239\">30</sup> כל פרטי השתל' דכל הפרצופי' כו' והוא אשר בתחלת וראש לפני כל ההשתל' דא\"ק עד רגלי העשי' לא<sup data-n=\"4240\">31</sup> הי' מעצמו' אור א\"ס בבחי' התחלקות כלל כ\"א<sup data-n=\"4241\">32</sup> ב' שמות מ\"ה וב\"ן<sup data-n=\"4242\">33</sup> בלבד שיצאו מעצמיות אוא\"ס והוא מה שלפני הצמצום דקו וחוט כו' נק' שם מ\"ה כמאמר הי' הוא ושמו בלבד כו' (וגם זה הוא שאנו קוראי' כן זהו לפי מה שנמשך אח\"כ לאחר הצמצום בחי' מ\"ה כו' אנו מכנים בחי' מ\"ה גם לפני בחי' הצמצום כו') וצמצום הקו וחוט כו' נק' בשם ב\"ן בכלל, ועדיין אין מציאת בחי' השתלשלו' ממש בבחי' התחלקות ממש להיות בבחי' פרצופי' מחולקי' כו', עד שבחי' עתיק וא\"א הוא שנתחלקו ב' שמות הנ\"ל דמ\"ה וב\"ן להיות נקראי' בשם ב' פרצופי' והוא פרצוף עתיק בשם מ\"ה בכלל וא\"א בשם ב\"ן בכלל וכנ\"ל ועדיין אין זה בחי' התחלקות גמור שהרי ע\"י וא\"א בפרצוף א' נחשבים רק שזה מבחי' התחתונה שבמאציל וזה נעשה ראש לנאצלים כנ\"ל<sup data-n=\"4243\">34</sup>, אבל כללות שניהם ענין א' והוא בבחי' כתר בכלל והוא בחי' ממוצע בין עולם הא\"ס לעולם הנאצלי'<sup data-n=\"4244\">35</sup> כידוע, אבל כשירד עוד האור מעצמות אוא\"ס למטה יותר והוא בבחי' או\"א שיונקי' ממזלות דא\"א וכנ\"ל<sup data-n=\"4245\">36</sup> שם נתחלק האור להיות בבחי' ב' פרצופי' שלימים ונפרדים לגמרי כו' עד שנקראו בשם תרין ריעין<sup data-n=\"4246\">37</sup> וכנ\"ל<sup data-n=\"4247\">38</sup> והגם שהן תרדל\"מ וכחדא שריין<sup data-n=\"4248\">39</sup> וכחדא נפקין כו' כידוע, מ\"מ תרין ריעין הם בבחי' התחלקות ממש לשני פרצופי' וכו' רק שהן תמיד בתכלית היחוד כו' ואמנם מ\"מ הרי הן ביחוד תמידי כאלו הן אחדות א' ממש כמאמר כחדא שריין כו'. אבל בירידת האור עוד<sup data-n=\"4249\">40</sup> למטה יותר והוא בבחי' זו\"נ דאצי' שם נעשו ב' שמות הנ\"ל ב' פרצופים ונפרדים ממש ולא יש יחוד ביניהם כ\"א לפרקים ועתים ידועים כידוע",[["4238","29","<b>ש' הוי' במילוי אלפין</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. שער רפ\"ח ניצוצין שי\"ח, פ\"א."],["4239","30","<b>כולל</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן ע' רמז. ובמאמרי אדה\"ז תקס\"ה כאן ע' תתקמד: ליתא."],["4240","31","<b>לא</b>: שם: ולא."],["4241","32","<b>כלל כ\"א</b>: ניתוסף בגוכתי\"ק."],["4242","33","<b>מ\"ה וב\"ן</b>: ראה הערה במאמרי אדה\"ז תקס\"ה כאן."],["4243","34","<b>כנ\"ל</b>: ראה לעיל מאמר ד\"ה אנכי אנכי ובהערה 51."],["4244","35","<b>כתר. . ממוצע בין עולם הא\"ס לעולם הנאצלי'</b>: ראה גם לעיל המשך כי תשא פ\"ח על יד הערה 192. חייב אדם לברך פ\"א על יד הערה 11. מאמר ד\"ה על חומותיך על יד הערה 56."],["4245","36","<b>וכנ\"ל</b>: ראה לעיל מאמר ד\"ה אנכי אנכי ובהערה 60."],["4246","37","<b>תרין ריעין</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670185\" data-slug=\"torat-chaim\" data-id=\"2300670185\">תו\"ח בראשית כא, ב</a> ובהערה 8."],["4247","38","<b>וכנ\"ל</b>: כ\"ה גם במאמרי אדה\"ז תקס\"ה כאן."],["4248","39","<b>וכחדא שריין</b>: ראה זהר אד\"ז האזינו רצ, ב. ראה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 58."],["4249","40","<b>האור עוד</b>: במאמרי אדה\"ז תקס\"ה כאן־ ובסה\"מ תרכ\"ו כאן: עוד האור."]]],[2000450399,"כמו בג' רגלים שיש יחוד זו\"נ שהוא יחוד מ\"ה וב\"ן כידוע אבל ברוב העתים שם מ\"ה דז\"א פרצוף בפ\"ע ושם ב\"ן דנוק' פרצוף נפרד לעצמו כו' כידוע.\n<b>וא\"כ</b> נמצא מובן שהגם שהתחלת אור הראשון הפשוט מעצמות אור הא\"ס לא הי' רק בבחי' חילוק ב' שמות מ\"ה וב\"ן בלבד מ\"מ ע\"י ירידת האור וריחוקו מעצמות אור הא\"ס נעשה בו בחי' פירוד והתחלקות מעט מעט עד שנבדלו ונעשו בחי' מפורדים לגמרי בזו\"נ כו'. ואמנם מ\"מ מובן מתוך כ\"ז דהיא הנותנת לומר שאין כל חדש בכל ריבוי ההשתל' דא\"א וע\"י ואו\"א וזו\"נ שהרי כולם בכלל ענין ודבר א' בלבד והוא ב' שמות מחולקים בלבד והיינו מ\"ה וב\"ן שבמאציל עצמו רק שבע\"י וא\"א התחלקותם באופן גבוה יותר ובאו\"א נתחלקו יותר בירידות המדרגות ובזו\"נ ירדו עוד יותר<sup data-n=\"4250\">41</sup> כנ\"ל, אבל מ\"מ עדיין אינם רק ב' שמות בלבד לפני עצמות המאציל דהגם שלפי סדר ההשתל' נתרחקו ונבדלו הרבה אבל לפני עצמות המאציל ששוה ומשוה קטן וגדול וכמ\"ש קטן וגדול שם הוא<sup data-n=\"4251\">42</sup> (ונק'<sup data-n=\"4252\">43</sup> אלוה<sup data-n=\"4253\">44</sup> הראשוני' והאחרונים<sup data-n=\"4254\">45</sup> וכמ\"ש שאל נא לימים ראשונים<sup data-n=\"4255\">46</sup> ) הרי גם עתה עדיין זו\"נ הם רק בחי' ב' שמות מ\"ה וב\"ן בלבד כמו שהיו במאציל עצמו לפני ההשתל' מאחר שאין שינוי לפני עצמות המאציל בין קודם כל ההשתלשלות לאחר כל ההשתל' כו'.\n<b>ובכ\"ז</b> יובן שכאשר בחי' ממעמקים שהוא ב' עומקים דאו\"א הנ\"ל מעלין מ\"ן למעלה בא\"א וע\"י אז ממילא נמשך מן העצמות להיות בחי' ע\"י וא\"א מאירים אורם ושפעם בנאצלים כנ\"ל מאחר ששרשם וכללותם של ענין א\"א וע\"י<sup data-n=\"4256\">47</sup> עם או\"א הכל ענין א' והוא רק בחי' ב' שמות מ\"ה וב\"ן בלבד כנ\"ל רק שנתחלקו יותר באו\"א להיות נקראים תרין ריעין כנ\"ל. אבל מ\"מ כשאו\"א מעלים מ\"ן חוזרים להיות ממש בבחי' ע\"י וא\"א עצמן והוא מפני ששרשן א' כנ\"ל וא\"כ ע\"י העלאת מ\"ן דיסוד אבא נמשך מ\"ה דע\"י וע\"י מ\"ן דאימא נמשך שם ב\"ן דא\"א כו' ועד\"ז עד רום המעלות גם מע\"י וא\"א למעלה כו' (והיינו בבחי' הוא הנ\"ל שזהו בחי' מ\"ה שלפני הצמצום והקו שנק' ב\"ן בכלל כו'). וזהו פי' תשובה תשוב ה\"י במלוי יו\"ד שהן מילוי דיסוד אבא ביסוד אימא שנק' שניהם מעמקים ב' עומקים שישובו לחזור למקור חוצבם בע\"י וא\"א להיות ממשיכים אנכי אנכי ב\"פ כנ\"ל. ולהבין זה בנה\"א ידוע שבחי' דממעמקים זהו ב' האהבות דבכל נפשך<sup data-n=\"4257\">48</sup> ובכל מאדך בכל נפשך מבחי' התבוננו' דבינה כו' ובכל מאדך בחי' ביטול במציאות לגמרי שהוא ע\"י בחי' אור אבא כידוע, והנה מבואר למעלה<sup data-n=\"4258\">49</sup> שנפש האדם כלולה היא מכל הפרצופי' העליוני'",[["4250","41","<b>יותר</b>: בסה\"מ תרכ\"ו כאן ע' רמח: ליתא."],["4251","42","<b>קטן וגדול שם הוא</b>: איוב ג, יח."],["4252","43","<b>(ונק'</b>: הסוגר נמצא במאמרי אדה\"ז תקס\"ה כאן."],["4253","44","<b>אלוה</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן. ובמאמרי אדה\"ז תקס\"ה כאן: אלקי."],["4254","45","<b>אלקי הראשוני' והאחרונים</b>: פיוט נשמת."],["4255","46","<b>שאל נא לימים ראשונים</b>: ואתחנן ד, לב."],["4256","47","<b>א\"א וע\"י</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן. ובמאמרי אדה\"ז תקס\"ה כאן ע' תתקמה: ע\"י וא\"א."],["4257","48","<b>דבכל נפשך</b>: ואתחנן ו, ה. ראה גם לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 73."],["4258","49","<b>מבואר למעלה</b>: בראש ההמשך מאמר ד\"ה להבין וכו' כי המצוה."]]],[2000450400,"דע\"י וא\"א ואו\"א וזו\"נ כו' ע\"כ יש ביכולתה באתעדל\"ת בב' עומקי' הנ\"ל דבכל נפשך ובכל מאדך לעורר למעלה שיהי' ג\"כ העלא' מ\"ן דאו\"א למעלה בע\"י וא\"א ויהי' נמשך אח\"כ מ\"ה וב\"ן דע\"י שהן ב\"פ אנכי כנ\"ל.\n<b>וזהו</b><sup data-n=\"4259\">50</sup> פי' הפסוק כי המצוה הזאת<sup data-n=\"4260\">51</sup> אשר אנכי מצוך היום כו' אשר אנכי מי<sup data-n=\"4261\">53</sup> שאנכי<sup data-n=\"4262\">54</sup> שהוא בחי' עתיק<sup data-n=\"4263\">55</sup> כו' וזהו דוקא ע\"י מצות התשובה<sup data-n=\"4264\">52</sup> תשוב ה\"י כו' וכמבואר הטעם מכל הנ\"ל שבתשובה דוקא תלוי המשכה אנכי מי שאנכי כו', ומ\"ש עוד אשר אנכי מצוך היום דוקא ולא למחר כו' יובן עפ\"י ענין הנ\"ל<sup data-n=\"4265\">56</sup> בפסוק נעשה אדם<sup data-n=\"4266\">57</sup> כו' דנפש האדם הנה היא כלולה מכל ההשתל' העליונה ולכך נא' בו נעשה לשון רבים<sup data-n=\"4267\">58</sup> כו' ולהיות כן הרי נעוץ על ידו תחב\"ס וסוב\"ת דמזה מוכרח לומר שיש בחי' הארה כוללת את הכל ולמעלה מכולם שעל ידה יהי' נעוץ תחב\"ס וסוב\"ת<sup data-n=\"4268\">59</sup> דאל\"כ הי' כ\"א על מקומו יבא ולא הי' הראש מצטרך לסוף כו', ומה<sup data-n=\"4269\">60</sup> שהראש מצטרך לסוף מזה הוראה שיש דבר שלמעלה מהראש והסוף כו' שלטעם זה יוכל להיות נעוץ תחב\"ס כו' שהוא בחי' ההתכללו' מבלתי ימצא ראש וסוף<sup data-n=\"4270\">61</sup> כלל כו'. וכ\"ז נמצא באדם, וי\"ל שזה\"ע אדם אדמה לעליון<sup data-n=\"4271\">63</sup> שלמעלה מבחי' השתלשלות כו', ובחי' אדם זהו דוקא כשהנשמה מלובשת בגוף<sup data-n=\"4272\">64</sup> כו' כמ\"ש מזה במ\"א<sup data-n=\"4273\">62</sup>. ולזה הטעם אין התשובה אלא עכשיו<sup data-n=\"4274\">65</sup> ולא למחר בעוה\"ב שהרי גם עכשיו בגיהנם אין רשעים עושין תשובה וכמארז\"ל ברשעים דאפי' על פתחו של גיהנם<sup data-n=\"4275\">66</sup>",[["4259","50","<b>וזהו</b>: במאמרי אדה\"ז תקס\"ה כאן־ ובסה\"מ תרכ\"ו כאן נרשם: פ\"ה."],["4260","51","<b>כי המצוה הזאת</b>: נצבים ל, יא."],["4261","53","<b>מי</b>: במאמרי אדה\"ז תקס\"ה כאן־ ובסה\"מ תרכ\"ו כאן: פי' אנכי מי."],["4262","54","<b>אנכי מי שאנכי</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא מהדו\"ק ספמ\"ט</a>. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["4263","55","<b>אנכי מי שאנכי. . עתיק</b>: ראה גם לעיל מאמר ד\"ה אנכי אנכי על יד הערה 49."],["4264","52","<b>כי המצוה הזאת. . מצות התשובה</b>: ראה רמב\"ן נצבים ל, יא. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380901\" data-slug=\"likkutei-torah\" data-id=\"4001380901\">לקו\"ת נצבים מה, ג</a>. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתעו. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141124\" data-slug=\"likkutei-sichot\" data-id=\"1300141124\">לקו\"ש נצבים כרך יד ע' 112</a> הערה 24."],["4265","56","<b>הנ\"ל</b>: בראש ההמשך מאמר ד\"ה להבין וכו' כי המצוה."],["4266","57","<b>נעשה אדם</b>: בראשית א, כו."],["4267","58","<b>נעשה. . לשון רבים</b>: ב\"ר פ\"ח, ח."],["4268","59","<b>נעוץ תחב\"ס וסוב\"ת</b>: ראה ס\"י פ\"א, מ\"ז. סידור שער הת\"ת צח, ג ואילך. סה\"מ תר\"ל ע' שכ. וראה גם לעיל מאמר ד\"ה ומקנה רב על יד הערה 27."],["4269","60","<b>ומה</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן ע' רמט. ובמאמרי אדה\"ז תקס\"ה כאן: וזה."],["4270","61","<b>מבלתי ימצא ראש וסוף</b>: ע\"פ קהלת ג, יא."],["4271","63","<b>אדם אדמה לעליון</b>: ישעי' יד, יד. ראה עבוה\"ק ח\"א חלק היחוד פי\"ז. מאמרי אדה\"א דברים ח\"א ע' קכב. וש\"נ. בראשית ע' קסב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670564\" data-slug=\"torat-chaim\" data-id=\"2300670564\">תו\"ח בראשית יח, ג</a>. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 81."],["4272","64","<b>אדם. . . כשהנשמה מלובשת בגוף</b>: ראה גם סה\"מ תרכ\"ז ע' תעא. תרל\"ב ח\"א ע' רסו. הגהות לד\"ה פתח אלי' תרנ\"ח ר\"ע ב. תער\"ב ח\"א ר\"ע תכח."],["4273","62","<b>וכ\"ז נמצא. . במ\"א</b>: הוספת כ\"ק אדמו\"ר מהר\"ש."],["4274","65","<b>אין התשובה אלא עכשיו</b>: ראה סידור שחרית לב, א. לד, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380621\" data-slug=\"likkutei-torah\" data-id=\"4001380621\">לקו\"ת פינחס עה, ב</a> ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תתכג. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540619\" data-slug=\"torat-chaim\" data-id=\"2300540619\">תו\"ח שמות ח\"א ז, א</a>. וש\"נ."],["4275","66","<b>ברשעים דאפי' על פתחו של גיהנם</b>: ערובין יט, א."]]],[2000450401,"אינן חוזרין כו' והוא מטעם שא\"א לו לעשות תשובה שם ובכאן בהיות הנפש בגוף יכולה לשוב בתשובה שלימה וכמו ראב\"ד שיצא נשמתו<sup data-n=\"4276\">67</sup> כו' והרי הי' ביכולתו להתהפך ולעלות מקצה התחתון שהי' רועה זונו' ולהתקשר בקצה העליון במעלה ומדרגה גבוה כ\"כ עד שגם ר' בכה עליו ואמר יש קונה עולמו בשעה א' כו' ואין זה הכח לנפש אלא כאן בזה העולם, והעיקר לכ\"ז הו\"ע הנ\"ל לפי שע\"י האדם בגופו הנה להיותו כולל כל ההשתל' כנ\"ל יהי' ביכולת על ידו להיות נעוץ תחב\"ס כו' כנ\"ל וע\"כ ביכולתו ג\"כ להיות עולה מן הקצה לקצה ממש כי נעוץ סוב\"ת כו' ולא נחלק ונבדל אצלו כל הדרגות עד שיהי' כ\"א על מקומו דוקא ולא יתערב בשל זולתו אלא אדרבה יהי' במדריגת בחי' ההתכללות של זה בזה כו' מטעם נעוץ תחלתן כו' וא\"כ גם יהפוך מרע לטוב בתשו' ובהיפך בבחירה שלו יהפוך מטוב לרע כו', אבל בעוה\"ב שאינו אלא מדרגה פרטי' ולא כללית כמו האדם כאן לכך הנה שם כאו\"א על מקומו דוקא ולא יוכל איש לשנות מדרגתו לא מטוב לרע ולא מרע לטוב כלל כו' וע\"כ רשעים אפי' על פתחו של גיהנם אינן חוזרין כי בלתי אפשר להם לחזור מטעם זה, משא\"כ האדם בזה העולם שהוא כלול מכללות כל ההשתל' כמ\"ש נעשה אדם כו' ע\"כ ביכולתו להפוך ממדרגה למדרגה כו'.\n<b>וזהו</b> שאמר אשר אנכי מצוך היום, היום דוקא ולא למחר בעוה\"ב כו' כי היום דוקא נעוץ תחב\"ס כו' ולא למחר בעוה\"ב מטעם הנ\"ל. וע\"י<sup data-n=\"4277\">68</sup> בחי' זו דתשו' שהיא שוה לכנ\"פ<sup data-n=\"4278\">69</sup> כנ\"ל עי\"ז מעוררי' שמבחי' שהוא שוה, שאם<sup data-n=\"4279\">70</sup> היותו משוה קטן וגדול, י\"ל בחי' בנה הגדול ובנה הקטן<sup data-n=\"4280\">71</sup> עכ\"ז יהי' נמשך בחי' משפט צדק, והיינו כמו שהי' בתחילת הבריאה שהי' שומר לפרי<sup data-n=\"4281\">72</sup> כו', כי מה שנעשה מנגד לפירי זהו ע\"י העול דחטא עה\"ד, אבל ע\"י התשובה נמשך מבחי' שופט צדק להיות משפט צדק כמו קודם החטא שתהי' שומר לפרי כו'.",[["4276","67","<b>ראב\"ד שיצא נשמתו</b>: ע\"ז יז, א. ראה סה\"מ תרמ\"ו ע' יט."],["4277","68","<b>וע\"י</b>: מכאן ואילך הוספת כ\"ק אדמו\"ר מהר\"ש."],["4278","69","<b>לכנ\"פ</b>: לכל נפש."],["4279","70","<b>שאם</b>: כ\"ה בכ\"מ — ראה לעיל המשך וידבר וגו' ויצוום פ\"ג ובהערה 50."],["4280","71","<b>בנה הגדול ובנה הקטן</b>: תולדות כז, מב."],["4281","72","<b>שהי' שומר לפרי</b>: ראה של\"ה בית ישראל יט, ב. לעיל המשך חייב אדם לברך פי\"ט ובהערה 707."]]],[2000450402,"<h3>שה\"מ ממעמקים כו'</h3>\n<b>בס\"ד ש\"ת האזינו ל\"ט</b>\n<b></b>נפלאת רחוקה עת\"י א\"א כו' בפיך ובלבבך לעשותו\nש\"ש\n<b>שיר</b> המעלות ממעמקי'<sup data-n=\"4282\">1</sup> קראתיך ה'<sup data-n=\"4283\">2</sup>, הנה נת' בד\"ה וכ\"מ שהוא שופט צדק<sup data-n=\"4284\">3</sup>, שענין ממעמקי' זהו ב' יסודות דאו\"א, והוא ע\"פ משנ\"ת בסידור האריז\"ל, ולכאו' פי' קראתיך קאי על אוא\"ס עצמותו ומהותו א\"כ איך ע\"י ממעמקי' ב' יסודות דאו\"א יגיע להמשיך מאוא\"ס עצמותו, שהרי לגבי<sup data-n=\"4285\">4</sup> גם פלא נחשב כעשי' גשמי' כמ\"ש עושה פלא<sup data-n=\"4286\">5</sup>, אך הענין הוא דבמצות התשובה כתי' לא<sup data-n=\"4287\">6</sup> נפלאת היא ממך<sup data-n=\"4288\">7</sup> ולא רחוקה היא כו'. הנה ידוע דבחי' עתיק נק' בשם פלא עליון<sup data-n=\"4289\">8</sup> וכמ\"ש נורא תהלות<sup data-n=\"4290\">9</sup> עושה פלא (שבחי'<sup data-n=\"4291\">10</sup> פלא הוא בבחי' אשר יראי' להללו שזהו בבחי' העליונה דכתר שהוא בחי' ע\"י כו'). והטעם לזה הנה היות פי' פלא ידוע שהו\"ע הבדלה והפרשה כמ\"ש כי יפלא ממך דבר<sup data-n=\"4292\">11</sup> כו', שהדבר מופרש ומובדל ממך להשיגו כי מפני בחי' עומק של המושג לא ישיגנו האדם כלל וכלל והרי הדבר נבדל ונעלם מעיני השגתו לגמרי כו', וזהו הנק' למעלה בחי' אור מקיף העליון שהוא נבדל בערך לגמרי ואיננו מתלבש כלל וכלל בעולמות והוא הנק' פלא עליון כו' מפני שהוא מופלא ומובדל",[["4282","1","<b>שיר המעלות ממעמקי'</b>: הוא דרוש האחרון מסדרה של ד' מאמרים שבהם נתבאר מאמר ד\"ה להבין וכו' כי המצוה שנאמר ע\"י כ\"ק אדה\"ז בשנת תקס\"ו, ונדפס במאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקלה ואילך. ובשינויים באוה\"ת נצבים ע' א'רכט ואילך. ונאמר גם ע\"י כ\"ק אדמו\"ר מהר\"ש בראשית שנת תרכ\"ז ונדפס בסה\"מ תרכ\"ו ע' רמב ואילך (עם הוספה, וקיצור נדפס שם ע' רנד ואילך).\nבמאמרי אדה\"ז תקס\"ה ח\"ב ע' תתעו נדפס גוף המאמר שפתיחתו היא כי המצוה הזאת והוא משבת פ' נצבים תקס\"ה (ומקבילו נדפס ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380900\" data-slug=\"likkutei-torah\" data-id=\"4001380900\">לקו\"ת נצבים מה, ב</a>). וביאור ראשון (שפתיחתו היא להבין שרשי הדברים) נדפס שם בע' תתפג. וביאור שני (שפתיחתו היא להבין וכו' ע\"פ כי המצוה) נדפס שם ע' תתקלה. ומאמר דידן מיוסד על ביאור שני כנ\"ל.\nמאמר דידן מבאר סיום המאמר דתקס\"ו ומתחיל מפ\"ה — ד\"ה לא נפלאת (ע' תתקמו-תתקנ שבמאמרי אדה\"ז תקס\"ה הנ\"ל).\nהנחה מדרוש זה מכ\"ק אדמו\"ר מהורש\"ב נדפסה להלן בחלק ההנחות. התאריך המופיע בריש המאמר הועתק משם.\nהפתיחה והגהה אחת נכתב בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש. הבא בתוך חצאי עיגול בפנים המאמר הם הגהות מכ\"ק אדמו\"ר מהר\"ש פרט באם צויין אחרת.\nהדרוש נמצא גם בכת\"י מעתיקים והם: א 134 (לא נסמנו עמודים) בכותרת: בס\"ד ש\"ש תרל\"ט. ב 545 ע' קמח בכותרת: בס\"ד ש\"ש. ג 363 רעח, ב בכותרת: בס\"ד ש\"ש תרל\"ט. ד 545 ע' קמח בכותרת: בס\"ד ש\"ש. ה 690 ע' קיח בכותרת: בס\"ד ש\"ש תרל\"ט. ו 2083 כת\"י הר\"ש סופר. ז מאסקבא 127 ע' 25 בכותרת: בס\"ד ש\"ש."],["4283","2","<b>שיר המעלות ממעמקי' קראתיך ה'</b>: תהלים קל, א."],["4284","3","<b>נת' בד\"ה וכ\"מ שהוא שופט צדק</b>: בתחילתו — נדפס לפני ד\"ה זה."],["4285","4","<b>לגבי</b>: אוצ\"ל: לגבי'."],["4286","5","<b>עושה פלא</b>: בשלח טו, יא."],["4287","6","<b>לא</b>: מכאן הוא לשון מאמרי אדה\"ז תקס\"ה כאן ע' תתקמו. סה\"מ תרכ\"ו כאן ע' רמט: פ\"ו."],["4288","7","<b>לא נפלאת היא ממך</b>: נצבים ל, יא."],["4289","8","<b>עתיק נק' בשם פלא עליון</b>: ראה גם (בנוסף להדרושים שבהערה 1) מאמר ד\"ה כי המצוה תרע\"ג (סה\"מ תרע\"ב — תרע\"ו ע' רחצ). ד\"ה ואשה אחת תשמ\"ו ס\"ד (קונט' כ\"ף מ\"ח תש\"נ — סה\"מ מלוקט ד ע' מו). ד\"ה וקבל היהודים תשל\"ח ס\"א (סה\"מ מלוקט א ע' שיז). ולהעיר מלעיל המשך כי תשא ספ\"א ובהערות 24-5."],["4290","9","<b>נורא תהלות</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן. ובמאמרי אדה\"ז תקס\"ה כאן: ליתא."],["4291","10","<b>(שבחי'</b>: הסוגר נמצא גם בסה\"מ תרכ\"ו כאן."],["4292","11","<b>כי יפלא ממך דבר</b>: פ' שופטים יז, ח."]]],[2000450403,"לגמרי כו'. וזהו בחי' עתיק שנעתק לגמרי מיומין דאצי'<sup data-n=\"4293\">12</sup> כנ\"ל<sup data-n=\"4294\">13</sup>, ובחי' א\"א הוא בחי' מקיף תחתון ואינו נק' פלא עליון כי אינו מופלא ומובדל לגמרי שהרי הוא בא מן ההעלם לגילוי אור להיות בבחי' יניקה לאו\"א כנ\"ל<sup data-n=\"4295\">14</sup> והגם שהוא להן לבחי' מקיף ג\"כ אבל אינו נק' פלא בענין בחי'<sup data-n=\"4296\">15</sup> ההפלאה וההבדלה לגמרי מכל וכל שהרי מ\"מ מתלבש בחו\"ב בבחי' מקיף ופנימי משא\"כ בחי' עתיק שהוא נעתק לגמרי כנ\"ל.\n<b>וזהו</b> פי' לא נפלאת היא ממך להיות בבחי' פלא עליון הנק' עתיק יומין הנ\"ל וגם לא רחוקה היא להיות בבחי' א\"א שנק' רחוק בלבד וכמ\"ש אמרתי אחכמה והיא רחוקה ממני<sup data-n=\"4297\">16</sup> פי' על אור מקיף דחכ' קאמר אחכמה בחי' אלף דחכמה כמאמר אאלפך חכ'<sup data-n=\"4298\">18</sup> כו' והוא בהיפוך אתוון דפל\"א<sup data-n=\"4299\">17</sup> כי פי' אלף אאלפך חכמה היינו ענין יציאת ההעלם לבוא לידי גילוי בחכ' וכמאמר הנ\"ל<sup data-n=\"4300\">19</sup> דאבא יונק ממזל הח'<sup data-n=\"4301\">20</sup> וכו', אך שהיא רחוקה מן החכ' בבחי' מקיף ג\"כ וזהו אמרתי אחכמה והיא רחוקה ממני למעלה מן החכ' כו' ומ\"מ איננה רחוקה לגמרי להיות מובדל ומופלא כמו בחי' עתיק כו', והוא חוזר ומפרש הדבר הזה באמרו לא בשמים היא<sup data-n=\"4302\">21</sup> כו' ולא מעבר לים היא<sup data-n=\"4303\">22</sup> כו' פי' אלו הב' בחי' דפלא ורחוק שהן בחי' ע\"י וא\"א נק' שמים ומעבר לים כו' דהנה השמים הגשמי' הרי אינן נראי' כלל<sup data-n=\"4304\">23</sup> ומה שנראים לעין אינו אלא זהרורית האוירים כידוע, אבל לא מעצם השמים כו'. וזהו משל להבין בענין שמים עליונים שהוא בחי' אור מקיף העליון דעתיק שנק' פלא כנ\"ל, דלפי שאינו מושג ונראה כלל כנ\"ל ע\"כ נק' שמים וכמשל השמים המקיפים מכל צד בשוה כו', ובחי' מקיף השני דבחי' א\"א הנ\"ל הוא הנק' מעבר לים כו'. דהנה ידוע שהחכ' נק' ים<sup data-n=\"4305\">24</sup> ומעבר לים היינו מעבר לים החכ' והוא בחי' אור מקיף דחכ' שלמעלה מן החכ' וכנ\"ל בפי' הפסוק אמרתי אחכמה והיא רחוקה ממני כו', וא\"כ היינו ב' בחי' הנ\"ל שאומר לא נפלאת היא ולא רחוקה היא אלא שחוזר ומפרש אותן יותר והוא באמרו לא בשמים ולא מעבר לים כו', ומה שאו' לא נפלאת היא ממך כו' הכוונה בכלל כך הוא שממך דוקא לא נפלאת ולא רחוקה כו', אבל למעלה הרי הן בחי' ב' מקיפים",[["4293","12","<b>עתיק שנעתק לגמרי מיומין דאצי'</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540202\" data-slug=\"torat-chaim\" data-id=\"2300540202\">תו\"ח וארא ח\"א נג, רע\"א</a>. וש\"נ."],["4294","13","<b>כנ\"ל</b>: במאמר ד\"ה אנכי אנכי על יד הערה 57."],["4295","14","<b>כנ\"ל</b>: בד\"ה אנכי אנכי שם על יד הערה 60 ואילך."],["4296","15","<b>בחי'</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן. ובמאמרי אדה\"ז תקס\"ה כאן: כי."],["4297","16","<b>אמרתי אחכמה והיא רחוקה ממני</b>: קהלת ז, כג."],["4298","18","<b>אאלפך חכ'</b>: ראה גם לעיל המשך כי תשא פ\"ז ובהערה 183."],["4299","17","<b>אלף. . בהיפוך אתוון דפל\"א</b>: ראה ת\"ז ת\"ע (קלה, א). הקדמת הראב\"ד לס\"י נתיב הא'."],["4300","19","<b>הנ\"ל</b>: במאמר ד\"ה אנכי אנכי על יד הערה 60."],["4301","20","<b>דאבא יונק ממזל הח'</b>: ראה זהר אד\"ז האזינו רפט, ב. ע\"ח שער הכללים פ\"ה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540755\" data-slug=\"torat-chaim\" data-id=\"2300540755\">תו\"ח שמות ח\"א לו, א</a> הערה 455. לעיל המשך וידבר וגו' ויצוום פי\"ב ובהערה 216."],["4302","21","<b>לא בשמים היא</b>: נצבים ל, יב."],["4303","22","<b>ולא מעבר לים היא</b>: שם שם, יג."],["4304","23","<b>השמים. . אינן נראי' כלל</b>: ראה גם לקמן (בחלק ההנחות) בהנחה ד\"ה ב\"ה אלקי ישראל ובהערה 39."],["4305","24","<b>שהחכ' נק' ים</b>: ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה פי' פתחה בחכמה ובהערה 58 שם."]]],[2000450404,"עליונים שנק' ע\"י וא\"א ונק' פלא ורחוק וכו' אלא שאצלך אינם נקראים פלא ורחוק, וזהו לא נפלאת היא ממך דוקא כו', (והיינו<sup data-n=\"4306\">25</sup> מפני כי האדם כלול מכל הפרצופים כנ\"ל<sup data-n=\"4307\">26</sup> בפי' נעשה אדם שגם פרצוף הכתר בכלל, וגם כי אדם אדמה לעליון<sup data-n=\"4308\">27</sup> ולכן ממך לא נפלאת כו' ולא רחוקה כו').\n<b>וביאור</b> הדברים, הנה יובן עפ\"י הנ\"ל במה שהאדם הוא בחי' כוללת הכל ובחי' כללות כל ההשתלשלו' העליונה כלולים בו כו', וא\"כ יש בו גם מקיפי' העליונים ולמעלה מהן ג\"כ שהרי אם ביכולתו להמשיך בחי' ב' מקיפי' דע\"י ודא\"א כנ\"ל בענין התשובה ממעמקים כו' וא\"כ<sup data-n=\"4309\">28</sup> בהכרח שיהי' שרשו למעלה מבחי' כללות כל ההשתל' המקיפי' הנ\"ל אלא גבוה גם מהם וע\"כ ביכולתו להמשיך אותן<sup data-n=\"4310\">29</sup> כו' (וזהו<sup data-n=\"4311\">30</sup> מצד כי פי' אדם הוא אדמה לעליון כו', וזהו ג\"כ מה שהאדם העושה תשובה נק' בעל תשובה פי' בעל הוא לשון מארי'<sup data-n=\"4312\">32</sup> ורבון<sup data-n=\"4313\">31</sup>, והיינו להיותו למעלה ממדריגת התשובה לכן ע\"י תשובתו מעורר ב\"פ אנכי ב' מקיפי' הנ\"ל כו'). וא\"כ הגם שב' מקיפים הנ\"ל נקראו בשם פלא ורחוק לגבי הנאצלי' מ\"מ לגבי האדם שכוללם כו' אינן נקראין כלל בשם פלא ורחוק כי לא יפלא אורות המקיפים<sup data-n=\"4314\">33</sup> ממנו ולא יורחק ממנו כלל להיות כי ניתן לאדם שיהי' בהתגלות אצלו גם פלא העליון מטעם שהוא בחי' כוללת הכל וכמ\"ש נעשה אדם<sup data-n=\"4315\">34</sup> וכנ\"ל בענין התשובה לפי שעל ידו דוקא נעוץ תחב\"ס<sup data-n=\"4316\">35</sup> כו', וזהו לא נפלאת היא ממך, ממך דוקא לא נפלאת וכך רצונו לומר המצוה של התשובה אשר אנכי מצוך<sup data-n=\"4317\">36</sup> כו' להיותה גורמת להיות בחי' ההתכללו' עד רום המעלות בבחי' הב' שמות מ\"ה וב\"ן כו' וא\"כ ממילא א\"א שיפלא ממך כי באדם גם בחי' ע\"י וא\"א יהי' התגלות אורן וכנ\"ל דאדם אדמה לעליון ממש כו' וכמאמר לפניך נגלו כל תעלומות<sup data-n=\"4318\">37</sup> כו' (והיינו<sup data-n=\"4319\">38</sup> שמפרש לא בשמים היא לאמר מי יעלה לנו השמימה כו', שהתשובה הרי קדמה לכל ההשתל' כו' דמ\"ה וב\"ן בלבד הוא שיצאו מעצמות אור א\"ס ומאחר שפי' תשובה הוא תשוב ה\"י כנ\"ל<sup data-n=\"4320\">39</sup> הרי האור",[["4306","25","<b>(והיינו</b>: הסוגר נמצא גם בסה\"מ תרכ\"ו כאן ע' רנ."],["4307","26","<b>כנ\"ל</b>: במאמר ד\"ה להבין וכו' כי המצוה בתחילתו."],["4308","27","<b>אדם אדמה לעליון</b>: ישעי' יד, יד. ראה עבוה\"ק ח\"א חלק היחוד פי\"ז. לעיל מאמר ד\"ה להבין כו' כי המצוה ובהערה 34."],["4309","28","<b>וא\"כ</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן. ובמאמרי אדה\"ז תקס\"ה כאן ע' תתקמז: א\"כ."],["4310","29","<b>אותן</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן. ובמאמרי אדה\"ז תקס\"ה כאן: אותו."],["4311","30","<b>(וזהו</b>: הסוגר נמצא גם בסה\"מ תרכ\"ו כאן."],["4312","32","<b>מארי'</b>: בסה\"מ תרכ\"ו כאן: מארא."],["4313","31","<b>בעל תשובה. . ורבון</b>: ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה וכל מאמינים ובהערה 38."],["4314","33","<b>אורות המקיפים</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן. ובמאמרי אדה\"ז תקס\"ה כאן: אורם."],["4315","34","<b>נעשה אדם</b>: בראשית א, כו. ראה גם לעיל במאמר רד\"ה להבין וכו' כי המצוה."],["4316","35","<b>נעוץ תחב\"ס</b>: ראה ס\"י פ\"א, מ\"ז. סידור שער הת\"ת צח, ג ואילך. סה\"מ תר\"ל ע' שכ. וראה גם לעיל מאמר ד\"ה ומקנה רב על יד הערה 27."],["4317","36","<b>אשר אנכי מצוך</b>: נצבים ל, יא."],["4318","37","<b>לפניך נגלו כל תעלומות</b>: מוסף לר\"ה בברכת זכרונות."],["4319","38","<b>(והיינו</b>: הסוגר נמצא גם במאמרי אדה\"ז תקס\"ה כאן."],["4320","39","<b>תשובה הוא תשוב ה\"י כנ\"ל</b>: ראה לעיל מאמר ד\"ה וכל מאמינים ובהערה 18."]]],[2000450405,"חוזר לקדמותו ממש והיינו לקדמות דאור א\"ס כמו קודם שיצאו ב' שמות מחולקי' עכ\"פ כנ\"ל (ועפ\"ז יובן איך ע\"י ממעמקי' נמשך שיומשך מעצמיות אוא\"ס שלמעלה גם מבחי' מ\"ה וב\"ן שז\"ע קראתיך לעצמיות אוא\"ס שמשם יומשך ש' הוי' מחדש כו'), וא\"כ בהכרח שאין המצוה הזאת דתשו' נמצאת לא בשמים ולא מעבר לים כו' כי למעלה היא גם מהם מטעם זה ובאדם הרי היא נמצאת מטעם הנ\"ל (דאדם<sup data-n=\"4321\">40</sup> אדמה לעליון שלמעלה מהשתלשלו' כו') וע\"כ ממך דוקא לא נפלאת ולא למעלה דלמעלה נפלאת היא ורחוקה היא (גם<sup data-n=\"4322\">41</sup> מבחי' שמים וים כו') מטעם הנ\"ל<sup data-n=\"4323\">42</sup>.\n<b>כי</b><sup data-n=\"4324\">43</sup> קרוב אליך הדבר מאד<sup data-n=\"4325\">44</sup> בפיך ובלבבך לעשותו, פי' כי קרוב כו' ענין נתינת טעם הוא למה שקדם במאמרו בהפלגת מעלת האדם איך שניתן לו גם כל בחי' מקיפים עליוני' הגבוהים מאד נעלה כו' שלא יהי' אצלו בחי' הסתר והפלאה כו' שכ\"ז לא זכה האדם מצד עצמו ממש אע\"פ שהוא בחי' כוללת כי לא נוצר האדם בשביל עצמו בלבד אלא כדי לתקן דבר נוצר, והוא שאמר כי קרוב אליך הדבר לעשותו בה\"א הידיעה שהוא בנין ותיקון הנוק' שנק' דבר<sup data-n=\"4326\">45</sup> וכמ\"ש דבר מלך שלטון<sup data-n=\"4327\">46</sup> כו'. ולהבין ביאור הדברים וגם מה שאמר כי קרוב אליך הדבר כו' מהו בחי' ההתקרבות של אדם לאותו הדבר כו' ובמשמעות הכתוב הוא שכל זה זכה משום שהדבר הוא אצלך ובחלקך הוא ע\"כ ניתן לך כ\"ז כו', הנה יש להקדים תחלה ענין א' בהיות ידוע בפי' אשר ברא אלקי' לעשות<sup data-n=\"4328\">47</sup> דפי' לעשות הוא לתקן<sup data-n=\"4329\">48</sup> וקאי אאלקי' דסמיך לי' והוא לעשותו לתקן<sup data-n=\"4330\">49</sup> ש' אלקי'<sup data-n=\"4331\">*50</sup> כו', והטעם שצריך תיקון הוא לפי שידוע בע\"ח דכל אורות הפרצופי' העליונים נתבררו מלבד בחי' מ\"ן דנוק' שלא נתברר עדיין והוא בחי' הגבורות דש' אלקי' דנוק' ולזה נוצר האדם שיתקן ויברר אותן כו', והוא מפני ששרש הנשמה במ\"ן דנוק' הוא כידוע בפי' כל ישראל בני מלכים<sup data-n=\"4332\">50</sup> הן ששרש נשמתם מבחי' מ\"ן דמל' דאצי'",[["4321","40","<b>(דאדם</b>: הסוגר נמצא גם בסה\"מ תרכ\"ו כאן ע' רנא."],["4322","41","<b>(גם</b>: הסוגר נמצא גם בסה\"מ תרכ\"ו כאן."],["4323","42","<b>הנ\"ל</b>: בסה\"מ תרכ\"ו כאן: הנ\"ל). ועד\"ז הוא במאמרי אדה\"ז תקס\"ה כאן ע' תתקמח."],["4324","43","<b>כי</b>: בסה\"מ תרכ\"ו נרשם כאן: פ\"ז. במאמרי אדה\"ז תקס\"ה נרשם כאן: פ\"ו."],["4325","44","<b>כי קרוב אליך הדבר מאד</b>: נצבים ל, יד."],["4326","45","<b>הנוק' שנק' דבר</b>: ראה (בנוסף להערה 1) פרדס שעה\"כ שכ\"ג, פ\"ד מערכת דבר. לקמן מאמר ד\"ה מה יפו על יד הערה 33. ד\"ה שלש רגלים (בהוספה) על יד הערה 40. מאמרי אדה\"ז תקס\"ח ח\"א ע' שג. מאמרי אדה\"א דברים ח\"ב ע' תשא."],["4327","46","<b>דבר מלך שלטון</b>: קהלת ח, ד. ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרצג."],["4328","47","<b>אשר ברא אלקי' לעשות</b>: בראשית ב, ג."],["4329","48","<b>לעשות הוא לתקן</b>: ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540179\" data-slug=\"torat-chaim\" data-id=\"2300540179\">תו\"ח בשלח ח\"א קלט, ד</a> בשם הע\"ח. בסה\"מ תרכ\"ח בתחילתו: בזהר ובמד\"ר. ראה ב\"ר פי\"א, ו ובפרש\"י שם. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תתסח. דברים ח\"ד ע' א'רט. סה\"מ תרצ\"ז ע' 214."],["4330","49","<b>לעשותו לתקן</b>: במאמרי אדה\"ז תקס\"ה כאן: לעשות ולתקן. בסה\"מ תרכ\"ו (מהדורת תשמ\"ט) כאן: לעשות לתקן."],["4331","*50","<b>לתקן ש' אלקי'</b>: ראה גם הוספות לכתר שם טוב (קה\"ת — מהדורת תשנ\"ט) ע' יב. סה\"מ תרצ\"ט ע' 72. מאמר ד\"ה בראשית ברא תש\"כ (סה\"מ תש\"כ ע' 19 וע' 25). שיחות קודש תשי\"א ע' 272. יומן חורף תרצ\"ה ווין (רשימות חוב' קעט ע' 5 ואילך). שיחת כ\"ק אדמו\"ר שמחת ביה\"ש תש\"ז."],["4332","50","<b>כל ישראל בני מלכים</b>: שבת סז, א. ראה גם (בנוסף להערה 1) שע\"ת מ, ב ובהערה 9."]]],[2000450406,"וע\"כ ביכולת הנשמה אלקי' דוקא לתקן ולעשות לשם אלקי' דנוק' שלא נתבררה עדיין כו', וענין הבירור של מ\"ן דנוק' העיקר הוא שיהי' ממנה בנין שלם ולהיות עומדת בבחי' פב\"פ באצי' כידוע, כי הנה ידוע דג' מדרגות יש במל' דאצי'<sup data-n=\"4333\">51</sup>, הא' כאשר היא בתכלית ההסתר מסותרת ונעלמת בבי\"ע ותתן טרף לביתה<sup data-n=\"4334\">52</sup> כו', ובכל חצות לילה היא עולה מבי\"ע<sup data-n=\"4335\">53</sup> ונעשית למעלה בבחי' נקודה תחת יסוד ז\"א<sup data-n=\"4336\">54</sup> כו', ואח\"כ בשחר עד תפלת ש\"ע עומדת בבחי' אב\"א ובש\"ע עומדת בבחי' פב\"פ וזהו תכלית עלייתה כו' וזהו עיקר הבירור שלה וכמ\"ש במ\"א באריכות, וזהו שאמר כי קרוב אליך הדבר מאד, פי' הדבר הוא בנין ותיקון מ\"ן הנוק' שנק' הדבר והוא קרוב אליך להיות כי שרש נשמות ישראל הוא ג\"כ מקום זה כנ\"ל, וגם פי' הפשוט שקרוב אליך הכוונה הוא על התיקון וכדמסיים לעשותו שקרוב אליך תיקון של הדבר לעשותו ולתקנו כו', גם<sup data-n=\"4337\">55</sup> מובן מטעם הנ\"ל דאדם הוא בחי' כוללת<sup data-n=\"4338\">56</sup> עד שהוא למעלה מן הכל וכפי' אדם אדמה לעליון כו' וכנ\"ל וע\"כ ביכולתו דוקא לעשות ולתקן בנין ותיקון מ\"ן דנוק' ולא בזולתו, וזהו כי קרוב אליך אליך דוקא קרוב מאד כי לא בשמים היא ולא מעבר לים היא מטעם הנ\"ל אלא ממך דוקא הוא שלא נפלאת היא כנ\"ל מפני שהוא כלול מהכל כמ\"ש נעשה אדם כו'.\n<b>בפיך</b> ובלבבך לעשותו<sup data-n=\"4339\">57</sup>, הנה בפיך ובלבבך זו תורה ותפלה בפיך זהו ע\"י לימוד התורה בדבור בפה ובלבבך הן בחי' ב' לבבות הנ\"ל דהיינו ב' האהבות דבכל נפשך ובכל מאדך<sup data-n=\"4340\">58</sup> כו', ובשתים אלה נבנה בנין הנוק' ונתקן תיקון שלה בבחי' המ\"ן שלה שלא נתברר עדיין כנ\"ל וזהו פי' לעשות כנ\"ל. והנה ביאור איכות בנין ותיקון הנוק' ע\"י לימוד התו' בפיך, יובן בהקדים ענין מארז\"ל הידוע (תמיד דל\"ב ע\"ב)<sup data-n=\"4341\">59</sup> דכל העוסק בתורה בלילה שכינה<sup data-n=\"4342\">60</sup> כנגדו כו', דלכאו' אינו מובן מהו שאומר בלילה דוקא ואם זה מוכרח ממשמעות הפסוק שלמדו מאמר זה והוא דכתי'",[["4333","51","<b>דג' מדרגות יש במל' דאצי'</b>: ראה ע\"ח שער מיעוט הירח של\"ו, פ\"א. ביאוה\"ז בלק ק, ד ואילך. מאמרי אדה\"ז על ענינים ע' ריג ואילך־ ע' ריז ואילך־ ע' רכא ואילך. תקס\"ד ע' קמב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080300\" data-slug=\"or-hatorah-hb\" data-id=\"8160080300\">אוה\"ת ויקרא כרך א ע' ש</a>. הנסמן בהערה 1. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 39. וראה גם לקו\"ב — לשער היחוד — אות מז ע' 388."],["4334","52","<b>ותתן טרף לביתה</b>: משלי לא, טו. ראה גם לעיל מאמר ד\"ה ומקנה רב ובהערה 151."],["4335","53","<b>חצות לילה. . מבי\"ע</b>: ראה גם (בנוסף להערה 1) בפיסקא הבאה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381256\" data-slug=\"likkutei-torah\" data-id=\"4001381256\">לקו\"ת שה\"ש לא, ד</a>. מאמרי אדה\"ז על ענינים שם. תקס\"ה ח\"א ע' שעו. ס\"ע שצ ואילך. סה\"מ תרל\"ב ח\"א ע' רעג. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 48."],["4336","54","<b>נקודה תחת יסוד ז\"א</b>: ראה זהר בלק קצא, א ובהגהת מהרח\"ו שם. ביאוה\"ז שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' קיא וע' קיב. ענינים שם. שע\"ת קא, ג ובהערה 22. הנסמן בהערה 1."],["4337","55","<b>גם</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן ע' רנב. ובמאמרי אדה\"ז תקס\"ה כאן: ג\"כ."],["4338","56","<b>כוללת</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן. ובמאמרי אדה\"ז תקס\"ה כאן: כללות."],["4339","57","<b>בפיך ובלבבך לעשותו</b>: נצבים ל, יד."],["4340","58","<b>הנ\"ל. . דבכל נפשך ובכל מאדך</b>: ואתחנן ו, ה. לעיל מאמר ד\"ה וכל מאמינים על יד הערה 48."],["4341","59","<b>(תמיד דל\"ב ע\"ב)</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן. ובמאמרי אדה\"ז תקס\"ה כאן ע' תתקמט: ליתא."],["4342","60","<b>שכינה</b>: במאמרי אדה\"ז תקס\"ה כאן: הקב\"ה יושב וקורא ושונה."]]],[2000450407,"קומי רוני<sup data-n=\"4343\">61</sup> בלילה<sup data-n=\"4344\">62</sup> דוקא שאז הוא נוכח פני הוי'<sup data-n=\"4345\">63</sup> דוקא ולמה לא ביום ג\"כ כו'. אך הענין הוא כידוע בכהאריז\"ל<sup data-n=\"4346\">64</sup> דבלילה דוקא יורדת הנוק' בעולמות הנפרדי' להחיותם כו' וכמ\"ש ותקם בעוד לילה ותתן טרף לביתה כו' ואז היא מוסתרת ומלובשת בלבושי' תחתונים מאד וכמ\"ש יונתי בחגוי הסלע<sup data-n=\"4347\">65</sup> בסתר המדרגות כו' ובכל חצות לילה חוזרת היא ועולה למעלה בבחי' העלאת מ\"ן דרפ\"ח ניצוצים<sup data-n=\"4348\">66</sup> שביררה מן העולמות כו' ובעלות המ\"ן שלה אזי שעת הכושר דוקא לירידת בחי' המ\"ד מלמעלה לברר המ\"ן שלה וכידוע שזהו תכלית המ\"ן כשמתבררת בירידת המ\"ד עלי' ומבררה כו'. וענין הבירור של המ\"ד הוא ענין בחי' גילוי אלקות שמתגלה במ\"ן כו', אע\"פ<sup data-n=\"4349\">67</sup> שהמ\"ן עולה למעלה כמו מס\"נ של נשמות הצדיקים וכיוצא, מ\"מ עדיין א\"א שיהי' בהם גילוי אלקות ממש מצד בחי' גשמיותם אלא כדי שיאיר בהם אור האלקי כמו שהוא הרי צריך שיתהפכו ממהות למהות אחר וזהו ענין הבירור של המ\"ן ואין זה אלא ע\"י ההארה עליונה שהוא בחי' המ\"ד בהגלות נגלות עליהם אזי מתבררים ונתהפכו להיות בבחי' אלקות ממש ויאיר אז אור האלקי ממש בהם וכמשל הפתילה שהוכנה להדלקה עד שהאור דולק בה יפה כו'. ועד\"ז<sup data-n=\"4350\">68</sup> מ\"ן דנוק' למטה שמ\"ד מבררים ונעשה ולד כו' וכמ\"ש במ\"א (וע'<sup data-n=\"4351\">69</sup> בת\"א בד\"ה והנה אנחנו מאלמי' אלומי'<sup data-n=\"4352\">70</sup> בענין בירור השבטי' ובירור שני דיוסף יעו\"ש). וגם כאן בענין עסק התורה בלילה דוקא הענין כך הוא שבעלות המ\"ן דנוק' בלילה דוקא מטעם הנ\"ל אזי בחי' המוחין שבז\"א דאצי' שנתלבשו בחכ' שבתורה כידוע דאוריי' מחכ' נפקת<sup data-n=\"4353\">71</sup> הן בחי' מ\"ד דז\"א דאצי' שמבררי' המ\"ן כו' (ובזה<sup data-n=\"4354\">72</sup> יובן מ\"ש בזהר בכ\"ד שבפלגות לילה<sup data-n=\"4355\">74</sup> קוב\"ה אתי לאשתעשע<sup data-n=\"4356\">73</sup> עם צדיקייא בגנתא דעדן והיינו לפי שבחצות לילה הוא עליית מ\"ן דב\"ן דמל', ולכן אז יורד המשכת מ\"ד דז\"א שז\"ע קוב\"ה<sup data-n=\"4357\">75</sup> ע\"י לימוד התו' שלומד עם הצדיקים שהם בחי' מס\"נ של הנשמות כנ\"ל וממשיך מ\"ד לברר המ\"ן דמל' כו').",[["4343","61","<b>קומי רוני בלילה</b>: איכה ב, יט."],["4344","62","<b>בלילה</b>: ראה מאמרי אדה\"ז תקס\"ה כאן בשולי היריעה."],["4345","63","<b>הוי'</b>: כ\"ה גם במאמרי אדה\"ז תקס\"ה ובסה\"מ תרכ\"ו כאן. ובאיכה שם: אדני. וראה לקמן הערה 80."],["4346","64","<b>בכהאריז\"ל</b>: ראה גם פע\"ח שער תיקון חצות שי\"ז, פ\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380321\" data-slug=\"likkutei-torah\" data-id=\"4001380321\">לקו\"ת במדבר ג, סע\"ב</a> ואילך."],["4347","65","<b>יונתי בחגוי הסלע</b>: שה\"ש ב, יד."],["4348","66","<b>דרפ\"ח ניצוצים</b>: ראה ע\"ח שער רפ\"ח שי\"ח, פ\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151537\" data-slug=\"likkutei-sichot\" data-id=\"1300151537\">לקו\"ש וישב כרך טו ע' 524</a> (אג\"ק שלו ח\"ב ע' כא). וש\"נ. מאמרי אדה\"א דברים ח\"ד ע' א'קעד. וש\"נ."],["4349","67","<b>אע\"פ</b>: במאמרי אדה\"ז תקס\"ה־ סה\"מ תרכ\"ו כאן: כי אע\"פ."],["4350","68","<b>ועד\"ז</b>: שם: ועד\"מ."],["4351","69","<b>(וע'</b>: הסוגר נמצא גם בסה\"מ תרכ\"ו כאן."],["4352","70","<b>בת\"א בד\"ה והנה אנחנו מאלמי' אלומי'</b>: וישב כח, א ואילך."],["4353","71","<b>דאוריי' מחכ' נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["4354","72","<b>(ובזה</b>: הסוגר נמצא גם בסה\"מ תרכ\"ו כאן ע' רנג."],["4355","74","<b>לילה</b>: בסה\"מ תרכ\"ו כאן: ליליא."],["4356","73","<b>שבפלגות. . לאשתעשע</b>: ראה זהר אחרי סז, ב. לך עז, א."],["4357","75","<b>דז\"א שז\"ע קוב\"ה</b>: ראה לקוטי הש\"ס להאריז\"ל ברכות ו, א. מאמרי אדה\"ז תקס\"ז ע' קכז. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316620002\" data-slug=\"or-hatorah-hb\" data-id=\"8316620002\">אוה\"ת בהר כרך ד ע' א'קמב</a> [ושם נדפס: בזח\"ג ואתחנן דרס\"ו ע\"ב. וכנצ\"ל: דרס\"ב ע\"ב]. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670350\" data-slug=\"torat-chaim\" data-id=\"2300670350\">תו\"ח נח סט, א</a> הערה 1."]]],[2000450408,"<b>וביאור</b> הדבר הוא שהרי אור א\"ס מתלבש בחכ'<sup data-n=\"4358\">76</sup> דוקא וע\"ד דוגמא בהלכה דשנים אוחזין<sup data-n=\"4359\">77</sup> וכיוצא הרי דבר ה' הוא וגילוי אור א\"ס ב\"ה, אך ענין ההלכה גשמיי' היא בכל עולם לפי ערך גשמיותו וצריך בירור ע\"י המ\"ד כנ\"ל, ומהו המ\"ד היינו מה שארז\"ל הקב\"ה<sup data-n=\"4360\">78</sup> יושב ושונה כנגדו, <sup data-n=\"4361\">79</sup> פי' הקב\"ה הוא בחי' מוחין דז\"א דאצי' כידוע ויושב ושונה ממש כנגדו לברר המ\"ן דנוק' שהוא דבור של ההלכה כו', והיינו שיושב ושונה עד שיהי' בה גילוי אור אלקי ממש כנ\"ל, וזהו שדקדקו זה המאמר מפסוק זה דקומי רוני בלילה כו' משום דבלילה היא קמה דוקא ומעלה מ\"ן ואז שפכי כמים לבך נוכח פני הוי'<sup data-n=\"4362\">80</sup> הוא הקב\"ה שיושב ושונה כנגדו לברר המ\"ן כנ\"ל והיינו פי' נוכח דהיינו שכינה כנגדו<sup data-n=\"4363\">81</sup> שאמרו (והוא<sup data-n=\"4364\">82</sup> ע\"ד שאמרו אין טיפה<sup data-n=\"4365\">83</sup> כו'), (ומה<sup data-n=\"4366\">84</sup> שבתמיד ארז\"ל שכינה כנגדו, ובמ\"א אמרו הקב\"ה קורא ושונה כנגדו, י\"ל שכינה היינו שכ\"ע בינה<sup data-n=\"4367\">85</sup> שמנה\"י דאימא נעשו מוחין לז\"א<sup data-n=\"4368\">86</sup>, וא\"כ ענינם אחד כו'). והנה המלאכים אמרו תנה הודך על השמים<sup data-n=\"4369\">87</sup> כו' כידוע ומשמעות הכתוב שהמלאכים ביקשו את התורה<sup data-n=\"4370\">88</sup> שילמדו אותה בדיבור כמו שניתנה לנו, והענין הוא שהיו רוצים שגם על ידם יהי' המשכות מ\"ד לברר מ\"ן כנ\"ל בעסקם בתורה בדבור<sup data-n=\"4371\">89</sup> פ' בראשית וכיוצא, אמנם באמת לא היו<sup data-n=\"4372\">90</sup> גילוי המשכת המ\"ד כלל על ידם והיינו שלא הי' הקב\"ה יושב ושונה כנגדם כלל כשהיו שונים דבר ההלכה כו', והטעם הוא לפי שהמלאכי' הן מבחי' חיצוני' העולמות<sup data-n=\"4373\">91</sup> והוא מבחי' זווג נשיקין כמ\"ש בע\"ח וא\"כ אינן אלא",[["4358","76","<b>אור א\"ס מתלבש בחכ'</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a> (ובמ\"מ הגהות והע\"ק שם). פל\"ה בהג\"ה (ובמ\"מ הגהות והע\"ק שם). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380365\" data-slug=\"likkutei-torah\" data-id=\"4001380365\">לקו\"ת במדבר יד, ב</a> [ושם מציין: ”בע\"ח שער מ\"ז פ\"ג\" ולפנינו הוא פ\"ב ”ושער ב במה\"ב פ\"א פ\"ג\" ולפנינו הוא בשער סדר אצי' ש\"ג]. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540658\" data-slug=\"torat-chaim\" data-id=\"2300540658\">תו\"ח שמות ח\"א ז, ד</a> הערה 333."],["4359","77","<b>דשנים אוחזין</b>: ריש ב\"מ."],["4360","78","<b>הקב\"ה</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן. ובמאמרי אדה\"ז תקס\"ה כאן: דהקב\"ה."],["4361","79","<b>הקב\"ה יושב ושונה כנגדו</b>: ראה תדא\"ר רפי\"ח. מאמרי אדה\"א דברים ח\"ב ע' שפז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540132\" data-slug=\"torat-chaim\" data-id=\"2300540132\">תו\"ח וארא ח\"א נח, ג</a>. וש\"נ."],["4362","80","<b>הוי'</b>: כ\"ה גם במאמרי אדה\"ז תקס\"ה ובסה\"מ תרכ\"ו כאן. אוה\"ת נצבים כאן ע' א'רלח ובאיכה שם: אדני. וראה לעיל הערה 63."],["4363","81","<b>שכינה כנגדו</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן. ובמאמרי אדה\"ז תקס\"ה כאן ע' תתקנ: כנגדו."],["4364","82","<b>(והוא</b>: הסוגר נמצא גם במאמרי אדה\"ז תקס\"ה כאן."],["4365","83","<b>אין טיפה</b>: ראה תענית כה, ב [לפי גי' הרוקח סשע\"ז]. זהר רע\"מ פינחס רמז, ב. מאמרי אדה\"א הנחות תקע\"ז ע' רכב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550174\" data-slug=\"torat-chaim\" data-id=\"2300550174\">תו\"ח יתרו ח\"ב רעו, ב</a> הערה 44."],["4366","84","<b>(ומה</b>: הסוגר נמצא גם בסה\"מ תרכ\"ו כאן."],["4367","85","<b>שכ\"ע בינה</b>: ראה גם לעיל המשך חייב אדם לברך פ\"מ ובהערה 1781."],["4368","86","<b>שמנה\"י דאימא נעשו מוחין לז\"א</b>: ראה ע\"ח שער הכללים פ\"ד. שער הזווגים שט\"ו, פ\"א. פ\"ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' צ."],["4369","87","<b>תנה הודך על השמים</b>: תהלים ח, ב."],["4370","88","<b>שהמלאכים ביקשו את התורה</b>: שבת פח, ב."],["4371","89","<b>בתורה בדבור</b>: כ\"ה גם מאמרי אדה\"ז תקס\"ה כאן. ובסה\"מ תרכ\"ו כאן: בדבור בתורה."],["4372","90","<b>היו</b>: שם: הי'."],["4373","91","<b>שהמלאכי'. . חיצוני' העולמות</b>: ראה גם לעיל המשך חייב אדם לברך פ\"ב ובהערה 53."]]],[2000450409,"בחי' ומדרגה פרטיי' בלבד כו' ואין אור א\"ס שורה ומתגלה ע\"י דבר פרטי שאיננו שלם בבחי' השלימות כי הוא שלם בבחי' השלימות האמיתי', ואמנם בנפש האדם להיותו בבחי' השלימות והוא בחי' ההתכללות מכל המדרגות כנ\"ל ע\"כ נעשה אדם בצלמנו כו' ע\"י דוקא יהי' המשכת המ\"ד בעסקו בתורה כנ\"ל והיינו שהקב\"ה יהי' יושב ושונה כנגדו ממש כנ\"ל, וזהו מפני שהאדם הוא מבחי' פנימיות האצי' והוא מבחי' זווג גופני<sup data-n=\"4374\">92</sup> דזו\"נ כו', וזהו ויברא הוי' אלקי' את האדם<sup data-n=\"4375\">93</sup> כו' וכמ\"ש בעז\"ה<sup data-n=\"4376\">94</sup>.\n<b>ובכ\"ז</b> יובן יותר הטעם שאמר כי קרוב אליך הדבר כו' אליך דוקא שהוא לכנ\"י יש זה הכח והעוז לעשות ולתקן הדבר שהוא בירור המ\"ן דנוק' ע\"י המשכת המ\"ד כנ\"ל ולא לזולתם כמו המלאכים וכיוצא, וזהו בפיך ובלבבך לעשותו לדבר כו' והיינו כמאמרם שאתם קרוים אדם<sup data-n=\"4377\">95</sup> כו' וכתי' באדם דוקא ורדו בדגת הים ובעוף השמים<sup data-n=\"4378\">96</sup> כו'.",[["4374","92","<b>שהמלאכי'. . זווג נשיקין. . שהאדם. . זווג גופני</b>: ראה ע\"ח שער מ\"ן ומ\"ד של\"ח, דרוש ד. שער פנימיות וחיצוניות ש\"מ, דרוש י."],["4375","93","<b>ויברא ה' אלקי' את האדם</b>: כ\"ה גם במאמרי אדה\"ז תקס\"ה־ סה\"מ תרכ\"ו־ ואוה\"ת נצבים כאן — ראה בראשית א, כז. ב, ז. ע\"ח שער החשמל שמ\"א, ספ\"ג. לקמן (בחלק ההנחות) בהנחה ד\"ה כי המצוה ובהערה 14."],["4376","94","<b>בעז\"ה</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן. ובמאמרי אדה\"ז תקס\"ה ואוה\"ת נצבים כאן: בע\"ח — נסמן בהערה שלפנ\"ז."],["4377","95","<b>שאתם קרוים אדם</b>: יבמות סא, א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550513\" data-slug=\"torat-chaim\" data-id=\"2300550513\">תו\"ח יתרו ח\"ב רסב, א</a> ואילך ובהערה 285."],["4378","96","<b>ורדו בדגת הים ובעוף השמים</b>: בראשית א, כח."]]],[2000450410,"<h3>[וידבר כו' אלה הם מועדי]</h3>\n<b></b><b>בס\"ד יום א' של חגה\"ס ל\"ט</b>\n[יום א' של חגה\"ס]\n<b>וידבר</b><sup data-n=\"4379\">1</sup> ה' אל משה לאמר<sup data-n=\"4380\">3</sup>, דבר אל בנ\"י כו'<sup data-n=\"4381\">2</sup> מועדי ה' כו' אלה הם מועדי<sup data-n=\"4382\">4</sup>. וצ\"ל כפל הלשון מועדי הוי' ומועדי<sup data-n=\"4383\">5</sup>, וכמו\"כ צ\"ל מ\"ש במ\"א מצות הוי'<sup data-n=\"4384\">7</sup> ומצותי<sup data-n=\"4385\">6</sup><sup data-n=\"4386\">8</sup>, גם צ\"ל מ\"ש כאן ברוב המועדי' וכן בכמה מקומות בתורה<sup data-n=\"4387\">9</sup> אני הוי' שלשון זה לא יתכן לומר כ\"א על מי שהוא ידוע ונראה והוא אומר שאני הוא פ' הידוע כו', אבל מאחר ששם הוי' נעלם שאינו ידוע ענין בחי' שם הוי' מי הוא, וא\"כ מהו ענין שאומר ומודיע לנו שאני הוא הוי' שגם שם הוי' אינו ידוע לנו<sup data-n=\"4388\">10</sup>.",[["4379","1","<b>וידבר וכו' אלה הם מועדי</b>: מיוסד על מאמר ד\"ה זה מכ\"ק אדמו\"ר הצ\"צ, וממנו ישנם ד' הנחות והם: א) הנחת כ\"ק אדמו\"ר מהר\"ש נדפסה ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200123\" data-slug=\"or-hatorah-hb\" data-id=\"8159200123\">אוה\"ת אמור כרך ג ע' תתלז</a> [ההנחה נמצאת בבוך 2111 ע' סז בכותרת: ”ב\"ה א\"ח שבועו' ר\"ך\". וכן צ\"ל: ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200127\" data-slug=\"or-hatorah-hb\" data-id=\"8159200127\">אוה\"ת אמור</a> שם מהדורת תשנ\"ג בע' 42. סה\"מ תרכ\"ו ע'] ב) הנחה אחרת נדפסה באוה\"ת אמור כרך ד ע' א'עה [בכותרת: א\"ח שבועות שנת תר\"ך]. ג) הנחת ר' הלל יודפס בעזה\"י בספרו פלח הרמון פ' אמור. ד) ועוד הנחה נמצאת בבוך 2064 ע' עב [בכותרת: רשימות משנת כת\"ר אסרו חג של שבועות בליבווויץ].\nהמאמר שבאוה\"ת הנ\"ל מיוסד על מאמר ד\"ה זה משבת חה\"מ פסח שנדפס במאמרי אדה\"ז תקס\"ח ח\"א ע' קנט [נדפס גם באוה\"ת אמור כרך ג ע' תתמא]. ונאמר — המאמר שבאוה\"ת — ע\"י כ\"ק אדמו\"ר מהר\"ש בהוס' הגהה בסה\"מ תרכ\"ו ע' רעג. ובשינויים וכו' נדפס באוה\"ת דברים ע' א ואילך ושם הפתיחה אלה הדברים [וקיצורים נדפסו באוה\"ת אמור כרך ג ע' תתמז]. מאמר דידן נדפס גם בסה\"מ תרנ\"ו ע' רעא. וראה גם מאמר ד\"ה ולקחתם לכם תשכ\"ז.\nהנחה מדרוש זה מכ\"ק אדמו\"ר מהורש\"ב נדפסה לקמן בחלק ההנחות ומשם נעתקה הכותרת שבריש המאמר (פרט לתיבת בס\"ד).\nהמאמר נכתב בכת\"י הר\"ש סופר עם הגהות ותיקונים בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש. ונמצא גם בכת\"י מעתיק בבוך א 363 רפ, ב בכותרת: בס\"ד חה\"ס תרל\"ט."],["4380","3","<b>וידבר ה' אל משה לאמר</b>: אמור כג, א."],["4381","2","<b>וידבר ה'. . כו'</b>: התחלת המאמר בכת\"י הר\"ש סופר הוא: אלה מועדי, ומחקו כ\"ק אדמו\"ר מהר\"ש ותיקן כבפנים."],["4382","4","<b>דבר אל בנ\"י כו' מועדי ה' כו' אלה הם מועדי</b>: שם כג, ב."],["4383","5","<b>כפל הלשון מועדי הוי' ומועדי</b>: ראה גם (בנוסף להערה 1) לקמן בפיסקא ובכ\"ז. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490047\" data-slug=\"or-hatorah-hb\" data-id=\"8316490047\">אוה\"ת לך כרך ד ס\"ע תרצג</a> ואילך. אמור כרך א ע' שכז. דברים ע' ב. תצא ע' תתקלג. מאמר ד\"ה להבין ענין ההפרש בין שבת ליו\"ט בסופו (ד\"ה עוד מענין הנ\"ל — הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ) יודפס בעה\"י בפלח הרמון ויקרא. וש\"נ."],["4384","7","<b>מצות הוי'</b>: ויקרא ד, ב."],["4385","6","<b>מ\"ש במ\"א מצות הוי' ומצותי</b>: ראה גם (בנוסף להערה 1) לקמן בפיסקא ובכ\"ז. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380346\" data-slug=\"likkutei-torah\" data-id=\"4001380346\">לקו\"ת במדבר ט, ג</a>. סידור שער הציצית ד, ד. ה, ג. אמ\"ב שם פו, א. אוה\"ת שלח ע' תקפח. בלק כרך ה ע' א'תרסט [ובמהדורת תשנ\"ח ע' תתקנא]. תצא כרך ו ע' ב'שסד ואילך. פלח הרמון ויקרא שם. וש\"נ. המשך תער\"ב ח\"ג ע' א'תמא."],["4386","8","<b>ומצותי</b>: תולדות כו, ה. בשלח טז, כח. יתרו כ, ו. ועוד."],["4387","9","<b>כאן. . בתורה</b>: בכת\"י הר\"ש סופר: בסיום כל פרשה. ותיקן כ\"ק אדמו\"ר מהר\"ש כבפנים."],["4388","10","<b>אני הוי'. . שהוא ידוע. . אינו ידוע לנו</b>: לך טו, ז. ויצא כח, יג. ועוד. שמות ו, ב. ו. ז. ח. ועוד. ראה (בנוסף להערה 1) אוה\"ת יתרו יתרו ע' תתקיד וע' תתקלט. לעיל מאמר ד\"ה אנכי אנכי ובהערה *10. לקמן בהנחה כאן על יד הערה 13. ולפנ\"ז בהנחה ד\"ה אנכי אנכי ובהערה *15."]]],[2000450411,"<b>אך</b> הענין הוא דהנה הרמב\"ן בהקדמתו לפי' החומש<sup data-n=\"4389\">11</sup> הקשה מה<sup data-n=\"4390\">12</sup> שבכל הד' ספרים הראשונים<sup data-n=\"4391\">13</sup> נאמר וידבר הוי' אל משה ולא נא' מי הוא המדבר ומספר זאת דאם משה הוא המספר הי' לו לומר כמו כל הנביאים יחזקאל<sup data-n=\"4392\">14</sup> וירמי'<sup data-n=\"4393\">15</sup> שנא' בהם ויאמר ה' אלי<sup data-n=\"4394\">16</sup> ואשמע קול<sup data-n=\"4395\">17</sup>, ואראה ואפול על פני<sup data-n=\"4396\">18</sup>, ואם הקב\"ה הוא המספר הל\"ל ואומר אל משה או ודברתי אל משה כמו מ\"ש ונועדתי לך שם<sup data-n=\"4397\">19</sup> ודברתי אתך מעל כו' ובכל התורה נא' רק וידבר כו' ולא נא' מי הוא המספר זולת במשנה תורה נא' שמשה מפי עצמו אמרם<sup data-n=\"4398\">20</sup> כמ\"ש ואתפלל<sup data-n=\"4399\">21</sup> ואתנפל<sup data-n=\"4400\">22</sup> כו' ואתחנן אל ה'<sup data-n=\"4401\">23</sup>, רק בתחלת ספר משנה תורה נא' אלה הדברים אשר דיבר משה<sup data-n=\"4402\">24</sup> שלשון זה הוא ג\"כ כמו כל הד' ספרים שלא נא' מי אמרן (שהוא כמו שלישי המדבר) והנה הוא תירץ שהתורה קדמה אלפים שנה לעולם<sup data-n=\"4403\">25</sup> וגם אז הי' נאמר וידבר ה' אל משה לכן אינו שייך שיאמר משה ויאמר ה' אלי שגם קודם הי' כן כו'. וזהו תירוץ. אמנם יש לתרץ עוד דהנה צ\"ל עוד ענין א'<sup data-n=\"4404\">26</sup> שמפני מה הוא כל התו' כמו סיפור דברים שמספר שצ\"ל כך וכך ולא דינים ציוים<sup data-n=\"4405\">28</sup> זולת פ' משפטים הוא כמו ספר דינים שמדבר לנוכח כי תקנה עבד עברי<sup data-n=\"4406\">29</sup> כו', משא\"כ בכל התורה הוא רק סיפור דברים<sup data-n=\"4407\">30</sup> בעלמא<sup data-n=\"4408\">27</sup>.",[["4389","11","<b>הרמב\"ן בהקדמתו לפי' החומש</b>: ראה פתיחת הרמב\"ן על התורה. בנוסף להערה 1 ראה גם אוה\"ת דברים ע' א. יתרו ע' תשעא. ע' תתקלח. ע' תתקלט."],["4390","12","<b>מה</b>: בכת\"י הר\"ש סופר העתיק כאן לשון האוה\"ת. ותיקן כ\"ק אדמו\"ר מהר\"ש כבפנים. ונמצא הלשון שבאוה\"ת בסמוך בפנים על יד הערה 27."],["4391","13","<b>שבכל הד' ספרים הראשונים</b>: כ\"ה גם בחלק המקומות שבהערה 1. ואוצ\"ל הג'."],["4392","14","<b>יחזקאל</b>: ברמב\"ן שם מביא הכתוב: ויהי דבר ה' אלי לאמר בן אדם — יחזקאל ג, טז-יז־ ו, א-ב־ יא, יד-טו־ יב, א-ב (חיבור ב' כתובים. בדפוסים הנפוצים מובא הכתוב בהשמטת תיבת: לאמר, אבל ראה מהדורת שעוועל ע' ב)."],["4393","15","<b>וירמי'</b>: ברמב\"ן שם מביא: ויאמר ירמיהו הי' דבר ה' אלי לאמר — ירמי' לב, ו. [כ\"ה בד\"ר — ראה גם מהדורת שעוועל שם. בדפוסים הנפוצים הובא הכתוב : ויהי דבר ה' אלי לאמר — ירמי' א, ד. יא. ב, א. ועוד. באוה\"ת אמור כרך ד כאן ע' א'עו ודברים שם מביא את זה על יחזקאל (נסמן בהערה שלפנ\"ז) וכן בירמי']."],["4394","16","<b>ויאמר ה' אלי</b>: ירמי' א, ז. ט. יב. יד. ועוד. יחזקאל כג, לו."],["4395","17","<b>ואשמע קול</b>: יחזקאל א, כח. וראה שם כד. ג, יב."],["4396","18","<b>ואראה ואפול על פני</b>: יחזקאל א, כח."],["4397","19","<b>ונועדתי לך שם</b>: תרומה כה, כב."],["4398","20","<b>במשנה תורה. . מפי עצמו אמרם</b>: ראה מגילה לא, ב. זהר ואתחנן רסא, א (ובמקדש מלך ואור החמה שם). (בנוסף להערה 1) לקמן בפיסקא והנה כ\"ז. ו (בחלק ההנחות) בהנחה כאן על יד הערה 67. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550043\" data-slug=\"torat-chaim\" data-id=\"2300550043\">תו\"ח יתרו ח\"ב רסד, א</a>. מאמרי אדה\"א שמות ח\"ב ע' שלא. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191009\" data-slug=\"likkutei-sichot\" data-id=\"1300191009\">לקו\"ש דברים כרך יט ע' 9</a> ואילך. וש\"נ. ר\"ח שבט כרך לו ע' 42. וש\"נ."],["4399","21","<b>ואתפלל</b>: עקב ט, כ. כו."],["4400","22","<b>ואתנפל</b>: עקב ט, יח. כה. וכ\"ה לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 20. כתוב זה לא הובא ברמב\"ן שם. ושם סדר הפסוקים: ואתחנן ואתפלל אל ה'. ועד\"ז הוא באוה\"ת אמור כרך ד כאן (ע' א'עו). פלח הרמון ויקרא כאן."],["4401","23","<b>ואתחנן אל ה'</b>: ואתחנן ג, כג."],["4402","24","<b>אלה הדברים אשר דיבר משה</b>: דברים א, א."],["4403","25","<b>שהתורה קדמה אלפים שנה לעולם</b>: ראה מדרש תהלים צ, ד. שבת פח, ב וברש\"י שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ."],["4404","26","<b>וזהו תירוץ. . א'</b>: ניתוסף בגוכתי\"ק עה\"ג."],["4405","28","<b>ציוים</b>: בסה\"מ תרנ\"ו כאן: וציווים. אבל באוה\"ת וסה\"מ תרכ\"ו כאן כבפנים."],["4406","29","<b>כי תקנה עבד עברי</b>: משפטים כא, ב."],["4407","30","<b>בכל התורה הוא רק סיפור דברים</b>: הגם שכתוב בלשון ציווי כמו דבר אל בנ\"י ויקחו לי תרומה כו' או כי תבואו אל הארץ ושבתה כו' מ\"מ כיון שתחלת הדברים הוא וידבר הוי' כו' נראה הל' שאין עיקר הכוונה הציווי רק עיקר הכווונה הוא הסיפור לספר איך ציווה ה' אל משה לדבר אל בנ\"י וכנ\"ל שהל' הוא כשלישי המדבר כו' לבד פ' משפטים אין כתוב בתחלת' וידבר כו' והל' נכתב בדרך ציווי ואזהרה — פלח הרמון ויקרא כאן."],["4408","27","<b>שמפני. . בעלמא</b>: קטע זה הובא לעיל (בהדרושים שבהערה 1) ראה לעיל הערה 12."]]],[2000450412,"<b>ויובן</b> זה בהקדם דברי חז\"ל<sup data-n=\"4409\">31</sup> שמבטלין מצוה שאפשר להתקיים ע\"י אחרים מפני תלמוד תורה<sup data-n=\"4410\">32</sup>, ולכאו' צ\"ל הלא כל התורה היא רק פי' וביאור המצוה כמו ציצית ותפילין ושבת והיתכן לומר שהוא יעסוק בפי' ביאור איך יעשה המצוה והוא עצמו לא יעשנה כ\"א אחר וכמו הפרשת תרומה שאפשר לקיים ע\"י אחרים, <sup data-n=\"4411\">34</sup> ומ\"מ הנה אמרו מצוה בו יותר מבשלוחו<sup data-n=\"4412\">35</sup> והאיך יהי' שהוא עצמו ילמד איך מפרישין תרומה וכמה צריכים להפריש והמצוה עצמה יעשנה אחר והיינו שלוחו כו'<sup data-n=\"4413\">33</sup>. אמנם הענין הוא דהנה המצות הם בזמן ומקום<sup data-n=\"4414\">36</sup> כמו ז' ימי הפסח שהם דוקא בז' ימים אלו דוקא מן ט\"ו בניסן עד ך\"א<sup data-n=\"4415\">37</sup> בו וכן ז' ימי הסוכות וכמו שבת שרגע א' לפני יום השבת ורגע שלאחר יום השבת אינו כלום ולא יתחייב כלל העושה בו מלאכה, רק יום השבת דוקא הוא הציווי באיסור מלאכה ל\"ט מלאכות<sup data-n=\"4416\">38</sup> כו', הרי כי הם מלובשים תחת הזמן, וכן במקום שהקרבת הקרבנות הי' צ\"ל בירושלים בבהמ\"ק<sup data-n=\"4417\">39</sup> דוקא ושחיטת חוץ<sup data-n=\"4418\">40</sup> כו' שהמצות מלובשים בזמן ומקום, משא\"כ התורה היא למעלה מבחי' זמן ומקום, ולכן ארז\"ל כל העוסק בתורת עולה<sup data-n=\"4419\">41</sup> כאלו הקריב עולה הגם שעכשיו שאין לנו בהמ\"ק, וגם בלימוד התורה כשילמוד הלכות פסח בסוכות<sup data-n=\"4420\">42</sup> או הלכות הסוכה בפסח הרי הקב\"ה קורא ושונה כנגדו<sup data-n=\"4421\">*43</sup> שוה כמו אם הי' לומד הלכות פסח בפסח והלכות סוכה בסוכות רק שדבר בעתו יותר טוב ועז\"נ",[["4409","31","<b>ויובן. . חז\"ל</b>: בסה\"מ תרכ\"ו כאן ע' עדר: אך באמת י\"ל דהנה ארז\"ל. וכן העתיק הר\"ש סופר ומחקו כ\"ק אדמו\"ר מהר\"ש ותיקן כבפנים."],["4410","32","<b>שמבטלין מצוה. . מפני תלמוד תורה</b>: ראה מוע\"ק ט, ב. רמב\"ם הל' ת\"ת פ\"ג, ה\"ד. טושו\"ע יו\"ד הל' ת\"ת סרמ\"ו, סי\"ח. הל' ת\"ת לאדה\"ז פ\"ד, ה\"ג. בהערה הבאה. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151138\" data-slug=\"likkutei-sichot\" data-id=\"1300151138\">לקו\"ש</a> כ' מ\"ח כרך טו ע' 138 ואילך."],["4411","34","<b>הפרשת תרומה. . ע\"י אחרים</b>: ראה תרומות פ\"ד, מ\"ד."],["4412","35","<b>מצוה בו יותר מבשלוחו</b>: קדושין מא, א. ראה שו\"ע אדה\"ז הל' שבת סר\"נ, ס\"ד ובקו\"א שם. תבואת שור סכ\"ח, סקי\"ד."],["4413","33","<b>ולכאורה. . כו'</b>: ראה (בנוסף להערה 1) <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380371\" data-slug=\"likkutei-torah\" data-id=\"4001380371\">לקו\"ת במדבר טו, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380191\" data-slug=\"likkutei-torah\" data-id=\"4001380191\">אחרי כו, ד</a>."],["4414","36","<b>המצות הם בזמן ומקום. . התורה. . זמן ומקום</b>: ראה לקמן בהערה 42."],["4415","37","<b>ז' ימי הפסח. . עד ך\"א</b>: ראה בא יב, יח. אמור כג, ו ואילך. פינחס כח, יז ואילך."],["4416","38","<b>ל\"ט מלאכות</b>: ראה שבת עג, א."],["4417","39","<b>הקרבנות. . בבהמ\"ק</b>: ראה פ' ראה יב, ה ואילך. רמב\"ם הל' מעשה הקרבנות רפי\"ח."],["4418","40","<b>ושחיטת חוץ</b>: ראה אחרי יז, ג ואילך. רמב\"ם שם ה\"ב ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550842\" data-slug=\"torat-chaim\" data-id=\"2300550842\">תו\"ח ויקהל ח\"ב תכז, ג</a>."],["4419","41","<b>כל העוסק בתורת עולה</b>: ראה מנחות קי, א. לקו\"ש מסעי כרך יח ע' 413. וש\"נ. ערב פסח כרך לב ע' 37. וש\"נ."],["4420","42","<b>כשילמוד הל' פסח בסוכות</b>: ראה גם (בנוסף להערה 1) לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 37. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380360\" data-slug=\"likkutei-torah\" data-id=\"4001380360\">לקו\"ת במדבר יג, א</a>. מאמרי אדה\"ז תקס\"ב ח\"א ע' רד. ח\"ב ע' תמו ואילך. ע' תמח ואילך. מאמרי אדה\"א במדבר ח\"ב ע' תקצד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550597\" data-slug=\"torat-chaim\" data-id=\"2300550597\">תו\"ח ויקהל ח\"ב שצג, א</a>. אוה\"ת שבועות ע' קנט. סה\"מ תרכ\"ז ע' שלו (בשולי הגליון). המשך תער\"ב ח\"א ע' שמב. ולהעיר ממאמרי אדה\"ז תקס\"ט ר\"ע קל."],["4421","*43","<b>הקב\"ה קורא ושונה כנגדו</b>: ראה תדא\"ר רפי\"ח. מאמרי אדה\"א דברים ח\"ב ע' שפז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540132\" data-slug=\"torat-chaim\" data-id=\"2300540132\">תו\"ח וארא ח\"א נח, ג</a>. וש\"נ."]]],[2000450413,"דבר בעתו מה טוב<sup data-n=\"4422\">43</sup>, אבל מ\"מ הנה גם בל\"ז הקב\"ה קורא ושונה כנגדו כו'. וגם מצות לימוד התורה היא להיות והגית בה יומם ולילה<sup data-n=\"4423\">45</sup> בלתי התחלקות הזמן ע\"ד כמו עבודת המלאכי' שאומרים קדוש ביום, וברוך בלילה דוקא כמ\"ש בילקוט ס\"פ תשא<sup data-n=\"4424\">46</sup>, והיינו להיותם בבחי' התחלקות הזמן, משא\"כ תו' שהיא בעצם למעלה מזמן ומקום לכן מצותה והגית בה יומם ולילה כו'<sup data-n=\"4425\">44</sup><sup data-n=\"4426\">47</sup>. והענין הוא דהנה נודע שרמ\"ח פקודין הם רמ\"ח אברי' דמלכא<sup data-n=\"4427\">48</sup> שכמו באדם הנה האברים הם כלים להשראת הנפש כמו\"כ המצות הם כלים<sup data-n=\"4428\">49</sup> להשראת אוא\"ס ב\"ה שהם רמ\"ח אברין דמלכא.\n<b>וביאור</b> הענין דהנה בד\"כ באדם הם ט' בחי' כללי' שבהראש הוא בחי' ג' מוחין, והגוף ותרין דרועין הם ג' ותרין רגלין ואות ברית הם ג' שהם ט' בחי' כללי' שהם כוללי' כל ציור האדם, ועד\"ז יובן למעלה דכתי' ועל דמות הכסא<sup data-n=\"4429\">50</sup> דמות כמראה אדם עליו מלמעלה שבחי' אדם זהו בחי' ז\"א דאצי' שהוא בעל ט' ספי'<sup data-n=\"4430\">51</sup>, ובפרטיות יש בו רמ\"ח אברין שהם רמ\"ח אברי' דמלכא שטפ\"ט היינו מה שכל ספי' כלולה מזולתה הם פ\"א ורת\"ס שיש בכל בחי' עולה רמ\"ג וה\"ח המגדילים הם רמ\"ח<sup data-n=\"4431\">52</sup> וז\"ע שרש רמ\"ח פקודין שהם רמ\"ח אברין דמלכא כו' והם מלובשים תחת הזמן ומקום לפי של' כלים דז\"א<sup data-n=\"4432\">53</sup> (שהמצות הם בכלים דז\"א שהוא בחי' אברי' דמלכא כמו האבר שהוא כלי להשראת הנפש כו' ולמעלה הוא כלים של ט\"ס דז\"א) מתלבשי' בג' עולמות בי\"ע יו\"ד כלים הפנימי' בבריאה ויו\"ד כלים התיכוני' ביצי' ויו\"ד כלים החיצוני' בעשי', ומפני כי הם מתלבשי' בבי\"ע לכן הם בבחי' זמן ומקום וגם כי שרש בי\"ע הוא מבחי' מל' כמ\"ש מלכותך מלכות<sup data-n=\"4433\">54</sup> כו' ובחי' המל' הוא בחי'",[["4422","43","<b>דבר בעתו מה טוב</b>: משלי טו, כג [ושם: ודבר]. ראה ערובין נד, א וברש\"י שם. סנהדרין קא, א. אוה\"ת משלי כרך א' ע' תרא ואילך. במדבר ע' סז ואילך."],["4423","45","<b>והגית בה יומם ולילה</b>: יהושע א, ח [ושם: בו — ראה (בנוסף להערה 1) מאמרי אדה\"ז תקס\"ז ע' שמח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680451\" data-slug=\"torat-chaim\" data-id=\"2300680451\">תו\"ח מקץ רכז, א</a> ובהערה 18. תצוה ח\"ב שכב, א. סה\"מ תרכ\"ט ע' שלה. המשך תער\"ב ח\"א ע' צב]."],["4424","46","<b>קדוש ביום וברוך בלילה. . בילקוט ס\"פ תשא</b>: ראה גם לעיל המשך וידבר וגו' ויצוום פ\"ח ובהערה *134."],["4425","44","<b>מצות. . כו'</b>: בסה\"מ תרכ\"ו כאן ס\"ע עדר בשינוי (וכן העתיק הר\"ש סופר) ותיקן כ\"ק אדמו\"ר מהר\"ש כבפנים."],["4426","47","<b>נודע</b>: באוה\"ת כאן ע' תתלח־ סה\"מ תרכ\"ו כאן: איתא בספרים (וכן העתיק הר\"ש סופר) ותיקן כ\"ק אדמו\"ר מהר\"ש כבפנים."],["4427","48","<b>שרמ\"ח פקודין הם רמ\"ח אברי' דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). <a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא</a> רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["4428","49","<b>המצות הם כלים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380360\" data-slug=\"likkutei-torah\" data-id=\"4001380360\">לקו\"ת במדבר יג, א</a>. לעיל המשך אם כסף תלוה פי\"ב על יד הערה 247 ואילך ובהערה שם."],["4429","50","<b>ועל דמות הכסא</b>: יחזקאל א, כו."],["4430","51","<b>ז\"א. . בעל ט' ספי'</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381201\" data-slug=\"likkutei-torah\" data-id=\"4001381201\">לקו\"ת שה\"ש יח, א</a> מציין: ”כמ\"ש במ\"א בד\"ה אלפי שנאן בפ' יתרו [<a class=\"ft-cite\" href=\"#/read/torah-or/3901370320\" data-slug=\"torah-or\" data-id=\"3901370320\">תו\"א יתרו עב, א</a>] ועיין בזהר נח דס\"ה א' ובע\"ח שער א\"א פ\"ב\"."],["4431","52","<b>שטפ\"ט. . רמ\"ג. . רמ\"ח</b>: ראה גם לעיל המשך אם כסף תלוה פי\"ב ובהערה 245."],["4432","53","<b>של' כלים דז\"א </b>: ראה ע\"ח שער הפרצופים ש\"ל, דרוש א. שער השמות שמ\"ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540159\" data-slug=\"torat-chaim\" data-id=\"2300540159\">תו\"ח שמות ח\"א כד, ב</a>. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550307\" data-slug=\"torat-chaim\" data-id=\"2300550307\">תצוה ח\"ב שכ, ג</a> ובהערה 84."],["4433","54","<b>מלכותך מלכות</b>: תהלים קמה, יג. ראה גם סה\"מ תר\"ל ע' שה."]]],[2000450414,"מלך מלך ימלוך<sup data-n=\"4434\">56</sup> שהוא שרש ומקור הזמן ומקום<sup data-n=\"4435\">55</sup> כידוע ממ\"ש במ\"א באריכות כו'. אבל התורה היא מבחי' מח' הקדומה כי אורייתא מח\"ע נפקת<sup data-n=\"4436\">57</sup> (וע'<sup data-n=\"4437\">58</sup> לקמן שחכ' דא\"ק היינו בחי' מח' הקדומה מאיר באצי'<sup data-n=\"4438\">59</sup> שהוא בחי' חכ' עילאה) שח\"ע היא קדש מלה בגרמי'<sup data-n=\"4439\">60</sup> פי' מלה בגרמי' שאינו שייך לעולמות דהנה המדות הם שייכי' לעולם<sup data-n=\"4440\">61</sup> דוקא שאם לא העולם לא הי' שייך לומר בחי' חסד או רחמים שבחי' חסדן או רחמן אינו שייך כ\"א על זולתו ואם לא הי' העולם לא שייך שהוא חסדן כי אין שום דבר שיעשה לו חסד או שירחם עליו, אבל בחי' החכ' שייך גם בלעדי העולם כמשל החכם שיוכל לישב בעצמו ולהשכיל השכלות הגם שלא ישפיע לזולתו כו', ועד\"ז יובן ענין ח\"ע שהיא קדש מלה בגרמי' שאינו שייך כלל לעולמות ומשם הוא שרש התורה שהיא גבוה מאד נעלה מבחי' המצות שמלובשים תחת הזמן כנ\"ל.\n<b>ולכן</b> בכל התורה לא נא' בדרך ציווי רק בדרך סיפור דברים בעלמא, כי ענין הציווי אינו שייך אלא לבחי' מלך שמצוה לעבדיו שיעשו לו כך וכך, אבל התורה לפי ששרשה גבוה מאד מבחי' ח\"ע שקדש מלה בגרמי' כנ\"ל, לכן היא רק בדרך סיפור, וה\"ז כמשל הבע\"ב שמסדר את חפציו שיעמדו בביתו זה כאן וזה כאן שאינו מצוה כלל רק שמסדר שדבר זה יעמוד כאן ודבר זה כאן, ועד\"ז יובן בענין התורה שנא' אם בחוקתי תלכו<sup data-n=\"4441\">62</sup> כו' ובפרטי עניני המצות שהציצית יהיו כך דוקא ובל\"ז לא יהי' נעשה בה וע\"י המשכת אוא\"ס ב\"ה וכמו\"כ התפילין וכל פרטי המצות שהוא בדרך סידור בעלמא שמסדר שהתפילין כו' והציצית יהיו על ד' כנפי בגדיהם<sup data-n=\"4442\">63</sup> כו', ועד\"ז בכל המצות כו'. וז\"ע מ\"ש ואהי' אצלו אמון, שפי' אמון ל' אומן<sup data-n=\"4443\">64</sup> והיינו מפני שהתורה היא אצלו לכן הוא בחי' אומן לסדר כל דבר כו'. ומעתה יובן ג\"כ ענין מפני מה לא נא' בכל ד' ספרים<sup data-n=\"4444\">*65</sup> התורה מי הוא המספר, כי המספר את התורה הוא בחי' עצמיות המאציל שלמעלה מבחי' ש' הוי', ומפני כי גדלה מעלת התו' בבחי' מח' הקדומה וכנ\"ל בענין בחי' ח\"ע שקדש מלה בגרמי', לכן מבטלין מצוה שאפשר לקיים ע\"י אחרים מפני ת\"ת כי המצות הם בבחי' זמן ומקום כנ\"ל אבל התו' היא למעלה מן הזמן ומקום<sup data-n=\"4445\">65</sup>.",[["4434","56","<b>מלך מלך ימלוך</b>: ראה זהר בראשית לד, א. אוה\"ת סידור ע' פג ואילך."],["4435","55","<b>המל'. . ומקור הזמן ומקום</b>: ראה שער היחוד והאמונה פ\"ז. מאמרי אדה\"א דברים ח\"א ע' קלה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540899\" data-slug=\"torat-chaim\" data-id=\"2300540899\">תו\"ח בשלח ח\"א רלד, א</a>. וש\"נ."],["4436","57","<b>אורייתא מח\"ע נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["4437","58","<b>(וע'</b>: החצע\"ג ניתוסף בגוכתי\"ק עה\"ג."],["4438","59","<b>לקמן שחכ' דא\"ק. . מאיר באצי'</b>: ד\"ה והנה כ\"ז."],["4439","60","<b>קדש מלה בגרמי'</b>: זהר אמור צד, ב."],["4440","61","<b>המדות הם שייכי' לעולם</b>: ראה לקמן (בחלק ההנחות) הנחה ד\"ה ב\"ה אלקי ישראל ובהערה 20."],["4441","62","<b>אם בחוקתי תלכו</b>: בחוקותי כו, ג."],["4442","63","<b>והציצית יהיו על ד' כנפי בגדיהם</b>: תצא כב, יג. שו\"ע אדה\"ז הל' ציצית ס\"י, ס\"א ואילך."],["4443","64","<b>ואהי' אצלו אמון. . אומן</b>: משלי ח, ל. ב\"ר בתחילתו."],["4444","*65","<b>ספרים</b>: בסה\"מ תרכ\"ו כאן: ספרי."],["4445","65","<b>ומקום</b>: בסה\"מ תרכ\"ו כאן ע' רעו ניתוסף: וד\"ל (וכן העתיק הר\"ש סופר כאן) ותיקן כ\"ק אדמו\"ר מהר\"ש כבפנים."]]],[2000450415,"<b>ובכ\"ז</b> יובן ענין ופי' אני הוי' הנא' בסיום כ\"פ, שאני קאי על בחי' עצמיות אוא\"ס ב\"ה המספר בחי' התורה שהוא למעלה מבחי' ש' הוי' כי ש' הוי' הוא בחי' שרש ומקור המחי' ומהוה העולמות<sup data-n=\"4446\">66</sup>, ואם<sup data-n=\"4447\">67</sup> כי ש' הוי' הוא בחי' שם העצם<sup data-n=\"4448\">68</sup> משא\"כ כל השמות הם כינוי' ש' אל הוא בחסד<sup data-n=\"4449\">69</sup> וש' אלקי' בגבו'<sup data-n=\"4450\">70</sup>, אבל ש' הוי' הוא שם העצם שגבוה משאר השמות, מ\"מ בחי' אני הוא עצמיות אוא\"ס שלמעלה מבחי' ש' הוי' כו'. ונאמר אני הוי' שאע\"פ שאני עצמיות המאציל גבוה למעלה הרבה מבחי' ש' הוי' מ\"מ אני הוי' שאני והוי' כולא חד<sup data-n=\"4451\">71</sup> כו' ולכן בסיום כמה פרשיות שבתו'<sup data-n=\"4452\">72</sup> נא' שאני הוא בחי' ש' הוי' המדבר למשה בחי' מצוה זו כו', וזהו ג\"כ ענין מועדי הוי' ונכפל עוד לומר מועדי כי ענין המועד הוא בחי' עת שאז מתגלה בחי' אוא\"ס ב\"ה ביתר שאת והם ג' מועדות שהם ג' זמנים שאז מתגלה הארה חדשה כו', ויש ב' בחי' בבחי' המועדי' שיש שנק' מועדי הוי', ויש בחי' מועדי שהם גבוהים יותר שהם מועדי' שלי היינו של עצמותו ית' וכמארז\"ל במד\"ר משפטים פ\"ל<sup data-n=\"4453\">74</sup> ע\"פ מגיד דבריו ליעקב<sup data-n=\"4454\">75</sup> חוקיו כו' מה שהוא עושה אומר לישראל לעשות, הוא דוקא עושה, וע' בפי' הוא בד\"ה וכ\"מ<sup data-n=\"4455\">76</sup> שהוא שופט צדק בפי' הוא מוחה פשעיך<sup data-n=\"4456\">73</sup>, ועד\"ז ה\"ע מצות הוי' ומצותי ג\"כ ע\"ד הנ\"ל. וזהו וידבר הוי' אל משה, הוי' הוא בחי' אוא\"ס ב\"ה שהוא הי' הוה ויהי'<sup data-n=\"4457\">77</sup> אל משה הוא בחי' ונחנו מ\"ה<sup data-n=\"4458\">78</sup> בחי' ביטול יסוד אבא<sup data-n=\"4459\">79</sup>, לאמר שיהי' גילוי זה בבי\"ע, ואיך יהי' הגילוי ע\"י דבר אל בנ\"י, בנ\"י הם בחי' למודי הוי' כמ\"ש וכל בניך למודי הוי', וע\"פ הקבלה הוא בחי' נו\"ה<sup data-n=\"4460\">80</sup> ושייכות בחי' נו\"ה לבחי' בנ\"י, כי ישראל הוא בחי' ז\"א<sup data-n=\"4461\">81</sup> ובנ\"י הם נו\"ה<sup data-n=\"4462\">82</sup> כי כל א' מישראל צריך לקיים המצות בבחי' נצחון הגם שאינו רוצה וכמו\"כ בבחי' הוד הגם שאינו מבין כו'.",[["4446","66","<b>ש' הוי'. . ומהוה העולמות</b>: ראה גם לעיל המשך חייב אדם לברך פ\"ד ובהערה לשם."],["4447","67","<b>ואם</b>: כ\"ה בכ\"מ — ראה לעיל המשך וידבר וגו' ויצוום פ\"ג ובהערה 50."],["4448","68","<b>הוי'. . שם העצם</b>: ראה כ\"מ לרמב\"ם הל' ע\"ז פ\"ב, ה\"ז. פרדס שער שם בן ד' שי\"ט, פ\"א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' תכו."],["4449","69","<b>אל הוא בחסד</b>: ראה זהר אחרי סה, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670094\" data-slug=\"torat-chaim\" data-id=\"2300670094\">תו\"ח נח סד, ג</a> הערה 39."],["4450","70","<b>וש' אלקי' בגבו'</b>: ראה זהר יתרו פג, ב. הנסמן בתו\"ח שם הערה 41."],["4451","71","<b>שאני והוי' כולא חד</b>: ראה גם (בנוסף להערה 1) המשך תער\"ב ח\"ב ר\"ע תתקיט: דאני הוי' אני והוי' כולא חד. שם ע' תתקכג: וכמ\"ש אני הוי' אני והוי' כולא חד. זהר בראשית בהקדמה ו, א [בפי' אני הוי']: אקרי אני. . יי' וכלא חד. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080234\" data-slug=\"or-hatorah-hb\" data-id=\"8160080234\">אוה\"ת ויקרא כרך א ע' רלד</a>."],["4452","72","<b>כמה פרשיות שבתו'</b>: בסה\"מ תרכ\"ו כאן: כ\"פ (וכן העתיק הר\"ש סופר כאן) ותיקן כ\"ק אדמו\"ר מהר\"ש כבפנים."],["4453","74","<b>במד\"ר משפטים פ\"ל</b>: ראה שם ס\"ט."],["4454","75","<b>מגיד דבריו ליעקב</b>: תהלים קמז, יט."],["4455","76","<b>בד\"ה וכ\"מ</b>: שנדפס לעיל (בהחצע\"ג שבד\"ה ולהבין)."],["4456","73","<b>וכמארז\"ל. . פשעיך</b>: ניתוסף בגוכתי\"ק עה\"ג."],["4457","77","<b>הוי'. . הי' הוה ויהי'</b>: ראה שער היחוד והאמונה פ\"ז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680292\" data-slug=\"torat-chaim\" data-id=\"2300680292\">תו\"ח מקץ ריט, ד</a> הערה 62."],["4458","78","<b>משה. . ונחנו מ\"ה</b>: נסמן לעיל מאמר ד\"ה ישמח משה הערה 5."],["4459","79","<b>משה. . יסוד אבא</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061254\" data-slug=\"likkutei-sichot\" data-id=\"1300061254\">לקו\"ש שמות כרך ו ע' 244</a> ואילך."],["4460","80","<b>וכל בניך למודי הוי'. . נו\"ה</b>: ישעי' נד, יג. ראה אוה\"ת ישעי' כרך ב ע' תתלו. וש\"נ."],["4461","81","<b>ישראל הוא בחי' ז\"א</b>: ראה ע\"ח שער פרטי עי\"מ שכ\"ז, ספ\"ד. שער הקליפות שמ\"ח, פ\"ג. מאמרי אדה\"א דברים ח\"ב ע' שצב. וש\"נ. לעיל מאמר ד\"ה פי' פתחה בחכמה על יד הערה 48."],["4462","82","<b>ובנ\"י הם נו\"ה</b>: ראה ת\"ז רתמ\"ח. לעיל מאמר ד\"ה פי' פתחה בחכמה ובהערה 17."]]],[2000450416,"<b>והמספר</b> הוא בחי' עצמיות אוא\"ס ב\"ה שלמעלה מבחי' ש' הוי' כנ\"ל. ואפ\"ל שהמספר הוא ש' הוי' כמו שהוא כלול בעצמותו<sup data-n=\"4463\">83</sup> וזהו מ\"ש הוי' הוי'<sup data-n=\"4464\">84</sup> כו' כמ\"ש במ\"א, ולגבי בחי' ש' הוי' שבסדר השתל' נק' בחי' עצמיות אוא\"ס ב\"ה כו'.\n<b>והנה</b> לפי משנת\"ל שהמספר הוא עצמיות המאציל צ\"ל מ\"ש ביוהכ\"פ לפני הוי' תטהרו<sup data-n=\"4465\">85</sup> שקאי על א\"ס ב\"ה שלמעלה מש' הוי' מהו בחי' זו הלא לא יתכן לומר שקאי על המספר שהי' צ\"ל אכפר, לכן אפ\"ל עוד פי' שהמספר הוא בחי' המל' שבחי' מל' מספר שהוי' דיבר אל משה כו'. אך באמת אפשר לתרץ בלא זה שהמספר הוא עצמיות המאציל ב\"ה ואעפ\"כ לא יקשה מלפני הוי' תטהרו, דהנה נת' במ\"א בד\"ה ביום השמע\"צ שלא נדפס<sup data-n=\"4466\">86</sup> שפי' שם ענין ממכ\"ע וסוכ\"ע שממכ\"ע הוא בחי' מו\"ס וסוכ\"ע הוא בחי' גלגלתא וז\"ע ב' ראשין והם בחי' תומ\"צ שבחי' מו\"ס הוא בחי' תורה והמצות שרשן בגלגלתא, ואעפ\"כ לא יקשה שכאן נת' שהמצות הם בבחי' זמן ומקום כמ\"ש ביאור ענין<sup data-n=\"4467\">87</sup> בלק\"ת פ' במדבר<sup data-n=\"4468\">88</sup> בביאור ע\"פ וידבר אלקי' דעשה\"ד, והנה המחבר בחי' סוכ\"ע וממכ\"ע הוא בחי' ב' ראשין הנ\"ל הוא בחי' רדל\"א כמ\"ש שם באריכות, לכן אפ\"ל שבחי' רדל\"א הוא המכפר וזהו לפני הוי' כו', ומבחי' רדל\"א נמשך סליחות<sup data-n=\"4469\">*89</sup> העוונות על המצות כי שרש המצות הם בגלגלתא, והכפרה נמשך מבחי' רדל\"א כו' וזהו תטהרו בגימ' כתר<sup data-n=\"4470\">89</sup>, והמספר כל התורה גם מ\"ש לפני הוי' מספר בחי' עצמיות המאציל שלמעלה גם מבחי' רדל\"א.\n<b>והנה</b> כ\"ז הוא בחי' ד' ס' הראשוני', אבל ס' משנה תו' נא' ל' שמשה אומר מפי עצמו כנ\"ל ועכ\"ז כ' התוס'<sup data-n=\"4471\">90</sup> וברוח הקדש, וצ\"ל זה איך הוא מפי עצמו וברוה\"ק, אך הענין יובן בהקדם התורה, דהנה איתא בפע\"ח שבאצי' מאיר בחי' חכ' דא\"ק, משא\"כ בבריאה מאיר בחי' בינה דאצי'<sup data-n=\"4472\">91</sup>, וזהו ההפרש שבין ד\"ס הראשוני' לבחי' משנה תורה שד\"ס הראשוני' הוא כמו באצי' ששם מאיר בחי' חכ' דא\"ק, משא\"כ משנה תורה הוא כמו בבחי' בריאה ששם מאיר רק בחי' בינה דאצי' ולא מבחי' חכ' דא\"ק, ובחי' בינה הוא המסך<sup data-n=\"4473\">92</sup> והיינו כי הבינה הוא בחי' לבוש להלביש כו' (ואפ\"ל שז\"ע משה זכה לבינה<sup data-n=\"4474\">93</sup> לכן בחי' משנה תורה הוא שמאיר",[["4463","83","<b>ש' הוי'. . כלול בעצמותו</b>: ראה גם לעיל המשך אם כסף תלוה ספי\"ד ובהערה 321."],["4464","84","<b>הוי' הוי'</b>: תשא לד, ו. זהר אד\"ר נשא קלח, רע\"א. ראה גם לעיל המשך אם כסף תלוה ספי\"ד ובהערה 319."],["4465","85","<b>לפני הוי' תטהרו</b>: אחרי טז, ל."],["4466","86","<b>בד\"ה ביום השמע\"צ שלא נדפס</b>: ראה אוה\"ת שמע\"צ ע' א'תשפא ואילך."],["4467","87","<b>ענין</b>: אוצ\"ל הענין."],["4468","88","<b>ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380376\" data-slug=\"likkutei-torah\" data-id=\"4001380376\">לקו\"ת פ' במדבר</b>: יז, א</a> ואילך."],["4469","*89","<b>סליחות</b>: באוה\"ת וסה\"מ תרכ\"ו כאן: סליחת."],["4470","89","<b>תטהרו בגימ' כתר</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380191\" data-slug=\"likkutei-torah\" data-id=\"4001380191\">לקו\"ת אחרי כו, רע\"ד</a> מציין לרמ\"ז ס\"פ אחרי."],["4471","90","<b>כ' התוס'</b>: במגילה שם ד\"ה משה."],["4472","91","<b>בפע\"ח שבאצי'. . חכ' דא\"ק. . בבריאה. . בינה דאצי'</b>: ראה ע\"ח שער סדר אבי\"ע שמ\"ז, פ\"ב. (בנוסף להערה 1) <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380533\" data-slug=\"likkutei-torah\" data-id=\"4001380533\">לקו\"ת קרח נד, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381261\" data-slug=\"likkutei-torah\" data-id=\"4001381261\">שה\"ש לג, א</a>. אוה\"ת דברים כאן סע\"ד ואילך."],["4473","92","<b>בינה הוא המסך</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פי\"ג. שער סדר אבי\"ע שם. ראה גם (בנוסף להערה 1) לקו\"ת שהש לט, ג. נא, א."],["4474","93","<b>משה זכה לבינה</b>: ר\"ה כא, ב. ראה גם מאמרי אדה\"ז תקס\"ח ח\"א ע' קפה."]]],[2000450417,"ע\"י הבינה). (אך צ\"ע הלא חו\"ב הם תרדל\"מ<sup data-n=\"4475\">94</sup> ומאחר שבחכ' מאיר בחי' חכ' דא\"ק הנה הם תרדל\"מ והי' צ\"ל בבריא' ג\"כ ע\"י הבינה שגם בה מאיר חכ' דא\"ק מאחר שהם תרדל\"מ כנ\"ל וצ\"ע. ואולי יש לתרץ ע\"פ מ\"ש בס\"י<sup data-n=\"4476\">96</sup> הבן בחכ' וחכם בבינה<sup data-n=\"4477\">97</sup>, שע\"י בחי' הבן שיש בחכ' היא נעשית בבחי' תרדל\"מ עם בינה היינו עם בחי' חכם שיש בבינה, אבל מה שמאיר בבריאה י\"ל שזהו מעצם הבינה ולא מבחי' חכם בבינה ששם תרדל\"מ עם החכ', (וכמו כל השפעה שהיא רק חלק היותר אחרון<sup data-n=\"4478\">98</sup> ע\"ד כמו בחי'<sup data-n=\"4479\">99</sup> מל' שבבחי' המשפיע כו') וא\"כ לא יקשה מידי שהגם שבחכ' דאצי' מאיר חכ' דא\"ק וכן י\"ל גם בחכם דבינה להיותה תרדל\"מ כנ\"ל מ\"מ מה שנמשך מעצם הבינה היינו ממל' דבינה בבריאה לא יש מבחי' חכ' דא\"ק כ\"א מבחי' בינה דאצי' בעצם כו')<sup data-n=\"4480\">95</sup> לכן בס' משנה תורה נא' כאלו משה מפי עצמו אמרן כו', ואעפ\"כ בתחלת ספר משנה תורה נא' אלה הדברים כו' שלא נא' מי הוא המספר, והיינו מפני שבעשה\"ד<sup data-n=\"4481\">100</sup> נא' וידבר כו' כל הדברים האלה<sup data-n=\"4482\">101</sup>, ופי' שכל הדברים נכללי' בעשה\"ד גם בחי' משנה תו' ותושבע\"פ כמ\"ש בד\"ה וידבר אלקי' בלק\"ת בפ' במדבר<sup data-n=\"4483\">102</sup> יעו\"ש, לכן נא' בתחלת הספר כמו בספרים הראשונים, והתחיל אלה הדברים לרמז על תיבת הדברים שנא' בפסוק וידבר כו'<sup data-n=\"4484\">103</sup>.\n<b>וביאור</b> ענין איך משה מפי עצמו וברוה\"ק, הנה יובן זה ממ\"ש בפע\"ח שער הק\"ש<sup data-n=\"4485\">104</sup> שבחי' המשכת אור חדש נמשך מבחי' אוא\"ס ב\"ה שלמעלה מבחי' חו\"ב בבחי' השתל' עו\"ע, והיינו שאותו האור ממש נמשך בהשתל' כו', אבל לבחי' חידוש הישינות נמשך ההמשכה רק מבחי' חו\"ב עצמם. ולכאו' יפלא הלא כתי' ובטובו מחדש<sup data-n=\"4486\">105</sup> בכ\"י תמיד מע\"ב, אך הענין דבחי' ההמשכה שנמשך להחיות העולמות שהוא בחי' חידוש הישינות עם כי בחי' זה הוא ג\"כ מבחי' אוא\"ס ב\"ה שלמעלה מבחי' חכ' מ\"מ לא נמשך כ\"א הארה מועטת לחדש הישינות לכן נק' המשכה זו המשכה מבחי' חו\"ב כו', וע' בלק\"ת בביאור השני ע\"פ יונתי בחגוי הסלע, בלק\"ת<sup data-n=\"4487\">106</sup> בשה\"ש<sup data-n=\"4488\">107</sup>, ועד\"ז ה\"ע משה מפי עצמו וברוה\"ק שהגם שהוא ברוה\"ק מ\"מ",[["4475","94","<b>חו\"ב הם תרדל\"מ</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670185\" data-slug=\"torat-chaim\" data-id=\"2300670185\">תו\"ח בראשית כא, ב</a> ובהערה 8."],["4476","96","<b>בס\"י</b>: ניתוסף בגוכתי\"ק בין השיטין."],["4477","97","<b>בס\"י הבן בחכ' וחכם בבינה</b>: פ\"א, מ\"ד."],["4478","98","<b>השפעה. . חלק היותר אחרון</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן ובהערה 80."],["4479","99","<b>ע\"ד כמו בחי'</b>: בסה\"מ תרכ\"ו כאן: כמו. וניתוסף בגוכתי\"ק בין השיטין תיבות ע\"ד. . בחי'."],["4480","95","<b>ואולי. . בעצם כו')</b>: מובא גם בסה\"מ תרכ\"ו כאן ע' רעז. ובאוה\"ת כאן ע' תתמ ליתא."],["4481","100","<b>שבעשה\"ד</b>: בסה\"מ תרכ\"ו כאן: שנא' אלה הדברים וקודם בעשה\"ד. וכן העתיק הר\"ש סופר ומחקו כ\"ק אדמו\"ר מהר\"ש ותיקן כבפנים. ראה גם לקמן הערה 103."],["4482","101","<b>וידבר. . הדברים האלה</b>: יתרו כ, א."],["4483","102","<b>בד\"ה וידבר אלקי' בלק\"ת בפ' במדבר</b>: טו, ג."],["4484","103","<b>והתחיל. . כו'</b>: ניתוסף בגוכתי\"ק עה\"ג. ראה גם לעיל הערה 100."],["4485","104","<b>בפע\"ח שער הק\"ש</b>: פי\"א."],["4486","105","<b>כתי' ובטובו מחדש</b>: בברכת יוצר."],["4487","106","<b>בלק\"ת. . בלק\"ת</b>: כ\"ה גם בהדרושים שבהערה 1."],["4488","107","<b>בלק\"ת. . בשה\"ש</b>: כ, ב ואילך."]]],[2000450418,"נק' ע\"ש משה כאלו הם מפי עצמו כו'. והנה אעפ\"כ אפ\"ל שגדלה מעלת משנה תורה יותר מבחי' ד\"ס הראשוני', דהנה ארז\"ל<sup data-n=\"4489\">108</sup> ע\"פ שמש בגבעון דום<sup data-n=\"4490\">109</sup> נטל יהושע ס' משנה תורה וא' כשם שלא דממתי מזה כך דום מלפני, ולכאו' צ\"ל מפני מה משנה תורה דוקא. אך הענין הוא ע\"ד משארז\"ל עריבים עלי ד\"ס<sup data-n=\"4491\">110</sup> יותר מיינה של תורה שעכ\"פ לא פחות הוא בחי' משנה תורה מד\"ס, וביאור הענין דהנה יש בחי' סופר וספר וסיפור<sup data-n=\"4492\">111</sup>, והנה התורה היא בחי' ספר תורה, אבל דברי סופרים<sup data-n=\"4493\">112</sup> נמשך מבחי' סופר שלמעלה מבחי' ספר כו' ולכן עריבים ד\"ס כו' כמ\"ש באריכות בלק\"ת<sup data-n=\"4494\">113</sup> בד\"ה ושאבתם מים בששון השני, ואפ\"ל מפני כי סופר הוא<sup data-n=\"4495\">115</sup> בחי' מל'<sup data-n=\"4496\">114</sup> ובבחי' מל' יש כח להוות מאין ליש<sup data-n=\"4497\">116</sup> שכח הזה הוא מעצמיות אוא\"ס ב\"ה<sup data-n=\"4498\">118</sup> כנודע, וכמו\"כ הוא במשנה תורה<sup data-n=\"4499\">117</sup>, ולכן נטל יהושע ס' משנה תורה דוקא ואמר כשם שלא דממתי מזה כך דום מלפני כמ\"ש שמש בגבעון דום, גם י\"ל שזהו ע\"ד מ\"ש בחנה בענין ש' צבאות<sup data-n=\"4500\">119</sup> שזהו מפני שותתפלל חנה על הוי'<sup data-n=\"4501\">120</sup> המשיכה בחי' הוי' צבאות כו', כמ\"ש בת\"א פ' בא<sup data-n=\"4502\">122</sup> בד\"ה בעצם כו' צבאות ה'<sup data-n=\"4503\">121</sup>.",[["4489","108","<b>ארז\"ל</b>: בסה\"מ תרכ\"ו כאן ע' רעח ניתוסף: במדרש (וכן העתיק הר\"ש סופר כאן) ותיקן כ\"ק אדמו\"ר מהר\"ש כבפנים."],["4490","109","<b>שמש בגבעון דום</b>: יהושע י, יב. ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830126\" data-slug=\"or-hatorah-hb\" data-id=\"8158830126\">אוה\"ת במדבר ע' קכו</a> מציין: בספרי הובא בילקוט [יהושע י, יג רמז כב]. . וכ\"ה במד\"ר פ' בראשית ספ\"ו."],["4491","110","<b>עריבים עלי ד\"ס</b>: ראה ע\"ז לה, א וברש\"י שם."],["4492","111","<b>סופר וספר וסיפור</b>: ס\"י פ\"א, מ\"א."],["4493","112","<b>דברי סופרים</b>: בסה\"מ תרכ\"ו כאן: סיפור [ראה בהערה לשם]. הר\"ש סופר כתב כאן: סופרים. והוסיף כ\"ק אדמו\"ר מהר\"ש בין השיטין תיבת: דברי."],["4494","113","<b>בלק\"ת</b>: סוכות פ, ב."],["4495","115","<b>הוא</b>: ניתוסף בגוכתי\"ק בין השיטין."],["4496","114","<b>סופר. . מל'</b>: כ\"ה גם בסה\"מ תרכ\"ו כאן. ובאוה\"ת כאן: סיפור. וכ\"ה לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 90."],["4497","116","<b>ובבחי' מל'. . להוות מאין ליש</b>: ראה גם (בנוסף להערה 1) <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540455\" data-slug=\"torat-chaim\" data-id=\"2300540455\">תו\"ח בא ח\"א ק, ב</a> ובהערה 162. וראה גם מאמר ד\"ה ביום השני הקריב תשל\"ב פ\"ד [קונ' כב שבט תנש\"א — סה\"מ מלוקט ה ע' ריא]."],["4498","118","<b>להוות מאין ליש. . מעצמיות אוא\"ס ב\"ה</b>: ראה אגה\"ק ס\"כ."],["4499","117","<b>מל'. . במשנה תורה</b>: ראה פע\"ח שער הלולב שכ\"ט, פ\"ד בשם הזהר. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380378\" data-slug=\"likkutei-torah\" data-id=\"4001380378\">לקו\"ת במדבר יז, ג</a>. מאמרי אדה\"ז תקס\"ח ח\"א ע' רמו. (בנוסף להערה 1) אוה\"ת שבועות ע' ריט [ובמהדורת תשנ\"ה ע' ריז]."],["4500","119","<b>בחנה בענין ש' צבאות</b>: שמו\"א א, יא. ברכות לא, ב."],["4501","120","<b>שותתפלל חנה על הוי'</b>: שמו\"א א, י."],["4502","122","<b>כמ\"ש בת\"א פ' בא</b>: ס, ג."],["4503","121","<b>כמ\"ש. . ה'</b>: ניתוסף בגוכתי\"ק."]]],[2000450419,"<h3>מה יפו פעמיך (שלוש רגלים) כו'</h3>\n<b></b><b>נא' מויו\"ט הראשון ש\"ח</b>\nהדום רגלי כו' מרגלים\nמיו\"ט הראשון של חג\n<b>מה</b> יפו פעמייך<sup data-n=\"4504\">1</sup> בנעלים<sup data-n=\"4505\">2</sup>, פי' פעמיך הוא בחי' ההילוך שנש\"י נק' מהלכים<sup data-n=\"4506\">3</sup> ונא' פעמי' ל' רבים, שמלבד שקאי על כאו\"א מישראל הנה בכאו\"א יש ב' בחי' הילוך<sup data-n=\"4507\">4</sup>, והיינו ההילוך מלמטלמ\"ע, וההילוך מלמעלמ\"ט, ולזה רמז באמרו פעמייך ל' רבים היינו ב' בחי' הילוך הנ\"ל. והנה ההילוך הוא ברגל, וצ\"ל ענין ובחי' רגל, הנה כתי' והארץ הדום רגלי<sup data-n=\"4508\">5</sup>, רגל הוא כנס\"י<sup data-n=\"4509\">6</sup> ויש מעלה יתירה ברגל מה שאין בראש שהרגלים הם המהלכים כו' נעוץ סופן<sup data-n=\"4510\">7</sup> כו' ולכן ישראל נק' לי ראש<sup data-n=\"4511\">8</sup> (שבבחי' זו הרגל היא ראש וכשם שהראש פועל פעולתה ברגל ליישר הילוכה או לכוין הילוך הרגל שתלך ותרקד לפי הזמר שמזמרים, כן הרגל במה שהוא ראש דהיינו בהילוכה ה\"ה נושא את הראש וכל הגוף למקום אשר בעצמם אינם יכולים לבוא, ונמצא כי בעצם ההילוך הרגל היא ראש גמורה נגד כל האברי' כו', ולכן ישראל שנק' בנים למקום<sup data-n=\"4512\">9</sup>, וברא כרעא דאבוה<sup data-n=\"4513\">10</sup>, ה\"ה כבי' לי בחי' ראש). [הג\"ה, עמ\"ש בד\"ה אני דפ'",[["4504","1","<b>מה יפו פעמייך</b>: מאמר זה הוא דרוש השני שמבאר פיסקא שני' שבביאור השני (על מאמר ד\"ה השמים כסאי) ד\"ה להבין שרשי הדברים הנ\"ל שנדפס במאמרי אדה\"ז תקס\"ה ח\"ב הנחת כ\"ק אדמו\"ר האמצעי ע' תשסא — תשסב. והוא דרוש העשירי מההמשך — לאחרי הפסק של כמה דרושים — שבו נתבארו הדרושים דהשמים כסאי ושני ביאוריו שנאמרו בשנת תקס\"ה כמצויין לעיל ברד\"ה ואשא אתכם.\nהמאמר (מלבד הפתיחה וכן הערות שבתוך ההחצע\"ג שנכתבו בגוכתי\"ק) הוא לשון מאמרי אדה\"ז תקס\"ה הנ\"ל עם הגהות הצ\"צ שבאים בתוך חצאי ריבוע. וההגהות שבהחצע\"ג הם מכ\"ק אדמו\"ר מהר\"ש. ההגהות וכן הפתיחה נכתבו בבוך 1162. ורק הגהה א' עה\"ג נכתבה בבוך זה 1089. אודות ביכלאך אלו ראה המצויין לעיל בריש מאמר ד\"ה ואשא אתכם.\nהמאמר פרט להפתיחה נדפס גם בלקו\"ת לג\"פ בראשית יג, ב ואילך. ובאוה\"ת בראשית כרך ג ע' 946 ואילך [ובאוה\"ת שם הנה: א) הגהות הצ\"צ לא ניתנו בין שני חצאי ריבוע. ב) חסירים הגהות כ\"ק אדמו\"ר מהר\"ש].\nהנחה מדרוש זה — רק איזה שורות — מכ\"ק אדמו\"ר מהורש\"ב נדפסה לקמן בחלק ההנחות. והפתיחה היא שלש רגלים. והנחה אחרת (בפתיחה שלש רגלים) נדפסה לקמן בההוספה.\nהכותרת שבראש המאמר נעתקה מהשולי הגליון שנדפס לקמן על יד הערה 66 ושם שהפתיחה היתה: שלש רגלים. ונאמר רק חלקו, וההמשך נכלל בדרוש דשבת בראשית כמצויין בהערה 68 שם."],["4505","2","<b>מה יפו פעמייך בנעלים</b>: שה\"ש ז, ב."],["4506","3","<b>שנש\"י נק' מהלכים</b>: ראה מאמרי אדה\"ז תקע\"א ע' ו ואילך וע' יג ואילך. פרשיות התורה ח\"ב ע' תשכט ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תרסז ואילך. במדבר ח\"ג ע' א'לג ואילך. נ\"ך ע' תמח ואילך ובהנסמן בהנ\"ל. אוה\"ת בחוקותי כרך ג ע' תתקלא."],["4507","4","<b>ב' בחי' הילוך</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' רנה ואילך (נוסח א'). אוה\"ת תצא ע' תתריג."],["4508","5","<b>והארץ הדום רגלי</b>: ישעי' סו, א."],["4509","6","<b>רגל הוא כנס\"י</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370003\" data-slug=\"torah-or\" data-id=\"3901370003\">תו\"א א, ב</a>. לעיל מאמר ד\"ה ומקנה רב על יד הערה 23 ובהנסמן בריש המאמר שם."],["4510","7","<b>נעוץ סופן</b>: נסמן לקמן בהערה 38."],["4511","8","<b>ישראל נק' לי ראש</b>: ראה פע\"ח שער הלולב שכ\"ט, פ\"א. לעיל המשך חייב אדם לברך פ\"ט הערה 274."],["4512","9","<b>ישראל שנק' בנים למקום</b>: פ' ראה יד, א."],["4513","10","<b>וברא כרעא דאבוה</b>: ראה ע\"ח שער פרקי הצלם שכ\"ד, פ\"א בשם רז\"ל. מאמרי אדה\"א קונטרסים ע' שלט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550364\" data-slug=\"torat-chaim\" data-id=\"2300550364\">תו\"ח ויקהל ח\"ב שצו, א</a> הערה 118."]]],[2000450420,"ציצית<sup data-n=\"4514\">11</sup> בענין בשעה שישראל אומרים אישר\"מ כו', ומ\"ש סד\"ה קול דודי<sup data-n=\"4515\">12</sup> בענין ומקפץ על הגבעות, עכ\"ה]. ולהיות הדום לבחי' רגל להגביהם זהו ע\"י והארץ שהם מצות מעשיות<sup data-n=\"4516\">13</sup> וה\"ע וצדקה תרומם גוי<sup data-n=\"4517\">14</sup> כו' [הג\"ה שיהיו בבחי' כי מי גוי גדול<sup data-n=\"4518\">15</sup> כו', עכ\"ה]. (וע' בפ' שלח<sup data-n=\"4519\">16</sup> בד\"ה בפ' נסכים ס\"ס ב', בענין ישוב המד\"ר<sup data-n=\"4520\">17</sup> שא' אשר לו גוי קרוב אין כתי' כאן דכתי'<sup data-n=\"4521\">19</sup> לבנ\"י עם קרובו<sup data-n=\"4522\">20</sup>, אלא דכאן נא' על שם הוי' והתם על<sup data-n=\"4523\">21</sup> ש' אלקי'<sup data-n=\"4524\">18</sup>, ושם בסוף ההג\"ה שזהו ע\"י התו' שאם יהיו ד\"ת קרובים לכם אף אני קורא אתכם קרובים שנא' לבנ\"י עם קרובו, והענין הוא דבמ\"ת כתי' קול גדול ולא יסף<sup data-n=\"4525\">22</sup>, ות'<sup data-n=\"4526\">23</sup> ולא פסק, ועי\"ז נעשו בנ\"י ג\"כ גדול שהאיר בם מבחי' גדול ה'<sup data-n=\"4527\">24</sup>, והיינו ע\"י שפב\"פ דבר ה' עמכם<sup data-n=\"4528\">25</sup> שנת' פירושו במ\"א שע\"י שדבר הוי' עמכם במ\"ת אנכי הוי' אלקיך<sup data-n=\"4529\">26</sup> שנמשך מבחי' אנכי מי שאנכי<sup data-n=\"4530\">27</sup> להיות שהוי' יהי' בבחי' אלקיך, אלק' שלך<sup data-n=\"4531\">28</sup>, ועי\"ז נעשה ה' עמכם שהאיר בכאו\"א בחי' ש' הוי' כי דבורו של הקב\"ה חשיב מעשה<sup data-n=\"4532\">29</sup> כו', ולכן כמו בש' הוי' דכתי' כי גדול ה' מכל האלקי'<sup data-n=\"4533\">30</sup> וכתי' ג\"כ כמ\"פ גדול הוי'<sup data-n=\"4534\">31</sup> כן ע\"י ש' הוי' שבכאו\"א מישראל עי\"ז הוא גדול ונק' עם קרובו של ש' הוי', והיינו ע\"י שד\"ת קרובי' אליך, ועי\"ז קרוב הדבר אליך<sup data-n=\"4535\">32</sup>, פי' דבר הוא בחי' מל'<sup data-n=\"4536\">33</sup> כמ\"ש באשר דבר מלך שלטון<sup data-n=\"4537\">35</sup> שהוא בחי' ש' אלקי'<sup data-n=\"4538\">34</sup> ה\"ה קרוב אליך, וכמ\"ש ומי גוי גדול<sup data-n=\"4539\">36</sup> היינו שמאיר בהם ע\"י הקול גדול בחי' גדול הוי', שעי\"ז אשר לו אלקי' כבי' קרובים אליו כו').",[["4514","11","<b>בד\"ה אני דפ' ציצית</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380505\" data-slug=\"likkutei-torah\" data-id=\"4001380505\">לקו\"ת שלח מח, סע\"ב</a> ואילך."],["4515","12","<b>סד\"ה קול דודי</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381191\" data-slug=\"likkutei-torah\" data-id=\"4001381191\">לקו\"ת שה\"ש טו, ג</a>."],["4516","13","<b>והארץ שהם מצות מעשיות</b>: ראה גם לעיל מאמר ד\"ה בנים אתם ובהערה 19."],["4517","14","<b>וצדקה תרומם גוי</b>: משלי יד, לד [ושם: צדקה — אבל כ\"ה גם לעיל בהמשך כי תשא פט\"ו ובהערה 378]."],["4518","15","<b>כי מי גוי גדול</b>: ואתחנן ד, ז."],["4519","16","<b>וע' בפ' שלח</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381291\" data-slug=\"likkutei-torah\" data-id=\"4001381291\">לקו\"ת שם מ, ד</a>."],["4520","17","<b>ישוב המד\"ר</b>: דב\"ר פ\"ב, טו."],["4521","19","<b>דכתי'</b>: בלקו\"ת שם: דהא כתיב."],["4522","20","<b>לבנ\"י עם קרובו</b>: תהלים קמח, יד."],["4523","21","<b>על</b>: בלקו\"ת שם: נאמר על."],["4524","18","<b>אשר. . אלקי'</b>: לשון הלקו\"ת שם."],["4525","22","<b>קול גדול ולא יסף</b>: ואתחנן ה, יט."],["4526","23","<b>ות'</b>: תרגום אונקלוס ויונתן שם."],["4527","24","<b>גדול ה'</b>: נסמן בסמוך בהערה 31."],["4528","25","<b>שפב\"פ דבר ה' עמכם</b>: ואתחנן ה, ד. ראה גם לעיל בהמשך חייב אדם לברך פכ\"ה על יד הערה 902."],["4529","26","<b>אנכי הוי' אלקיך</b>: יתרו כ, ב."],["4530","27","<b>אנכי מי שאנכי</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא מהדו\"ק ספמ\"ט</a>. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["4531","28","<b>שהוי'. . אלקיך אלק' שלך</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370368\" data-slug=\"torah-or\" data-id=\"3901370368\">תו\"א תצוה פב, רע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381297\" data-slug=\"likkutei-torah\" data-id=\"4001381297\">לקו\"ת שה\"ש מב, ב</a>,"],["4532","29","<b>דבורו. . חשיב מעשה</b>: ראה ב\"ר פמ\"ד, כב. רש\"י לך טו, יח."],["4533","30","<b>כי גדול ה' מכל האלקי'</b>: יתרו יח, יא."],["4534","31","<b>כמ\"פ גדול הוי'</b>: תהלים מח, ב. צה, ג. צו, ד. קלה, ה. קמה, ג. דבהי\"א טז, כה. בהערה שלפנ\"ז."],["4535","32","<b>קרוב הדבר אליך</b>: ע\"פ נצבים ל, יד."],["4536","33","<b>דבר הוא בחי' מל'</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ד מערכת דבר. לעיל מאמר ד\"ה שיר המעלות ממעמקים ובהערה 45."],["4537","35","<b>באשר דבר מלך שלטון</b>: קהלת ח, ד."],["4538","34","<b>מל'. . שם אלקי'</b>: ראה זהר בראשית כב, א. אחרי סה, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540393\" data-slug=\"torat-chaim\" data-id=\"2300540393\">תו\"ח וארא ח\"א עה, ב</a> הערה 202."],["4539","36","<b>ומי גוי גדול</b>: ואתחנן ד, ח."]]],[2000450421,"<b>וביאור</b> הענין יובן<sup data-n=\"4540\">37</sup> ע\"פ הקדמה אחת והוא במה שנעוץ תחב\"ס וסופן בתחלתן<sup data-n=\"4541\">38</sup> כו', דהנה אנו רואים למטה באדם התחתון ענין זה דנעוץ סופן בתחלתן ותחב\"ס להיות כי הרגל מעמיד את הראש וגם ע\"י סם רפואה ידוע שעושין לרגל כדי שירפא דוקא הראש<sup data-n=\"4542\">39</sup> מפני שיש להן שייכות וקשר וחיבור בגידים זע\"ז כו', והנה מה שמתרפא הראש ע\"י רפואת הרגל הענין הוא דניתוסף ונתרבה אור השכל להיות משכנו ביתר שאת בכלי המוח, כי בתחלה שהי' איזה קלקול בכלי המוח עד שמפני זה הי' גרעון אור השכל שלא האיר כ\"כ במוח לפי שהכלי מונע את האור כשאין הכלי זך ובהיר כל צרכו כידוע מפני שאז לא יוכל לקבל האור בכי טוב וכשניתקן הכלי ממילא יתיישב בו חלקי האור בכי טוב, ומה שהארת אור השכל מאיר בכלי המוח בכי טוב נק' בשם בירור המוחין לפי שהראש הוא כלי המוחין והמוחין כאשר מתבררי' להאיר בהמוח בתוס' וריבוי אור זה נק' בשם בירור כו'. והנמשל מזה יובן למעלה בהיות ידוע שההשתל' למעלה באצי' הוא בבחי' אורות וכלים כמו אור החכמה הוא בכלי וכן אור החסד כו', והנה מבואר בפע\"ח<sup data-n=\"4543\">40</sup> בהקדמה<sup data-n=\"4544\">41</sup> שיש ב' מדרגות בי\"ס דאצי', הא' כמו שהן מתחלת אצילותן מהמאציל באו\"כ שנמשך להן מן המאציל המשכה תמידית לצורך קיומן העצמי ומה שיסתעף מהן בעולמות כדי סיפוקם בצמצום בלתי תוס' וריבוי מכמו שהן בעצם בתחלה כו', והב' כאשר הן באין בתוספת דהיינו שנמשך בהן בחי' גילוי אור מהמאציל בבחי' תוס' וריבוי אור יתר על המדה מכמו שהן מתחלת אצילותן מן המאציל כו', ותוס' וריבוי הזה הנה אינו בא רק מסיבת המעשה התחתוני' בהעלאת מ\"נ כו' [הג\"ה, וע\"ש בפע\"ח בההקדמה דבחי' זו זהו הנק' בשם יחוד וזיווג ר\"ל המתקת הגבורות בחסדים והמשכת והשפעת הדעת באלקות, וזהו ומלאה הארץ דעה את ה'<sup data-n=\"4545\">42</sup> ונמשך מבחי' והאדם ידע את חוה<sup data-n=\"4546\">43</sup> אדם זהו תשב\"כ ידע את חוה היא תשבע\"פ<sup data-n=\"4547\">44</sup>, ור\"ל ההשפעה מחכ' עילאה בחכמה תתאה, והנה בחי' היחוד הנ\"ל נק' הילוך כמ\"ש במאו\"א אות ה' סעי' יו\"ד, וזהו ענין מעלת הרגל שבה ועל ידה דוקא הוא ענין ההילוך דהיינו ע\"י הבירורים שמלמטה ממשיכי' בחי' והתהלכתי בתוככם<sup data-n=\"4548\">45</sup> שהוא תוספת וריבוי האור מסוכ\"ע בממכ\"ע ע\"ד אני אענה את השמים<sup data-n=\"4549\">46</sup> והם יענו את הארץ כדפי' בזח\"ב יתרו דפ\"ה סע\"ב, עכ\"ה]. משא\"כ מדריגת עצמותם כמו שהן א\"צ למעשה התחתוני' אלא בתמידית יבוא להן שפעם ממילא כנ\"ל בשביל קיום העולמות כו'.",[["4540","37","<b>יובן</b>: מכאן מתחיל לשון מאמרי אדה\"ז תקס\"ה ח\"ב כאן ע' תשסא."],["4541","38","<b>שנעוץ תחב\"ס וסופן בתחלתן</b>: ראה ס\"י פ\"א, מ\"ז."],["4542","39","<b>רפואה. . לרגל כדי שירפא. . הראש</b>: ראה גם לעיל מאמר ד\"ה ומקנה רב ובהערה 25."],["4543","40","<b>מבואר בפע\"ח</b>: מכאן ועד סיום הפיסקא נעתק גם לעיל במאמר ד\"ה ישמח משה על יד הערה 98 ואילך (בשינויים קלים)."],["4544","41","<b>בפע\"ח בהקדמה</b>: השוה חסד לאברהם מעין ראשון נהר ו."],["4545","42","<b>ומלאה הארץ דעה את ה'</b>: נסמן לעיל בהמשך חייב אדם לברך פכ\"ד הערה 883."],["4546","43","<b>והאדם ידע את חוה</b>: בראשית ד, א."],["4547","44","<b>אדם זהו תשב\"כ. . חוה היא תשבע\"פ</b>: ראה לעיל המשך חייב אדם לברך פכ\"ו ובהערה 987."],["4548","45","<b>והתהלכתי בתוככם</b>: בחוקותי כו, יב."],["4549","46","<b>אני אענה את השמים</b>: נסמן לעיל המשך חייב אדם לברך ספל\"ב הערה 1295."]]],[2000450422,"<b>והנה</b> ענין הבירור הנ\"ל עד\"מ מאור השכל בכלי הראש שניתוסף ונתרבה כו' ה\"ז בחי' תוס' וריבוי אור הנ\"ל שאינו בא אלא ע\"י מעשה התחתוני', והוא ע\"י בחי' הבירורי' דרפ\"ח נצוצין<sup data-n=\"4550\">47</sup> כו' שנק' העלאת מ\"ן כידוע וה\"ז כמשל הנ\"ל ברפואה שעושין לרגל כדי שירפא כל הראש שעי\"ז ניתוסף האור כו' ונק' בירור המוחין כו', וזהו כל עיקר טעם ענין הידוע דבאתעדל\"ת נעשה אתעדל\"ע<sup data-n=\"4551\">48</sup> דלכאו' אינו מובן איך יתכן שהנבראי' בע\"ג שאין להם ערך כלל עם הבורא כידוע שהי'<sup data-n=\"4552\">49</sup> זה ביכולתם לעורר אתעדל\"ע שבבחי' האצי' דהיינו להיות תוספת האורות בכלים כנ\"ל. אך הענין הוא מפני ההתכללו' דנעוץ סופן בתחלתן ותחב\"ס ויש ברגל מה שבראש עד שהראש ירפא ברפואת הרגל כנ\"ל, וא\"כ ע\"י הבירור דמעשה התחתוני' יכול להיות ג\"כ למעלה בחי' תוספת האורות בכלים כמו תוספת המוחין בראש שזהו הנק' אתדל\"ע [ובחי'<sup data-n=\"4553\">50</sup> זו נק' רפואה כי כנס\"י הוא בחי' חולת אהבה ועז\"נ סמכוני באשישות<sup data-n=\"4554\">51</sup> כמ\"ש בפ' יתרו בד\"ה<sup data-n=\"4555\">53</sup> משה ידבר<sup data-n=\"4556\">52</sup> [ה<sup data-n=\"4557\">54</sup>. ועיין בזהר פ' נח דס\"ו ע\"ב בפי' הפסוק וירפא את מזבח ה' ההרוס<sup data-n=\"4558\">55</sup> עכ\"ה] וזהו שאנו אומרים ברוך אתה הוי' פי' ברוך שיומשך האור בכלי בבחי' תוס' ברכה וריבוי אור כנ\"ל להיות יציאת ההעלם לגילוי באתה ביתר שאת וכנ\"ל וזהו ע\"י העלאת מ\"נ ומטעם הנ\"ל. וזהו שרש ענין והארץ הדום רגלי כו' דהנה כנ\"י נק' רגל כנ\"ל משום דברא כרעא דאבוה כו', והנה מפני שנעוץ תחלתן בסופן דהיינו הראש ברגל כנ\"ל, ע\"כ יש ביכולת כנ\"י באתעדל\"ת שלהם לגרום למעלה בחי' אתעדל\"ע בראש ומוחין דהיינו להיות בחי' תוספת וריבוי האור בכלי, אך צ\"ל והארץ הדום רגלי, היינו שצ\"ל בחי' שרפרף שנק' הדום להרים ולהגביה בחי' הרגל הנ\"ל. וזהו ענין אחר והוא משום דגם שנעוץ תחלתן בסופן אבל מ\"מ בחי' הרגל ירד ונשתלשל מאד בירידות המדרגות למטה מטה כמשל מי שיושב על הכסא שרגליו יורדי' ונשפלים למטה ביותר ויוכלו מחמת זה להתחלש כחם כו' וצריך שיגביהו אותם דהיינו לסעדם ולתמכם בשרפרף קטן כנ\"ל. כך הנמשל למעלה דכמו שירדה כנ\"י למטה בגופי' גשמי' כו' כך בחי' מל' דאצי' למעלה יורדת למטה בבי\"ע להחיות רוח שפלים כו' בירידת המדרגות מאד עד להחיות ג\"כ שרים דנוגה דעשיי' ויוכל להיות שם יניקת הקליפות ביותר וכמ\"ש רגליה יורדות<sup data-n=\"4559\">56</sup> כו' [ועיין מזה בזח\"ב פקודי דרמ\"א ע\"א<sup data-n=\"4560\">57</sup>] שלכן צריך להרגלים",[["4550","47","<b>דרפ\"ח ניצוצין</b>: ראה ע\"ח שער רפ\"ח שי\"ח, פ\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151537\" data-slug=\"likkutei-sichot\" data-id=\"1300151537\">לקו\"ש וישב כרך טו ע' 524</a> (אג\"ק שלו ח\"ב ע' כא). וש\"נ. מאמרי אדה\"א דברים ח\"ד ע' א'קעד. וש\"נ."],["4551","48","<b>דבאתעדל\"ת נעשה אתעדל\"ע</b>: ראה זהר לך פח, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540430\" data-slug=\"torat-chaim\" data-id=\"2300540430\">תו\"ח שמות ח\"א מא, א</a> ובהערה 189."],["4552","49","<b>שהי'</b>: במאמרי אדה\"ז תקס\"ה כאן: שיהי'."],["4553","50","<b>[ובחי'</b>: ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316270474\" data-slug=\"or-hatorah-hb\" data-id=\"8316270474\">אוה\"ת בראשית כאן ע' תעד</a>: ובחי'. אבל בבוך 1162 — במאמר אדה\"ז עם הגהות הצ\"צ — הובא כבפנים. וראה לקמן הערה 54."],["4554","51","<b>סמכוני באשישות</b>: שה\"ש ב, ה."],["4555","53","<b>בפ' יתרו בד\"ה משה ידבר</b>: תו\"א שם סח, א."],["4556","52","<b>בפ' יתרו</b>: בבוך 1162: בת\"א. ותיקן כ\"ק אדמו\"ר מהר\"ש בין השיטין: בפ' יתרו."],["4557","54","<b>[ה.</b>: בבוך 1162: [ה והניח מקום פנוי. כ\"ק אדמו\"ר מהר\"ש מחק את החצאי ריבוע שלפני אות ה. בלקו\"ת לג\"פ כאן יג, ד לא העתיק גם את אות ה והניח מקום פנוי. באוה\"ת בראשית כאן: (הג\"ה. וראה לעיל הערה 50."],["4558","55","<b>וירפא את מזבח ה' ההרוס</b>: מל\"א יח, ל."],["4559","56","<b>רגליה יורדות</b>: משלי ה, ה."],["4560","57","<b>ועיין מזה בזח\"ב פקודי דרמ\"א ע\"א</b>: ראה גם לעיל מאמר ד\"ה ומקנה רב על יד הערות 101-102. ד\"ה בנים אתם על יד הערה 18."]]],[2000450423,"העלאה והגבהה למעלה באיזה סעד בכדי שלא ירדו בחי' הרגלים למטה כ\"כ, וזהו ענין השרפרף הנק' הדום רגלי כו' והוא בחי' תשבע\"פ שנק' ארץ מטעם המבואר בביאור הראשון<sup data-n=\"4561\">58</sup> וגם ע\"י מצות מעשיות כמ\"ש שם הטעם [ועי\"ז<sup data-n=\"4562\">59</sup> נעשה עליית כנ\"י למעלה מעלה וצדקה תרומם גוי שיהי' הרגל בבחי' ראש מלמטה למעלה כו'<sup data-n=\"4563\">60</sup> [הג\"ה, וכענין שלש רגלים תחוג לי<sup data-n=\"4564\">61</sup> כו' בנהר יעברו ברגל<sup data-n=\"4565\">62</sup> כו' למעלה מבחי' ונהר יוצא מעדן<sup data-n=\"4566\">63</sup> כו', וזהו ענין מהלכים ב' בחי' הילוך, הא' מלמעלמ\"ט שע\"י הרגל נמשך תוס' אור במוחין והן נמשכים ומתגלים מלמעלה למטה כו' כנ\"ל, הב' שמלמטה למעלה הרי הרגל בבחי' ראש כו' וכמ\"ש באג\"ה בד\"ה איהו וחיוהי<sup data-n=\"4567\">64</sup> וגם הקו מאור א\"ס המסתיים ברגלי<sup data-n=\"4568\">65</sup> א\"ק מאיר מלמטה<sup data-n=\"4569\">66</sup> למעלה בבחי' אור חוזר, עכ\"ה]. * ובזה יובן מ\"ש<sup data-n=\"4570\">68</sup> בישעי' סי' נ\"ח י\"ג<sup data-n=\"4571\">69</sup> אם תשיב משבת רגליך [עשות חפציך ביום קדשי וגו', שבת קיח\"ב, קיג\"א, קיט\"א, קנ\"א, פסחים סח\"ב, ביצה לד\"ב, ובמצ\"ד פי' דהיינו שלא יצא חוץ לתחום. והענין] דמבואר בלק\"ת מהאריז\"ל פ' בשלח<sup data-n=\"4572\">70</sup> בטעם תחום שבת אלפים אמה [שהם המקום פנוי שבין הסט\"א ובין נהי\"מ דעשיי', היינו כי בשבת נהי\"מ דעשיי' נפרדי' מן הקליפות ועולים למעלה בחג\"ת, משא\"כ בחול רגליה יורדות שנה\"י דעשיי' מתקרב למקום הקליפות כו'. וכאשר עולים נהי\"מ בשבת ומתרחקת מהקליפה נשאר חלל ומקו\"פ ביניהם ובין הקליפה אלפים אמה כו' והעושה מלאכה בשבת גורם הכנסת הקליפה למקום החלל ונדבקים בקדושה כמו בחול וזהו ענין מחללי'<sup data-n=\"4573\">71</sup> כו' ע\"ש. ועיין מענין מחלליה בזח\"א ד\"ו תחלת ע\"א], ועל אותו בחי' החלל הוזהרו בנ\"י שלא יצאו בו ברגלם אלא יאספו את רגלם לתוך",[["4561","58","<b>תשבע\"פ שנק' ארץ. . בביאור הראשון</b>: מאמר ד\"ה בנים אתם על יד הערה 107."],["4562","59","<b>[ועי\"ז</b>: ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480233\" data-slug=\"or-hatorah-hb\" data-id=\"8316480233\">אוה\"ת בראשית כאן ע' 948</a>: ועי\"ז."],["4563","60","<b>כו'</b>: בלקו\"ת לג\"פ כאן יד, א: כו']. בבוך 1162 הובא כבפנים."],["4564","61","<b>שלש רגלים תחוג לי</b>: משפטים כג, יד."],["4565","62","<b>בנהר יעברו ברגל</b>: תהלים סו, ו. ראה גם לעיל מאמר ד\"ה ומקנה רב ובהערה 41."],["4566","63","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["4567","64","<b>באג\"ה בד\"ה איהו וחיוהי</b>: ס\"כ ( תניא — קלב, א)."],["4568","65","<b>ברגלי</b>: באגה\"ק: בסיום רגלי."],["4569","66","<b>מלמטה</b>: שם: ממטה."],["4570","68","<b>ובזה יובן מ\"ש בישעי'</b>: (מכאן) ”חציו השני של דרוש זה לא נאמר במוציו\"ט ונכלל בד\"ה בראשית שלאחריו\" — רשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש שבספר התולדות שלו (קה\"ת תש\"ז) ע' 48 הערה 1. מכאן ואילך נעתק גם לקמן במאמר ד\"ה בראשית על יד הערה 37 ואילך."],["4571","69","<b>בישעי' סי' נ\"ח י\"ג</b>: במאמרי אדה\"ז תקס\"ה כאן ע' תשסב: בשבת."],["4572","70","<b>בלק\"ת מהאריז\"ל פ' בשלח</b>: בטעמי המצות. במאמרי אדה\"ז תקס\"ה כאן: בכתבי האריז\"ל. ראה גם לעיל מאמר ד\"ה בנים אתם על יד הערה 30."],["4573","71","<b>מחללי'</b>: תשא לא, יד."]]],[2000450424,"התחום דקדושה וכמ\"ש אל יצא איש ממקומו<sup data-n=\"4574\">72</sup> כו' וגם למעלה בחי' נה\"י נק' רגליך וע\"ז אמר אם תשיב משבת רגליך שצריך לאסוף בחי' נה\"י דקדושה להגביהם כלפי מעלה בשבת ולא ירדו כ\"כ למטה בבחי' חלל דקליפה לגרום להם ג\"כ שפע המוחין דשבת כו' [וע' מענין אל יצא איש ממקומו בזח\"ב בשלח דס\"ג סע\"ב ובפ' ויקהל דר\"ז ע\"א דהא מיניה לבר אתר דאלקי' אחרים איהו כו' ממקומו דא כבוד דלתתא ושם פי' דאלפים אמה הם נגד שהמל' הנק' מקום בנינה משני בחי' חו\"ג ושרשם מחו\"ב הנק' אאלפך חכ' ובינה<sup data-n=\"4575\">73</sup>, שמחו\"ב אין להם יניקה כו'], ומזה יובן ג\"כ דרך<sup data-n=\"4576\">74</sup> כלל על כל פגם וחסרון שנעשה ע\"י כל ל\"ת כמו לאו דכלאים לא תלבש שעטנז<sup data-n=\"4577\">75</sup> כו' וכיוצא שעי\"ז גורם ירידת שפע הקדושה להיות משכנה בבחי' החלל והפגם דסט\"א וכמ\"ש ולא תחללו<sup data-n=\"4578\">76</sup> כו' וכמ\"ש זה הענין במ\"א, והוא ע\"ד ענין הנ\"ל בירידת בחי' הרגל למטה כו' [ומזה יובן ענין והארץ הדום רגלי שע\"י קיום המצות גורמים הגבהת בחי' רגלי שהם נהי\"מ דקדושה שיהיו נפרדי' מהקליפות ויתעלו למעלה, וזהו וצדקה תרומם גוי, דפי' גוי היינו שיגביה נה\"י המרומזי' באות ג' דגוי שיתכללו בחג\"ת בחי' וא\"ו<sup data-n=\"4579\">*77</sup> כו' והיינו ע\"י צדקה, שפי' בלק\"ת מהאריז\"ל בישעי' שם<sup data-n=\"4580\">77</sup> שרגל הקוף מורה על רגליה יורדות מות, וכשנפרד הרגל מהקליפות נעשה מזה ה', וזה מרומז בצדקה שיש בה קוף הא כו' וידוע שכל המצות נק' בשם צדקה וכמ\"ש וצדקה תהי' לנו<sup data-n=\"4581\">78</sup> כי נשמור לעשות את כל מצות ה'<sup data-n=\"4582\">79</sup> כו', היינו כי ע\"י קיום המצות נעשה בחי' עליות נהי\"מ שיתפרדו מהסט\"א ואזי יעלו למעלה, ועי\"ז גורם עליות כל העולמות למעלה מעלה כמבואר מענין עליות דשבת שהתחלה עליות נהי\"מ דעשיי' וזה גורם גם עליות כח\"ב דאצי' למעלה כו' כמבואר בד\"ה את שבתותי תשמרו<sup data-n=\"4583\">80</sup>, הרי שהרגל מגביה את הראש א\"כ הראש מקבל מהרגל, וכ\"ז ע\"י והארץ הדום רגלי שהוא מעשה המצות ותשבע\"פ הנקראי' ארץ שהם בחי' הדום להגביה הרגל ע\"ד אם תשיב משבת רגליך כו' ועי\"ז וקראת לשבת ענג כו' המשכת וגילוי ענג העליון.\n<span data-k=\"ks\"><b>קיצור.</b> ענין והארץ מצות הדום להגביה כנ\"י הנק' רגל שלא יהי' רגליה יורדות, ותחלה יבאר ענין הרגל שיש בכחה להוליך את הראש או לרפאו כי נעוץ </span>",[["4574","72","<b>אל יצא איש ממקומו</b>: בשלח טז, כט."],["4575","73","<b>אאלפך חכ' ובינה</b>: איוב לג, לג. שבת קד, א."],["4576","74","<b>דרך</b>: במאמרי אדה\"ז תקס\"ה כאן: בדרך."],["4577","75","<b>לא תלבש שעטנז</b>: תצא כב, יא."],["4578","76","<b>ולא תחללו</b>: אמור כב, לב. ראה מאמר ד\"ה זה במאמרי אדה\"ז תקס\"ב ח\"ב ע' שפו ואילך. תקס\"ה ח\"ב ע' תרעה ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550219\" data-slug=\"torat-chaim\" data-id=\"2300550219\">תו\"ח תצוה ח\"ב שנז, ב</a>. וש\"נ."],["4579","*77","<b>גוי. . נה\"י. . בחג\"ת. . וא\"ו</b>: ראה גם לעיל מאמר ד\"ה בנים אתם על יד הערה 71 ואילך. וש\"נ."],["4580","77","<b>בלק\"ת מהאריז\"ל בישעי' שם</b>: נד, יד עה\"פ בצדקה תכונני."],["4581","78","<b>המצות. . וצדקה תהי' לנו</b>: ואתחנן ו, כה. ראה מאמרי אדה\"א ויקרא ח\"ב ע' עדרת. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540914\" data-slug=\"torat-chaim\" data-id=\"2300540914\">תו\"ח שמות ח\"א יד, א</a> ובהערה 628. לעיל מאמר ד\"ה בנים אתם על יד הערה 20. לקמן מאמר ד\"ה בראשית על יד הערה 16 (ובין הערות 47-48). ו(בחלק ההנחות) הנחה ד\"ה ומקנה רב על יד הערה 125. ד\"ה בנים אתם על יד הערה 55."],["4582","79","<b>מצות ה'</b>: בואתחנן שם: המצוה הזאת לפני ה'."],["4583","80","<b>בד\"ה את שבתותי תשמרו</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380263\" data-slug=\"likkutei-torah\" data-id=\"4001380263\">לקו\"ת בהר מג, ד</a>."]]],[2000450425,"<b>סופן</b> בתחלתן, ויש בע\"ס ב' בחי' מה שיש להם חיות קצוב, ותוס' וריבוי האור והוא הנק' הילוך וזה נמשך ע\"י אתעדל\"ת מהבירורי' וזהו ענין ההילוך ע\"י הרגל, והרפואה לחולת אהבה, בא\"י אמ\"ה, והתהלכתי, אני אענה את השמים והם יענו את הארץ, ענין שלש רגלים, בנהר יעברו ברגל, אך לפי שרגלי' יורדות מחמת חטא עה\"ד שנתערב הקליפה בקדושה סד\"ה ראה ריח בני<sup data-n=\"4584\">81</sup>, צ\"ל הדום רגלי וזהו אם תשיב משבת רגליך, שיתפרדו נהי\"מ מהקליפות, ומרומז בתיבת צדקה מקוף רגל ארוך מה שרגליה יורדות נעשה הא.\n<b>ועפ\"ז</b> אפשר לומר בענין המרגלים שהוא ג\"כ מלשון רגל<sup data-n=\"4585\">82</sup> היינו מה שירדו ונשלחו לברר ארץ כנען שהיתה בחי' רגליה יורדות, והם היו מבחי' דכורא<sup data-n=\"4586\">83</sup> ע\"כ נשלחו לתקן בחי' רגליה יורדות כו' שיהי' ע\"ד ויעל אברם ממצרים<sup data-n=\"4587\">84</sup> כו', עיין בת\"א ר\"פ יתרו בד\"ה בחדש השלישי, ועיין בהרמ\"ז פ' שלח פי' ג\"כ ענין המרגלים ע\"ד הנ\"ל, ורגל פירושו חפוש דהיינו העצה שיפשפש במעשיו<sup data-n=\"4588\">85</sup> ע\"ד ושם דרך<sup data-n=\"4589\">86</sup> כל השם אורחותיו<sup data-n=\"4590\">87</sup> כו' וכענין יהושע וכלב, וכן בכל אדם בעת עסקיו בעניני עוה\"ז ובפרט בבעל עסק הרי מתפשט ע\"כ הרגל למטה בק\"נ, אלא שכאשר מקיים בכל דרכיך דעהו<sup data-n=\"4591\">88</sup> שלא להתדבק ממש בהם רק ע\"ד בא אחיך במרמה<sup data-n=\"4592\">89</sup>, שמה שהוא בחי' אחיך של היצה\"ר באכילה ושתי' אין זה רק בבחי' כדי לברר וכמו שאומרים ואספת דגנך<sup data-n=\"4593\">90</sup> בק\"ש דוקא עי\"ז אח\"כ נעשו מה יפו פעמיך בנעלים ועמ\"ש ע\"פ ואנכי תרגלתי לאפרים<sup data-n=\"4594\">91</sup> בלק\"ת ס\"פ פנחס<sup data-n=\"4595\">92</sup> שנמשך בחי' אנכי בבחי' רגל היינו במצות מעשיות שיהיו עי\"ז בחי' הדום רגלי כנ\"ל ועי\"ז קחם על זרועותיו ע\"ד וצדקה תרומם גוי כנ\"ל.",[["4584","81","<b>סד\"ה ראה ריח בני</b>: תו\"א תולדות כא, ב."],["4585","82","<b>המרגלים. . מלשון רגל</b>: ראה גם לעיל מאמר ד\"ה ומקנה רב ובהערה 59."],["4586","83","<b>המרגלים. . מבחי' דכורא</b>: ראה רמ\"ז לזהר שלח קנח, א."],["4587","84","<b>ויעל אברם ממצרים</b>: לך יג, א."],["4588","85","<b>שיפשפש במעשיו</b>: ברכות ה, א. עירובין יג, ב."],["4589","86","<b>ושם דרך</b>: תהלים נ, כג. ראה הגהות הב\"ח סוטה ה, ב אות א."],["4590","87","<b>כל השם אורחותיו</b>: מוע\"ק ה, סע\"א. ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה ישמח משה הערה 24."],["4591","88","<b>בכל דרכיך דעהו</b>: משלי ג, ו."],["4592","89","<b>בא אחיך במרמה</b>: תולדות כז, לה."],["4593","90","<b>ואספת דגנך</b>: עקב יא, יב."],["4594","91","<b>ואנכי תרגלתי לאפרים</b>: הושע יא, ג."],["4595","92","<b>בלק\"ת ס\"פ פנחס</b>: פ, ב ואילך."]]],[2000450426,"<span data-k=\"ks\"><b>קיצור.</b> ענין המרגלים הי' לתקן בחי' רגליה יורדות ולעשות הדום לבחי' רגל, ע\"ד ושם דרך, ואנכי תרגלתי לאפרים, עכ\"ה<sup data-n=\"4596\">93</sup>].</span>",[["4596","93","<b>עכ\"ה</b>: ההג\"ה מתחלת לעיל בתיבת: [ומזה — אחר ציון 76 בפנים."]]],[2000450427,"<h3>בראשית כו'</h3>\n<b>בס\"ד פ' בראשית תרל\"ט</b>\n<b></b>מעלת אתכפיא כו' הדום רגלי כו' מרגלים כו' תהו ותקון - ב' קיצורים\nבראשית\n<b>בראשית</b> ברא<sup data-n=\"4597\">1</sup> אלקי'<sup data-n=\"4598\">2</sup> את השמים ואת כו' והארץ היתה תהו<sup data-n=\"4599\">3</sup> כו', וצ\"ל ענין אומרו והארץ היתה תהו, הלא בעה\"ת<sup data-n=\"4600\">4</sup> הי' כל הספירות שבתיקון רק שהיו בחי' נקודות זת\"ז<sup data-n=\"4601\">5</sup> כנודע, ומהו והארץ דוקא. וגם משמע שזהו כעין נתינת טעם על בריאת שמו\"א שאמר תחלה, וצ\"ל מהו. והענין הוא דהנה עיקר בחי' הבירורים מבחי' התהו שנשארו שלא נתבררו בדרך בירור שמלמעלמ\"ט, כ\"א שיבוררו בדרך בירור מלמטלמ\"ע ע\"י עבודת האדם כמשי\"ת זהו בבחי' ארץ בחי' מ'<sup data-n=\"4602\">6</sup> ש'<sup data-n=\"4603\">8</sup> ב\"ן<sup data-n=\"4604\">7</sup> דוקא. וכנודע שב\"ן הוא המתברר ע\"י בחי' ש' מ\"ה<sup data-n=\"4605\">9</sup> דתיקון המברר אותו, ופי' מ\"ה הוא בחי' ביטול בכלל, ועיקרו בחי' מ\"ה דחכ' שהוא בחי' ביטול אמיתי דיחו\"ע וכמו שאמר משה בחי' יסו\"א<sup data-n=\"4606\">10</sup> ונחנו מה<sup data-n=\"4607\">11</sup> כו' וכמו שא' בס\"י ע\"ס בלי מה שפי' בלי שום מהות<sup data-n=\"4608\">12</sup>, ואמנם בכדי לבוא לבחי' זה זהו ע\"י בחי' ביטול היש לאין, וזהו שארז\"ל גדולים מע\"צ<sup data-n=\"4609\">13</sup> ממעשה שמים וארץ, דאלו מעשה שמים וארץ הם בחי' בריאה יש מאין, אבל ע\"י עבודת האדם בתומ\"צ שעי\"ז נא' ועמך כולם צדיקי'<sup data-n=\"4610\">14</sup> וכמ\"ש מזה בד\"ה ויהיו כל הפקודי' (חה\"ש ך\"ו)<sup data-n=\"4611\">15</sup> שהמקיים המצות נק' צדיק ע\"ש שכל",[["4597","1","<b>בראשית ברא</b>: מאמר זה הוא דרוש השלישי שמבאר פיסקא שלישית שבביאור השני (על מאמר ד\"ה השמים כסאי) ד\"ה להבין שרשי הדברים הנ\"ל שנדפס במאמרי אדה\"ז תקס\"ה ח\"ב הנחת כ\"ק אדמו\"ר האמצעי ע' תשסב — תשסד. והוא דרוש הי\"א מההמשך שבו נתבארו הדרושים דהשמים כסאי ושני ביאוריו שנאמרו בשנת תקס\"ה כמצויין לעיל ברד\"ה ואשא אתכם.\nדרוש זה (מתחיל מלקמן ד\"ה אך הנה עדיין) הוא לשון מאמרי אדה\"ז תקס\"ה הנ\"ל עם הגהות הצ\"צ שבאים בתוך חצאי ריבוע. חלק מהמאמר מתחיל מהתיבות: ”וזהו דכתיב\" נדפס גם לעיל במאמר ד\"ה מה יפו. ומלקמן ד\"ה ”אך הנה עדיין\" נדפס גם בלקו\"ת לג\"פ בראשית יד, ג ואילך. וב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560017\" data-slug=\"or-hatorah-hb\" data-id=\"8316560017\">אוה\"ת בראשית כרך ג ע' תעה</a> ואילך. הכותרת שבראש המאמר נעתקה מבוך 363 כת\"י מעתיק ע' רפג.\nמאמר זה נזכר לקמן במאמר ד\"ה זה עני על יד הערות 58. 53.\nהמאמר נמצא בבוך 1069 שכולל הדרושים שנאמרו בשנת תרל\"ט."],["4598","2","<b>בראשית ברא אלקי'</b>: בראשית א, א."],["4599","3","<b>והארץ היתה תהו</b>: שם א, ב."],["4600","4","<b>בעה\"ת</b>: בעולם התהו."],["4601","5","<b>בעה\"ת. . הספירות. . נקודות זת\"ז</b>: ראה ע\"ח שער הכללים פ\"א. שער התיקון ש\"י, פ\"ה. (ובנוסף להערה 1) לעיל מאמר ד\"ה ישמח משה ובהערה 74."],["4602","6","<b>ארץ בחי' מ'</b>: ראה זהר תוספתא בראשית לא, ב."],["4603","8","<b>מ' ש' ב\"ן</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"ג. שעה\"י קמה, א. הערה 14."],["4604","7","<b>ארץ. . ש' ב\"ן</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540851\" data-slug=\"torat-chaim\" data-id=\"2300540851\">תו\"ח בשלח ח\"א קעה, ב</a>. וש\"נ."],["4605","9","<b>שב\"ן הוא המתברר. . ש' מ\"ה</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."],["4606","10","<b>משה בחי' יסו\"א</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061254\" data-slug=\"likkutei-sichot\" data-id=\"1300061254\">לקו\"ש שמות כרך ו ע' 244</a> ואילך."],["4607","11","<b>ונחנו מה</b>: נסמן לעיל במאמר ד\"ה ישמח משה הערה 5."],["4608","12","<b>בס\"י ע\"ס בלי מה. . מהות</b>: פ\"א, מ\"ד ובמפרשים שם."],["4609","13","<b>גדולים מע\"צ</b>: ראה כתובות ה, א. מאמרי אדה\"א ויקרא ח\"ב ע' תתי. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670399\" data-slug=\"torat-chaim\" data-id=\"2300670399\">תו\"ח בראשית כה, ג</a> ובהערה 25. תצוה ח\"ב שכד, ד. סה\"מ תרל\"ו ח\"ב ע' רמב."],["4610","14","<b>ועמך כולם צדיקי'</b>: ישעי' ס, כא."],["4611","15","<b>בד\"ה ויהיו כל הפקודי' (חה\"ש ך\"ו)</b>: סה\"מ תרכ\"ו ע' קד. וראה גם הנסמן שם בריש הספר ע' לד\"ה שאו כו' ויהיו כל הפקודי'. לקמן (בחלק ההנחות) הנחה ד\"ה ושמרתם את חוקותי ובהערה 4."]]],[2000450428,"המצות נק' בשם צדקה כמ\"ש וצדקה תהי' לנו<sup data-n=\"4612\">16</sup> כי נשמור לעשות את כל המצוה כו', הנה עי\"ז פועלים להיות בחי' ביטול היש לאין, ולכן גדולים מע\"צ, וי\"ל פי' מעשה ל' כפי' והכרח<sup data-n=\"4613\">17</sup> מל' גט מעושה<sup data-n=\"4614\">18</sup>, מעשין על הצדקה<sup data-n=\"4615\">19</sup>, ל' כפי', שהעיקר הוא בחי' אתכפי', וע\"י אתכפי' יבוא לבחי' אתהפכא שזהו בחי' ביטול אמיתי דמ\"ה דחכ' כו', וע' בד\"ה קחו מאתכם תרומה, שבעבודה גבהה מעלת אתכפי'<sup data-n=\"4616\">20</sup> יותר מבחי' אתהפכא, הגם שבעצם אתהפכא גבוה יותר וזהו שלימות המכוון, וכמ\"ש בהקדמת הזהר מאן מנכון<sup data-n=\"4617\">21</sup> דלא מהפך מחשוכא לנהורא כו' לית לי' חולקא הכא, מ\"מ בעבודה אתכפי' חשוב יותר כי אחר שפועל בעצמו בחי' אתהפכא שוב א\"צ לעבודה כ\"כ כו', וגם מפני כי הבירור הוא ע\"י אתכפי' דוקא.\n<b>וענין</b> בחי' הבירורים הוא, דהנה כתי' ראה נתתי לפניך<sup data-n=\"4618\">22</sup> את החיים ואת הטוב ואת כו' הרע, ונת' מזה במ\"א שהרע עוד גרוע מבחי' מות<sup data-n=\"4619\">23</sup>, שהרי לטומאת מת יש טהרה, וכמ\"ש מזה באגה\"ק סי' ך\"ח בד\"ה למה נסמכה, משא\"כ רע גמור א\"א להתברר כ\"א שצריכים ללקט ממנו ניצוצי הקדושה המחיים אותו כמ\"ש ואתה מחי' את כולם<sup data-n=\"4620\">24</sup>, אפי' רע (ומ\"ש ובורא רע<sup data-n=\"4621\">25</sup>, י\"ל לא יגורך רע<sup data-n=\"4622\">26</sup> זהו באצי', אבל בבריאה יש מציאות רע וכנודע שבבריאה מיעוטה רע<sup data-n=\"4623\">27</sup>, אבל עכ\"פ נמצא בחי' הרע, וי\"ל שזהו רע בערך האצי' וגם בערך טוב דבריאה וכמובן ממה שית' לקמן בענין הבירור מלמעלמ\"ט שמה שלא יוכל להתברר וליכלל באצי' נפל בבריאה<sup data-n=\"4624\">28</sup>, ועד\"ז מבריאה ליצי' כו', וא\"כ י\"ל שבערך היצי' נק' עדיין טוב, אמנם באמת אינו כן",[["4612","16","<b>שכל המצות. . וצדקה תהי' לנו</b>: ואתחנן ו, כה. ראה מאמרי אדה\"א ויקרא ח\"ב ע' עדרת. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540914\" data-slug=\"torat-chaim\" data-id=\"2300540914\">תו\"ח שמות ח\"א יד, א</a> ובהערה 628. לעיל מאמר ד\"ה בנים אתם על יד הערה 20. ד\"ה מה יפו על יד הערה 78. לקמן (בין הערות 47-48). ו(בחלק ההנחות) בהנחה ד\"ה ומקנה רב על יד הערה 125. ד\"ה בנים אתם על יד הערה 55."],["4613","17","<b>מעשה ל' כפי' והכרח</b>: ראה גם לעיל מאמר ד\"ה על חומותיך ובהערה 123."],["4614","18","<b>גט מעושה</b>: גיטין פח, ב (במשנה)."],["4615","19","<b>מעשין על הצדקה</b>: ב\"י לטור יו\"ד סרמ\"ח. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121246\" data-slug=\"likkutei-sichot\" data-id=\"1300121246\">לקו\"ש</a> ל\"ג בעומר כרך יב ע' 238 ובהנסמן שם."],["4616","20","<b>בד\"ה קחו מאתכם תרומה. . מעלת אתכפי'</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370402\" data-slug=\"torah-or\" data-id=\"3901370402\">תו\"א ויקהל פט, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370511\" data-slug=\"torah-or\" data-id=\"3901370511\">קיד, ג</a> ואילך. ראה אוה\"ת על ענינים ע' רד ואילך. וש\"נ. מאמר ד\"ה כימי צאתך י\"א ניסן תשמ\"ב (קונ' י\"א ניסן תשמ\"ז — סה\"מ מלוקט ב ע' מא)."],["4617","21","<b>בהקדמת הזהר מאן מנכון</b>: ראה שם ד, א."],["4618","22","<b>ראה נתתי לפניך</b>: נצבים ל, טו [בדילוג]."],["4619","23","<b>שהרע עוד גרוע מבחי' מות</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' קסג ובהנסמן בריש המאמר שם. המשך תער\"ב ח\"א ע' רכג."],["4620","24","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו. ראה גם לעיל מאמר ד\"ה לה\"ע הנוסח וכו' באש הצתה ובהערה 52."],["4621","25","<b>ובורא רע</b>: ישעי' מה, ז."],["4622","26","<b>לא יגורך רע</b>: תהלים ה, ה. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380322\" data-slug=\"likkutei-torah\" data-id=\"4001380322\">לקו\"ת במדבר ג, ג</a>."],["4623","27","<b>שבבריאה מיעוטה רע</b>: ראה ע\"ח שער ק\"נ שמ\"ט, פ\"ו. מאמרי אדה\"א דברים ח\"ד ע' א'תצג. וש\"נ. אוה\"ת נח כרך ג' ע' 1200 ואילך."],["4624","28","<b>שמה שלא יוכל להתברר. . נפל בבריאה</b>: ראה ע\"ח שער מ\"ן ומ\"ד של\"ט, דרוש ד. שער כללות אבי\"ע שמ\"ב פ\"ג. לקמן ובהערות 90-91. (בנוסף להערה 1) מאמרי אדה\"ז תקס\"ה ח\"א ע' תק. ח\"ב ע' תשנא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550256\" data-slug=\"torat-chaim\" data-id=\"2300550256\">תו\"ח תשא ח\"ב שפה, ג</a>. וש\"נ."]]],[2000450429,"שמ\"ש מיעוטו רע הכוונה שנתערב בו מעט רע, אם ממה שנשאר משה\"כ, או ממה שניתוסף בחטא עה\"ד (והגם שעה\"ד מתחיל ביצי'<sup data-n=\"4625\">29</sup> כנודע מ\"מ יש פגמו גם בבריאה כו' ואכמל\"ב) ממש שצריך להתברר ותלוי בעבודת האדם בבחי' הבירור בעשיי' דוקא מלמטלמ\"ע וכמשי\"ת אי\"ה) והוא ע\"י מעשה ל' כפי' והכרח לקיים כל השס\"ה ל\"ת בבחי' אתכפי' דוקא, וכמארז\"ל אל יאמר אדם א\"א בבשר חזיר אלא אפשי ואבי שבשמים גזר עלי<sup data-n=\"4626\">30</sup>, וכן בכל השס\"ה ל\"ת<sup data-n=\"4627\">31</sup>, ולהזהר בכל רמ\"ח מ\"ע לקיים כמצוה עלינו כו' בבחי' עבודת עבד, וע' בלק\"ת<sup data-n=\"4628\">32</sup> בד\"ה ועתה יגדל נא, ובהביאור שם. והענין הוא דכתי' רגלי' יורדות<sup data-n=\"4629\">33</sup> כו' מחמת חטא עה\"ד שנתערב הקלי' בקדושה ע' בפ' תולדות סד\"ה ראה ריח בני<sup data-n=\"4630\">34</sup>, וגם הנה נודע שבתחלת הבריאה נפל בהם ניצוצות משה\"כ דתהו, וע\"י חטא עה\"ד ניתוסף כו', ולכן רגלי' יורדות כו' וצריכים להגביהם כו', וזהו והארץ היא בחי' מעהמ\"צ<sup data-n=\"4631\">35</sup> הם הדום בחי' שרפרף<sup data-n=\"4632\">36</sup> להגביה את בחי' הרגל מירידתה, וע\"י הגבהת הרגל והפרדתה מירידתה, עי\"ז נמשך תוס' וריבוי אורות בע\"ס דאצי', כי הרגל יש לו מעלה גם בבחי' או\"י והוא במה שנושא הראש, ונוסף לזה שבבחי' או\"ח הנה הרגל הוא ראש, וזהו דכתי'<sup data-n=\"4633\">37</sup> (ישעי' סי' נ\"ח י\"ג)<sup data-n=\"4634\">38</sup> אם תשיב משבת רגליך [עשות חפציך ביום קדשי וגו', שבת קיח\"ב, קיג\"א קיט\"א קנ\"א, פסחים סח\"ב, ביצה לד\"ב, ובמצ\"ד פי' דהיינו שלא יצא חוץ לתחום והענין] דמבואר בלק\"ת מהאריז\"ל פ' בשלח<sup data-n=\"4635\">39</sup> בטעם תחום שבת אלפים אמה [שהם המקום פנוי שבין הסט\"א ובין נהי\"מ דעשיי', היינו כי בשבת נהי\"מ דעשיי' נפרדי' מן הקליפות ועולים למעלה בחג\"ת, משא\"כ בחול רגליה יורדות שנה\"י דעשיי' מתקרב למקום הקליפות כו'. וכאשר עולים נהי\"מ בשבת ומתרחקת מהקליפה נשאר חלל ומקו\"פ ביניהם ובין הקליפה אלפים אמה כו' והעושה מלאכה בשבת גורם הכנסת הקליפה למקום החלל ונדבקים בקדושה כמו בחול וזהו ענין מחללי'<sup data-n=\"4636\">40</sup> כו' ע\"ש. ועיין מענין מחלליה בזח\"א ד\"ו תחלת ע\"א], ועל אותו בחי' החלל הוזהרו בנ\"י שלא",[["4625","29","<b>שעה\"ד מתחיל ביצי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380325\" data-slug=\"likkutei-torah\" data-id=\"4001380325\">לקו\"ת במדבר ד, ב</a>."],["4626","30","<b>אל יאמר אדם א\"א. . גזר עלי</b>: ראה תו\"כ ס\"פ קדושים. שע\"ת עא, סע\"ד ואילך."],["4627","31","<b>וכן בכל השס\"ה ל\"ת</b>: ראה גם של\"ה עש\"מ מט, ב. נד, א (המאמר הששי). שער האותיות בסופו קי, א. תושב\"כ תצא שפד, א. שה\"א ה, א. מאמרי אדה\"א שמות ח\"ב ע' תצג. ויקרא ח\"ב ע' תשנד. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300291250\" data-slug=\"likkutei-sichot\" data-id=\"1300291250\">לקו\"ש ברכה כרך כט ע' 235</a> ובהערה 50. שמונה פרקים להרמב\"ם פ\"ו. לקו\"ת ואתחנן ט, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550244\" data-slug=\"torat-chaim\" data-id=\"2300550244\">תו\"ח משפטים ח\"ב רצד, ג</a>. סהמ\"צ להצ\"צ פד, ב. אוה\"ת משפטים ע' א'קלח. ע' א'קמז. שיחת שבת נצו\"י תשמ\"ב (התוועדויות ח\"ד ע' 2231 ואילך). פרדס חב\"ד גליון ג ע' 29 ואילך. סה\"ש תשנ\"ב ח\"ב ע' 367 הערה 42."],["4628","32","<b>בלק\"ת</b>: שלח לט, א. מ, א. נעתק לעיל במאמר ד\"ה ומקנה רב על יד הערה 118 ואילך."],["4629","33","<b>רגלי' יורדות</b>: משלי ה, ה."],["4630","34","<b>סד\"ה ראה ריח בני</b>: תו\"א תולדות כא, ב."],["4631","35","<b>והארץ היא בחי' מעהמ\"צ</b>: ראה גם לעיל מאמר ד\"ה בנים אתם ובהערה 19."],["4632","36","<b>והארץ. . הדום בחי' שרפרף</b>: ישעי' סו, א. לעיל מאמר ד\"ה ומקנה רב על יד הערה 19 ואילך."],["4633","37","<b>וזהו דכתי'. . עכ\"ה]</b>: נדפס גם לעיל במאמר ד\"ה מה יפו על יד הערה 68 ואילך."],["4634","38","<b>(ישעי' סי' נח י\"ג)</b>: במאמרי אדה\"ז תקס\"ה ח\"ב ע' תשסב: בשבת."],["4635","39","<b>בלק\"ת מהאריז\"ל פ' בשלח</b>: בטעמי המצות. במאמרי אדה\"ז תקס\"ה שם: בכתבי האריז\"ל. ראה גם לעיל מאמר ד\"ה בנים אתם על יד הערה 30."],["4636","40","<b>מחללי'</b>: תשא לא, יד."]]],[2000450430,"יצאו בו ברגלם אלא יאספו את רגלם לתוך התחום דקדושה וכמ\"ש אל יצא איש ממקומו<sup data-n=\"4637\">41</sup> כו' וגם למעלה בחי' נה\"י נק' רגליך וע\"ז אמר אם תשיב משבת רגליך שצריך לאסוף בחי' נה\"י דקדושה להגביהם כלפי מעלה בשבת ולא ירדו כ\"כ למטה בבחי' חלל דקליפה לגרום להם ג\"כ שפע המוחין דשבת כו' [וע' מענין אל יצא איש ממקומו בזח\"ב בשלח דס\"ג סע\"ב ובפ' ויקהל דר\"ז ע\"א דהא מיניה לבר אתר דאלקי' אחרים איהו כו' ממקומו דא כבוד דלתתא ושם פי' דאלפים אמה הם נגד שהמל' הנק' מקום בנינה משני בחי' חו\"ג ושרשם מחו\"ב הנק' אאלפך חכ' ובינה<sup data-n=\"4638\">42</sup>, שמחו\"ב אין להם יניקה כו'], ומזה יובן ג\"כ דרך<sup data-n=\"4639\">43</sup> כלל על כל פגם וחסרון שנעשה ע\"י כל ל\"ת כמו לאו דכלאים לא תלבש שעטנז<sup data-n=\"4640\">44</sup> כו' וכיוצא שעי\"ז גורם ירידת שפע הקדושה להיות משכנה בבחי' החלל והפגם דסט\"א וכמ\"ש ולא תחללו<sup data-n=\"4641\">45</sup> כו' וכמ\"ש זה הענין במ\"א, והוא ע\"ד ענין הנ\"ל בירידת בחי' הרגל למטה כו' [ומזה יובן ענין והארץ הדום רגלי שע\"י קיום המצות גורמים הגבהת בחי' רגלי שהם נהי\"מ דקדושה שיהיו נפרדי' מהקליפות ויתעלו למעלה, וזהו וצדקה תרומם גוי<sup data-n=\"4642\">46</sup>, דפי' גוי היינו שיגביה נה\"י המרומזי' באות ג' דגוי שיתכללו בחג\"ת בחי' וא\"ו כו' והיינו ע\"י צדקה, שפי' בלק\"ת מהאריז\"ל בישעי' שם<sup data-n=\"4643\">47</sup> שרגל הקוף מורה על רגליה יורדות מות, וכשנפרד הרגל מהקליפות נעשה מזה ה', וזה מרומז בצדקה שיש בה קוף הא כו' וידוע שכל המצות נק' בשם צדקה וכמ\"ש וצדקה תהי' לנו כי נשמור לעשות את כל מצות ה'<sup data-n=\"4644\">48</sup> כו', היינו כי ע\"י קיום המצות נעשה בחי' עליות נהי\"מ שיתפרדו מהסט\"א ואזי יעלו למעלה, ועי\"ז גורם עליות כל העולמות למעלה מעלה כמבואר מענין עליות דשבת שהתחלה עליות נהי\"מ דעשיי' וזה גורם גם עליות כח\"ב דאצי' למעלה כו' כמבואר בד\"ה את שבתותי תשמרו<sup data-n=\"4645\">49</sup>, הרי שהרגל מגביה את הראש א\"כ הראש מקבל מהרגל, וכ\"ז ע\"י והארץ הדום רגלי שהוא מעשה המצות ותשבע\"פ הנקראי' ארץ<sup data-n=\"4646\">50</sup> שהם בחי' הדום להגביה הרגל ע\"ד אם תשיב משבת רגליך כו' ועי\"ז וקראת לשבת ענג כו' המשכת וגילוי ענג העליון.\n<b>קיצור</b><sup data-n=\"4647\">51</sup>. ענין והארץ מצות הדום להגביה כנ\"י הנק' רגל שלא יהי' רגליה יורדות, ותחלה יבאר ענין הרגל שיש בכחה להוליך את הראש או לרפאו כו'<sup data-n=\"4648\">52</sup> כי",[["4637","41","<b>אל יצא איש ממקומו</b>: בשלח טז, כט."],["4638","42","<b>אאלפך חכ' ובינה</b>: איוב לג, לג. שבת קד, א."],["4639","43","<b>דרך</b>: במאמרי אדה\"ז תקס\"ה שם: בדרך."],["4640","44","<b>לא תלבש שעטנז</b>: תצא כב, יא."],["4641","45","<b>ולא תחללו</b>: אמור כב, לב. ראה מאמר ד\"ה זה במאמרי אדה\"ז תקס\"ב ח\"ב ע' שפו ואילך. תקס\"ה ח\"ב ע' תרעה ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550219\" data-slug=\"torat-chaim\" data-id=\"2300550219\">תו\"ח תצוה ח\"ב שנז, ב</a>. וש\"נ."],["4642","46","<b>וצדקה תרומם גוי</b>: משלי יד, לד [ושם: צדקה — אבל כ\"ה גם לעיל בהמשך כי תשא פט\"ו ובהערה 378]. ראה לעיל מאמר ד\"ה בנים אתם על יד הערה 71 ואילך. וש\"נ."],["4643","47","<b>בלק\"ת מהאריז\"ל בישעי' שם</b>: נד, יד עה\"פ בצדקה תכונני."],["4644","48","<b>מצות ה'</b>: ואתחנן ו, כה [ושם: המצוה הזאת לפני ה'. ראה לעיל על יד הערה 16]."],["4645","49","<b>בד\"ה את שבתותי תשמרו</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380263\" data-slug=\"likkutei-torah\" data-id=\"4001380263\">לקו\"ת בהר מג, ד</a>."],["4646","50","<b>ותשבע\"פ הנקראי' ארץ</b>: ראה לעיל המשך חייב אדם לברך פכ\"ד ובהערה 884."],["4647","51","<b>קיצור</b>: נדפס גם לעיל במאמר ד\"ה מה יפו כנ\"ל בהערה 37, וחלקו הראשון לשייך לד\"ה הנ\"ל."],["4648","52","<b>כו'</b>: תיבה זו ליתא שם."]]],[2000450431,"נעוץ סופן בתחלתן<sup data-n=\"4649\">53</sup>, ויש בע\"ס ב' בחי' מה שיש להם חיות קצוב, ותוספת וריבוי האור והוא הנק' הילוך וזה נמשך ע\"י אתעדל\"ת מהבירורי' וזהו ענין ההילוך ע\"י הרגל, והרפואה לחולת אהבה, בא\"י אמ\"ה, והתהלכתי<sup data-n=\"4650\">54</sup>, אני אענה את השמים<sup data-n=\"4651\">55</sup> והם יענו את הארץ, ענין שלש רגלים, בנהר יעברו ברגל<sup data-n=\"4652\">56</sup>, אך לפי שרגלי' יורדות מחמת חטא עה\"ד שנתערב הקליפה בקדושה סד\"ה ראה ריח בני, צ\"ל הדום רגלי וזהו אם תשיב משבת רגליך, שיתפרדו נהי\"מ מהקליפות, ומרומז בתיבת צדקה מקוף רגל ארוך מה שרגליה יורדות נעשה הא.\n<b>ועפ\"ז</b> אפשר לומר בענין המרגלים שהוא ג\"כ מלשון רגל<sup data-n=\"4653\">57</sup> היינו מה שירדו ונשלחו לברר ארץ כנען שהיתה בחי' רגליה יורדות, והם היו מבחי' דכורא<sup data-n=\"4654\">58</sup> ע\"כ נשלחו לתקן בחי' רגליה יורדות כו' שיהי' ע\"ד ויעל אברם ממצרים<sup data-n=\"4655\">59</sup> כו', עיין בת\"א ר\"פ יתרו בד\"ה בחדש השלישי, ועיין בהרמ\"ז פ' שלח פי' ג\"כ ענין המרגלים ע\"ד הנ\"ל, ורגל פירושו חפוש דהיינו העצה שיפשפש במעשיו<sup data-n=\"4656\">60</sup> ע\"ד ושם דרך<sup data-n=\"4657\">61</sup> כל השם אורחותיו<sup data-n=\"4658\">62</sup> כו' וכענין יהושע וכלב, וכן בכל אדם בעת עסקיו בעניני עוה\"ז ובפרט בבעל עסק הרי מתפשט ע\"כ הרגל למטה בק\"נ, אלא שכאשר מקיים בכל דרכיך דעהו<sup data-n=\"4659\">63</sup> שלא להתדבק ממש בהם רק ע\"ד בא אחיך במרמה<sup data-n=\"4660\">64</sup>, שמה שהוא בחי' אחיך של היצה\"ר באכילה ושתי' אין זה רק בבחי' כדי לברר וכמו שאומרים ואספת דגנך<sup data-n=\"4661\">65</sup> בק\"ש דוקא עי\"ז אח\"כ נעשו מה יפו פעמיך בנעלים ועמ\"ש ע\"פ ואנכי תרגלתי לאפרים<sup data-n=\"4662\">66</sup> בלק\"ת ס\"פ פנחס<sup data-n=\"4663\">67</sup> שנמשך בחי' אנכי בבחי' רגל היינו במצות מעשיות שיהי'<sup data-n=\"4664\">68</sup> עי\"ז בחי' הדום רגלי כנ\"ל ועי\"ז קחם על זרועותיו ע\"ד וצדקה תרומם גוי כנ\"ל.\n<span data-k=\"ks\"><b>קיצור.</b> ענין המרגלים הי' לתקן בחי' רגליה יורדות ולעשות הדום לבחי' רגל, ע\"ד ושם דרך, ואנכי תרגלתי לאפרים, עכ\"ה<sup data-n=\"4665\">69</sup>]. </span>\n<b>אך</b><sup data-n=\"4666\">70</sup> הנה עדיין י\"ל בענין הנ\"ל ברגל משום דנעוץ תחלתן בסופן כו', לכך נעשה ע\"י אתעדל\"ת אתעדל\"ע<sup data-n=\"4667\">71</sup> כו' דמ\"מ היא גופה צריכה טעם למה הענין כך",[["4649","53","<b>נעוץ סופן בתחלתן</b>: ראה ס\"י פ\"א, מ\"ז."],["4650","54","<b>והתהלכתי</b>: בחוקותי כו, יב."],["4651","55","<b>אני אענה את השמים</b>: נסמן לעיל המשך חייב אדם לברך ספל\"ב הערה 1295."],["4652","56","<b>בנהר יעברו ברגל</b>: תהלים סו, ו."],["4653","57","<b>המרגלים. . מלשון רגל</b>: ראה גם לעיל מאמר ד\"ה ומקנה רב ובהערה 59."],["4654","58","<b>המרגלים. . מבחי' דכורא</b>: ראה רמ\"ז לזהר שלח קנח, א."],["4655","59","<b>ויעל אברם ממצרים</b>: לך יג, א."],["4656","60","<b>שיפשפש במעשיו</b>: ברכות ה, א. עירובין יג, ב."],["4657","61","<b>ושם דרך</b>: תהלים נ, כג. ראה הגהות הב\"ח סוטה ה, ב אות א."],["4658","62","<b>כל השם אורחותיו</b>: מוע\"ק ה, סע\"א. ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה ישמח משה הערה 24."],["4659","63","<b>בכל דרכיך דעהו</b>: משלי ג, ו."],["4660","64","<b>בא אחיך במרמה</b>: תולדות כז, לה."],["4661","65","<b>ואספת דגנך</b>: עקב יא, יב."],["4662","66","<b>ואנכי תרגלתי לאפרים</b>: הושע יא, ג."],["4663","67","<b>בלק\"ת ס\"פ פנחס</b>: פ, ב ואילך."],["4664","68","<b>שיהי'</b>: בסד\"ה מה יפו הנ\"ל: שיהיו."],["4665","69","<b>עכ\"ה</b>: ההג\"ה מתחלת לעיל בתיבת: [ומזה — אחר ציון 45 בפנים."],["4666","70","<b>אך</b>: מכאן מתחיל לשון מאמרי אדה\"ז תקס\"ה ח\"ב כאן ע' תשסב."],["4667","71","<b>אתעדל\"ת אתעדל\"ע</b>: ראה זהר לך פח, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540430\" data-slug=\"torat-chaim\" data-id=\"2300540430\">תו\"ח שמות ח\"א מא, א</a> ובהערה 189."]]],[2000450432,"דהראש יצטרך להרגל<sup data-n=\"4668\">72</sup> והגם שאנו רואי' בחוש שכך הוא מ\"מ י\"ל שרש הענין על מה ולמה היתה תחילת הבריאה באופן זה ולא באופן אחר כו'. ויובן זה בהקדים ענין א' והוא בענין התהו ותיקון דהנה ידוע שבעולם התהו היו האורות בלתי כלולי' זב\"ז אלא היו הז' נקודות זה תחת זה וז\"ש וימלוך תחתיו<sup data-n=\"4669\">73</sup> כמ\"ש בע\"ח כו'. וביאור הדברים ידוע דהיינו מפני שהי' ההשתלשלו' בדרך עו\"ע<sup data-n=\"4670\">74</sup> ואע\"פ שהעלול צריך לעילתו אבל העילה א\"צ לעלול הימנו כלל וע\"כ נק' זת\"ז שהרי אין העליון כלול מן התחתון כלל כמו כאשר נמשך אור החכ' מאור הכתר אע\"פ שהחכ' מקבלת שפעה מאור הכתר בתמידות אבל אור הכתר איננו מקבל כלל בשום פעם מאור החכ' העלול ממנו כו', ונמצא אין הכתר כלול מן החכמה כלל וגם החכ' אינה כלולה מן הכתר רק במה שמקבלת ממנו שפעה, אבל היא נפרדת לדבר מהות בפ\"ע אחרי קבלתה, וזהו פי'<sup data-n=\"4671\">75</sup> זת\"ז * [והיו ענפין מתפרדין<sup data-n=\"4672\">76</sup> ומחמת זה הי' שבה\"כ, ובעולם התיקון נעשו בחי' פרצופי' היינו עד\"מ ציור אדם שהראש מצטרך להרגל ומקבל ממנו ועמ\"ש מענין תהו ותיקון בפ' שמות<sup data-n=\"4673\">77</sup> בד\"ה מי שם פה לאדם, ומ\"ש במ\"א בביאור ע\"פ לרוקע<sup data-n=\"4674\">78</sup> הארץ על המים, ובביאור ע\"פ והניף הכהן אותם על לחם הבכורים בלק\"ת פ' אמור<sup data-n=\"4675\">79</sup>, ומ\"ש ע\"פ מבלי אשר לא ימצא האדם<sup data-n=\"4676\">80</sup> את המעשה אשר עשה אלקי'<sup data-n=\"4677\">81</sup> מראש עד סוף]. והנה השבירה הי' בבחי' הכלים דתהו דוקא ולא באורות<sup data-n=\"4678\">82</sup> כידוע דז' נקודות דתהו נסתלקו והכלים שלהם נשברו ונפלו למטה בעולם הבריאה כו' [ועמ\"ש מזה",[["4668","72","<b>דהראש יצטרך להרגל</b>: במאמרי אדה\"ז תקס\"ה כאן: דהרגל יברר את הראש כו' ולמה יש להם התכללות זאת."],["4669","73","<b>וז\"ש וימלוך תחתיו</b>: וישלח לו, לג (תיבות אלו לא הובאו במאמרי אדה\"ז תקס\"ה כאן). ראה מאמרי אדה\"א דברים ח\"ד ע' א'תפב. וש\"נ."],["4670","74","<b>עו\"ע</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381108\" data-slug=\"likkutei-torah\" data-id=\"4001381108\">לקו\"ת ברכה צה, ב</a>: הנזכר בספרים. שה\"ש א, ב: כמ\"ש בספרים. ראה גם רמב\"ם הל' יסוה\"ת פ\"ב, ה\"ו."],["4671","75","<b>פי' זת\"ז</b>: במאמרי אדה\"ז תקס\"ה כאן ע' תשסג ניתוסף: וכמבואר בפרד\"ס וד\"ל."],["4672","76","<b>ענפין מתפרדין</b>: זהר ח\"ש קכג, א."],["4673","77","<b>בפ' שמות</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370232\" data-slug=\"torah-or\" data-id=\"3901370232\">תו\"א נא, ד</a> ואילך. בבוך 1162: בת\"א פ' שמות [וכ\"ה באוה\"ת בראשית כאן ע' 950], ותיקן כ\"ק אדמו\"ר מהר\"ש כבפנים [וכ\"ה בלקו\"ת לג\"פ כאן יד, ד]."],["4674","78","<b>ומ\"ש במ\"א בביאור ע\"פ לרוקע</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' רב ואילך (ובהנסמן במ\"מ לריש המאמר בח\"ב שם). תיבת: במ\"א ניתוסף בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש."],["4675","79","<b>בלק\"ת פ' אמור</b>: לז ג ואילך."],["4676","80","<b>ע\"פ מבלי אשר לא ימצא האדם</b>: קהלת ג, יא."],["4677","81","<b>אלקי'</b>: בקהלת שם: האלקים."],["4678","82","<b>השבירה. . הכלים. . באורות</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"א. (בנוסף להערה 1) מאמרי אדה\"א דברים ח\"ד ע' א'תפ. וש\"נ. בהערה הבאה."]]],[2000450433,"בלק\"ת בביאור ע\"פ ראשי המטות<sup data-n=\"4679\">83</sup>] ולכך נק' בשם שבירת הכלים דוקא וידוע דבחי' הכלים דתהו הי' סיבת שבירתן מפני ריבוי האור ומיעוט הכלים<sup data-n=\"4680\">84</sup> וזה הי' כל עיקר ענין התיקון להיות ריבוי הכלים ומיעוט האור דהיינו שיהי' הכלים רחבים ביותר מכפי ערך האור שבהן<sup data-n=\"4681\">85</sup> [ועמ\"ש מזה בביאור ע\"פ החלצו מאתכם<sup data-n=\"4682\">86</sup>, והנה הכלים דתיקון נתתקנו ממה שנתברר משבה\"כ דתהו] דהנה ז' הבלים<sup data-n=\"4683\">87</sup> דתהו שנשברו ונפלו ואח\"כ התיקון מה שהי' יכול להתברר וליכלל באצי' נכלל באצי'<sup data-n=\"4684\">88</sup> ומה שלא יוכל להתברר וליכלל שם באצי'<sup data-n=\"4685\">89</sup> נפל עוד למטה מן האצי' והוא בעולם הבריאה ועד\"ז מבריאה ליצי' ומיצי' לעשיי' כו' וכמ\"ש במ\"א [ועיין מזה בלק\"ת פ' פנחס בד\"ה הנה כתי' לעבדה ולשמרה ושם פ\"ב<sup data-n=\"4686\">90</sup> ובסידור בהדרוש ע\"פ צו את בנ\"י כו' את קרבני לחמי, ושם בהביאור<sup data-n=\"4687\">91</sup>], ונמצא שהסיבה העיקרית להריבוי של הכלים כ\"כ דהיינו שיהי' ריבוי ההשתל' כ\"כ באבי\"ע הוא ע\"י ענין הבירור דהיינו ע\"י מה שנדחה והוברר בחי' הפסולת בתחלה לפני האצי' ע\"כ יכול להיות אח\"כ ריבוי הרחבת כלים באצי' וכו' וכמו שאנו רואים למטה סיבת הרחבת כלים ואברים הוא ע\"י סיבת הבירורי' דמזונות האדם שנעשה דם והדם נהפך לחיות<sup data-n=\"4688\">92</sup> כו' וכמ\"ש במ\"א, והנה בירורי' הנ\"ל הן מלמעלמ\"ט דהיינו דרך ירידתן של הכלים דתהו ממדרג' למדרגה כנ\"ל אמנם אחר שכבר נפל בירידה אחר ירידה עד ע' שרים<sup data-n=\"4689\">93</sup> כו' יש עוד בחי' בירורי' והוא ע\"י העלאות רפ\"ח ניצוצות<sup data-n=\"4690\">94</sup> כו' מלמטה למעלה ומתחלה נברר בעשיי' ומעשי' נברר עוד ועולה ליצי' כו' ועד\"ז עד רום המעלות כידוע ומבואר במ\"א [בביאור ע\"פ מי יתנך<sup data-n=\"4691\">95</sup> כאח לי] ולהיות כן גם יהי' סיבת תוס' וריבוי האור למעלה ע\"י הבירורי' שמלמטלמ\"ע מאחר שע\"י הבירורי' שמלמעלה למטה נעשה הרחבת כלים הנ\"ל לפי ששרש הדברים שמתעלים מלמטלמ\"ע הרי הן בשרשן בחי' ז' הכלים דתהו שנפלו כנ\"ל והוא למעלה במדרגה מבחי' התיקון כי הגם שמ\"ה מברר ב\"ן כו',",[["4679","83","<b>בלק\"ת בביאור ע\"פ ראשי המטות</b>: מטות פב, ג."],["4680","84","<b>דתהו. . ריבוי האור ומיעוט הכלים</b>: ראה ע\"ח שער הכללים פ\"א. שער שביה\"כ ש\"ט, פ\"ו. (בנוסף להערה 1) מאמרי אדה\"ז תקס\"ג ח\"ב ע' תקמב (בשם המגיד הובא ב)<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830254\" data-slug=\"or-hatorah-hb\" data-id=\"8158830254\">אוה\"ת נשא ע' רנד</a>. מאמרי אדה\"א דברים ח\"ד ע' תעו ואילך. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540118\" data-slug=\"torat-chaim\" data-id=\"2300540118\">תו\"ח בשלח ח\"א רמה, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550434\" data-slug=\"torat-chaim\" data-id=\"2300550434\">ויקהל ח\"ב שצ, א</a>. לקו\"ת שבהערה 86."],["4681","85","<b>שבהן</b>: במאמרי אדה\"ז תקס\"ה כאן ישנו קטע נוסף שלא הועתק כאן."],["4682","86","<b>בביאור ע\"פ החלצו מאתכם</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380670\" data-slug=\"likkutei-torah\" data-id=\"4001380670\">לקו\"ת מטות פז, א</a> ואילך."],["4683","87","<b>הבלים</b>: במאמרי אדה\"ז תקס\"ה כאן־ ובבוך 1162 (שממנה העתיק הר\"ש סופר): הכלים. בלקו\"ת לג\"פ כאן: הבלים [הכלים]. ומחק הר\"ש סופר תיבת הבלים, וכן מחק הב' חצאי ריבוע."],["4684","88","<b>ואח\"כ. . באצי'</b>: במאמרי אדה\"ז תקס\"ה כאן: ירדו ממדרגה למדרגה מה שלפני האצי' ירד ונפל באצי' ומה שהוברר באצי' הוברר."],["4685","89","<b>וליכלל שם באצי'</b>: שם: שם."],["4686","90","<b>בלק\"ת פ' פנחס. . פ\"ב</b>: עו, ד."],["4687","91","<b>ובסידור. . בהביאור</b>: שחרית לה, ב ואילך."],["4688","92","<b>דמזונות האדם שנעשה דם והדם נהפך לחיות</b>: ראה גם מאמרי אדה\"ז תקס\"ד ע' קלד. ע' קמג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381184\" data-slug=\"likkutei-torah\" data-id=\"4001381184\">לקו\"ת שה\"ש יג, ד</a>."],["4689","93","<b>ע' שרים</b>: ראה זהר בראשית מו, סע\"ב. שע\"ת עד, א הערה 2."],["4690","94","<b>רפ\"ח ניצוצות</b>: ראה ע\"ח שער רפ\"ח שי\"ח, פ\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151537\" data-slug=\"likkutei-sichot\" data-id=\"1300151537\">לקו\"ש וישב כרך טו ע' 524</a> (אג\"ק שלו ח\"ב ע' כא). וש\"נ. מאמרי אדה\"א דברים ח\"ד ע' א'קעד. וש\"נ."],["4691","95","<b>בביאור ע\"פ מי יתנך</b>: מאמרי אדה\"ז תקס\"ה ח\"א ע' תקא."]]],[2000450434,"אבל לאחר שנתברר הרי מסיבתו דוקא נעשה הרחבת הכלי כנ\"ל וירידת כל ההשתל' למטה כ\"כ אינו אלא מסיבת המתברר כנ\"ל והרי שרשו בבחי' ש' ס\"ג<sup data-n=\"4692\">96</sup> דתהו<sup data-n=\"4693\">97</sup> שלמעלה מש' מ\"ה<sup data-n=\"4694\">98</sup> כידוע ולכך בהעלותו למעלה יוכל לגרום תוס' וריבוי האור מפני שגבוה הוא יותר מאותו צמצום הראשון<sup data-n=\"4695\">99</sup> שנעשה ע\"פ בחי' ש' מ\"ה המברר ולהיותו בחי' הגורמת הרחבת הכלי וע\"כ נמצא באברים בחי' התכללות כמו שנכלל הראש ברגל עד שהרגל יחזיק הראש ויגרום בו תוס' אור כנ\"ל. וזהו מב' סיבות הנ\"ל. והוא אחת לפי ששרש חיות הרגל הי' למעלה מן ראש בתחלה לפי הנ\"ל אלא שירד ברגל ע\"פ הבירור שמלמעלמ\"ט כנ\"ל ע\"כ מקבל הראש מן הרגל אח\"כ בבירור שמלמטה למעלה והוא כמשל הרפואה שעושין לרגל<sup data-n=\"4696\">100</sup> כו'. ויובן דבר זה מבואר היטב ע\"פ הידוע במ\"ש כי לא על הלחם לבדו<sup data-n=\"4697\">101</sup> יחי' האדם כי על כל מוצא פי ה' יחי' האדם כו'<sup data-n=\"4698\">102</sup> דמבואר בכהאריז\"ל משום דמוצא פי ה' שבמאכל גבוה ממוצא פי ה' שבנפש האדם לכך יחי' את האדם הגם שהאדם יש לו ג\"כ מוצא פי ה' במאמר נעשה אדם<sup data-n=\"4699\">103</sup> כו'. והטעם הוא לפי שבחי' הצומח גבוה בכלים דתהו יותר משרש בחי' נפש המדברת וע\"כ ירד בירידות המדרגה יותר ולכך יחי' את האדם כו' [וכמ\"ש מזה ע\"פ וידבר משה אל ראשי המטות<sup data-n=\"4700\">104</sup>], וא\"כ לפי הענין הנ\"ל בסדר הבירורי' שמלמעלה למטה שנפל פסולת היותר אחרון בעוה\"ז השפל לפ\"ז ג\"כ מוכרח לומר ששרש העשיי' גבוה הי' יותר משרש היצי' לפני השבירה וע\"כ ירד יותר כו', ובדרך כלל כל העולמות בי\"ע הן אשר ירדו יותר מן האצי' שרשם לפני השבירה גבוה יותר וע\"כ הוא הסיבה שבחי' הבירורי' שמלמטה למעלה מבי\"ע גורמים תוס' וריבוי אור למעלה באורות דאצי' מאחר ששרש הנשמות ומלאכים גבוהים היו מן האצילות לפני השבירה כו' וע\"ד הנ\"ל במאכל הצומח שיחי' את האדם מטעם זה, ועפ\"ז יובן יותר ענין הנ\"ל בטעם ההתכללות דראש ברגל עד שיתחזק הראש מן הרגל דהיינו לפי שבחי' הבירורי' שמלמעלה למטה הנ\"ל היינו כענין טעם הנ\"ל המבואר בצומח שהוא למעלה באמת מהאדם כו' ואשר מזה יהי' הרחבת הכלים כנ\"ל, וגם בחי' ריבוי תוס' אור ע\"י הבירורים מלמטה למעלה כנ\"ל הוא ע\"פ המבואר למעלה בטעם שהצומח יחי' את האדם והכל ענין א' וסיבה א' לפי ששרש המתברר גבוה מן המברר כנ\"ל ע\"כ בעלותו יחי' ויוסיף אור למעלה כו' והרי המלאכי' ונשמות שעולין בהעלאת מ\"ן הן",[["4692","96","<b>ש' ס\"ג</b>: ראה זהר רע\"מ פינחס רמו, ב."],["4693","97","<b>ש' ס\"ג דתהו</b>: ראה ע\"ח שער דרושי הנקודות ש\"ח, פ\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670152\" data-slug=\"torat-chaim\" data-id=\"2300670152\">תו\"ח בראשית ט, א</a> ובהערה 2."],["4694","98","<b>ש' ס\"ג דתהו שלמעלה מש' מ\"ה</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. הנסמן במאמרי אדה\"א דברים ח\"א ע' ה הערה ד\"ה: שם."],["4695","99","<b>הראשון</b>: במאמרי אדה\"ז תקס\"ה כאן ע' תשסד: האור הראשון."],["4696","100","<b>כמשל הרפואה שעושין לרגל</b>: ראה גם לעיל מאמר ד\"ה ומקנה רב ובהערה 25."],["4697","101","<b>כי לא על הלחם לבדו</b>: עקב ח, ג. ראה לקו\"ת להאריז\"ל שם (ח, א. ג). פע\"ח שער יוהכ\"פ שכ\"ז, פ\"א. כש\"ט קה\"ת סקצ\"ד. (בנוסף להערה 1) מאמרי אדה\"א דברים ח\"ב ע' תקעה. וש\"נ. שה\"א טז, ב ובהערה 10. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540054\" data-slug=\"torat-chaim\" data-id=\"2300540054\">תו\"ח וארא ח\"א נה, ב</a> ואילך. וש\"נ."],["4698","102","<b>כו'</b>: כ\"ה גם במאמרי אדה\"ז תקס\"ה כאן."],["4699","103","<b>נעשה אדם</b>: בראשית א, כו."],["4700","104","<b>הצומח גבוה. . נפש המדברת. . ראשי המטות</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380647\" data-slug=\"likkutei-torah\" data-id=\"4001380647\">לקו\"ת מטות פא, ב</a>. ראה גם (בנוסף להערה 1) מאמרי אדה\"א ויקרא ח\"ב ע' תתפד. וש\"נ. במדבר ח\"ב ע' תעט. ח\"ה ע' א'תשד. דברים ח\"ב ע' תרסה. וש\"נ."]]],[2000450435,"נכללי' בז' הכלים עצמן כמו שהיו קודם השבירה כו'. ובכ\"ז יובן שרש הדברים דהארץ הדום רגלי הנ\"ל ולמה יהי' נעוץ תחלתן בסופן וסוב\"ת מתחלת הבריאה כו' ולמה ע\"י אתעדל\"ת נעשה אתעדל\"ע כו' כי זה בהכרח ע\"פ הנ\"ל בענין התהו והתיקון כו'.\n<b></b>[הג\"ה. קיצור. הטעם שהוסד כן שנעוץ סופן בתחלתן, היינו לפי שבחי' סופן שרשם בתהו למעלה יותר, כי בתהו הי' זת\"ז ע\"ד עילה ועלול ומריבוי האור נשברו הכלים והובררו תחלה מלמעלמ\"ט ומזה נתהוו ע\"ס דתיקון, ומה שנפל למטה מתברר עוד מלמטלמ\"ע ע\"י האדם, ע' באג\"ה סי' ך\"ו בד\"ה והמשכילים יזהירו<sup data-n=\"4701\">105</sup>, ומה שנפל למטה שרשו למעלה גבוה יותר וזהו שהרגל בבחי' א' גבוה מהראש ועמ\"ש בסידור אחר עלינו לשבח בד\"ה ביאור למ\"ש בסש\"ב פנ\"ב נ\"ג יעו\"ש ג\"כ מענין זה. ומכ\"ז יובן ג\"כ ענין כח המצות מעשיות שנק' הדום רגלי. ועוי\"ל כי זהו מפעולת כח הא\"ס שבפעולתו לא יהי' ראש וסוף ויהי' הסוף ראש בבחי' א' כיון שנבראו מכח אין סוף, שאין בו מעלה ומטה וראש וסוף ולכן ע\"י הארה זו הסוכ\"ע יש בבחי' סוף מה שאין בראש, ונמצא מצד ממכ\"ע שייך ראש וסוף, אבל מצד שמקבלי' חיות מאור הסוכ\"ע אין שייך ראש וסוף ועמ\"ש בביאור ע\"פ יביאו לבוש מלכות<sup data-n=\"4702\">106</sup> דבאמת שרש הכלי נמשך מבחי' סוכ\"ע דוקא והאור והנשמה נמשך מבחי' ממכ\"ע מהקו וחוט יעו\"ש כי הכלי הוא בחי' היש לגבי האור שהוא בלי מה והתהוות היש הוא מבחי' סוכ\"ע הכל יכול, וא\"כ מבחי' התיקון שעיקרו ענין הרחבת הכלים הוא נמשך מבחי' סוכ\"ע ולכן מצד זה בחי' הרגל שהוא ענין ריבוי הכלי יותר מבהראש ע\"כ יש בבחי' זו מעלה יתירה מצד שרשה בבחי' הסוכ\"ע כו', וזהו ענין מבלי אשר לא ימצא כו' עמ\"ש מזה בד\"ה והי' מספר בנ\"י<sup data-n=\"4703\">107</sup>, וא\"כ בבחי' זו התיקון גבוה מעצמו יותר מעיגולים דתהו שהיו בחי' נפש והיושר דתיקון הוא בחי' רוח<sup data-n=\"4704\">108</sup> שגבוה מהנפש, עכ\"ה<sup data-n=\"4705\">109</sup>\n ",[["4701","105","<b>באג\"ה. . יזהירו</b>: תניא קמד, סע\"ב ואילך."],["4702","106","<b>בביאור ע\"פ יביאו לבוש מלכות</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370416\" data-slug=\"torah-or\" data-id=\"3901370416\">תו\"א מג\"א צב, ג</a>."],["4703","107","<b>בד\"ה והי' מספר בנ\"י</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380334\" data-slug=\"likkutei-torah\" data-id=\"4001380334\">לקו\"ת במדבר ו, ג</a>."],["4704","108","<b>מעיגולים. . נפש. . והיושר רוח</b>: ראה ע\"ח דרוש עגו\"י ש\"א, ענף ב' וג'. מאמרי אדה\"א קונטרסים ע' תלב ואילך. בראשית ע' קעה. וש\"נ. הנחות תקע\"ז ע' קמג. וש\"נ. אוה\"ת בראשית כרך ז ס\"ע 2312 ואילך. סה\"מ תרכ\"ז ע' ד. תרל\"ג ח\"ב ע' שפד בשולי היריעה."],["4705","109","<b>עכ\"ה</b>: כנצ\"ל: עכ\"ה"]]],[2000460079,"<h3>והי' ברכה כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ לך לך, ט\"ל).</b>\n<b></b>בחי' חסד דאברהם כו' פי' מגן כו' תהו ותקון מעלתם זע\"ז כו' מגן דמצות מעשיות\nלך\n<b>והי'</b> ברכה<sup data-n=\"1\">1</sup>, וארז\"ל זהו שחותמי' מגן אברהם, כי כל פסוק זה פי' בגמ' פסחי' קי\"ז ב' על ברכה ראשונה דשמ\"ע שהיא ברכת אבות, ואמרו ואעשך לגוי גדול זהו שאומרי' אלקי אברהם, ואברכך כו' יצחק, ואגדלה כו' יעקב, יכול יהו חותמין בכולם ת\"ל והי' ברכה בך חותמי' ואין חותמי' בכולם. וצ\"ל הטעם מפני מה בך דוקא חותמי'. וגם צ\"ל ענין פי' מגן אברהם אם אברהם הוא המגין, או שבחי' אברהם צריכה לבחי' מגן, שלא יומשך בגילוי כ\"כ כ\"א ע\"פ צמצום המגן דוקא, וכענין מגן ונרתק השמש שהוא בכדי שיהיו יכולי' לקבל אור השמש. אך באמת שניהם אמת.\n<b>ותחלה</b> נפרש פי' השני שבחי' אברם צריך למגן, וכמ\"ש אנכי מגן לך כו'. והענין הוא שהגם שברוב הדרושי' נת' שבחי' אברהם הוא בחי' חסד עולם<sup data-n=\"2\">2</sup>, והוא בחי' חסד דמ\"ה דז\"א, שמצד היותו שפל בעיני עצמו כאמרו ואנכי עפר ואפר כו', לכן הי' חושב זולתו לטוב ממנו, שעי\"ז הי' משפיע לכל כל טוב, וכמ\"ש בא\"צ שער י\"ז הוא שער הנדיבות<sup data-n=\"3\">3</sup> שאברם הי' נדיב בין בנפשו בין בגופו בין בממונו כו'. ואמנם כ\"ז הי' מצד הביטול שהי' אבר מ\"ה כלי לבחי' הביטול דמ\"ה דז\"א בחי' חסד עולם. משא\"כ רב חסד הוא בחי' השפעה מצד הגדולה, וכמשנ\"ת מזה באורך בד\"ה כי ידעתיו (בס' חורף תרט\"ז)<sup data-n=\"4\">4</sup> ובמ\"א בד\"ה יביאו לבוש מל' (שלא נדפס)<sup data-n=\"5\">5</sup> ובכ\"ד וכנ\"ל.",[["1","1","<b>והי' ברכה</b>: מאמר זה מיוסד על ד\"ה אנכי מגן, ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490047\" data-slug=\"or-hatorah-hb\" data-id=\"8316490047\">אוה\"ת לך לך (כרך ד') תרצג, א</a> ואילך. [מאמר האוה\"ת הוא הגהות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370052\" data-slug=\"torah-or\" data-id=\"3901370052\">תו\"א לך לך יב, א</a>]. ובהערת כ\"ק אדמו\"ר זי\"ע (נדפס לעיל ע' 5) מציין על מאמר זה: מבאר עניני דרוש אנכי מגן לך (שבתו\"א ולקו\"ת לג\"פ). להלן בהוספות נדפס ג\"כ הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע ממאמר זה."],["2","2","<b>שברוב הדרושים נת' שבחי' אברהם הוא חסד עולם</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370308\" data-slug=\"torah-or\" data-id=\"3901370308\">תו\"א יתרו סט, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370366\" data-slug=\"torah-or\" data-id=\"3901370366\">תצוה פב, סע\"א</a> ואילך. מאמרי אדהאמ\"צ שמות ח\"ב ס\"ע שלח ואילך [ובהנסמן שם בתחילת המאמר]. סה\"מ תרכ\"ז ע' קצט. ובכ\"מ."],["3","3","<b>בא\"צ </b>[ באורחות צדיקים]<b> שער י\"ז הוא שער הנדיבות</b>: ראה גם אוה\"ת וירא צ, ב. תזריע (כרך ב') ע' תקכא. סה\"מ תרכ\"ז שם. תרל\"ב ח\"א ע' ז. קפב. תרפ\"ט ע' 90 ואילך. תרח\"צ ע' קכט ואילך."],["4","4","<b>בד\"ה כי ידעתיו (בס' חורף תרט\"ז)</b>: נדפס באוה\"ת וירא צ, סע\"א ואילך."],["5","5","<b>בד\"ה יביאו לבוש מל' (שלא נדפס)</b>: נמצא בכת\"י 1029 (טז, א ואילך). ובשינויים בסה\"מ תרכ\"ז ע' קצז ואילך. וש\"נ."]]],[2000460080,"<b>ואמנם</b> עפמשנ\"ת בהג\"ה על ד\"ה מים רבים שבפ' נח<sup data-n=\"6\">6</sup>, גבי וחסדי מאתך לא ימוש שהוא בחי' חסד עליון ואהבה רבה הבאה מלמעלה להיות וימינו תחבקני, ופי' שם שהוא בחי' כי חפץ חסד הוא, ונז' שם המשל לבחי' זו מאברהם אע\"ה שהי' מצטער כשלא הי' לו אורחי' כו' ע\"ש, הרי משם מבואר שבחי' אברהם שרשו מבחי' כי חפץ חסד הוא, שהוא חסד דלגאו הנז' באד\"ר דקל\"ג ב', וכ\"מ ממ\"ש בזהר ר\"פ פקודי דר\"ך ע\"ב ע\"פ מה רב טובך אשר צפנת ליראיך כו' שבחי' נהורא קדמאה דגניז קוב\"ה זהו בחי' אברהם, ונהורא קדמאה זהו בחי' הנ\"ל, כדמשמע בזח\"ג פ' בלק דר\"ד ע\"ב, ע' מק\"מ שם. ומ\"מ לא קשיא מידי ממש\"נ ברוב הדרושי' שחסד דאברהם זהו בחי' חסד עולם, כי ודאי יש בחי' אברהם באצי' שהוא מרכבה למדת החסד דאצי', וכמ\"ש בפרד\"ס בשם ספר הבהיר אמרה מדת החסד כל ימי היות אברם בארץ כו' כמ\"ש מזה בכ\"ד, להיותו עומד כו' שהחליף מקום עבודת מדת החסד כמשנ\"ת בד\"ה ואעשך לגוי גדול (ו\"ל)<sup data-n=\"7\">7</sup>, ובחי' אברם זה ז\"ע בחי' חסד עולם. אבל מ\"מ יש בחי' אברם גם למעלה מאצי' כנודע מענין בעבר הנהר ישבו אבותיכם<sup data-n=\"8\">8</sup> כו', א\"כ שפיר י\"ל גם בחי' כי חפץ חסד כו'.\n<b>ועפ\"ז</b> יתפרש ענין בחי' הנדיבות דאברם כפשוטו, שלהיות שרשו מבחי' חסד דלגאו כו' לכן השפיע למטה רב טוב בלי שום דקדוק כלל, ולא מצד היותו מ\"ה כנ\"ל אלא מצד עצם רב טובו וחסדו האמיתי כו', עד שמחמת מדת חסדו בקש לו ישמעאל יחי' לפניך שעם היותו מכירו כו'<sup data-n=\"9\">9</sup> עכ\"ז מצד עצם מדת חסדו שבלי דקדוק כלל בקש עבור ישמעאל, ולא עוד שבקש שיהי' לפניך כמשנ\"ת בהג\"ה לד\"ה השמי' כסאי<sup data-n=\"10\">10</sup> ע\"ש.\n<b>והנה</b> ארז\"ל בתחילה עלה במח' לברוא את העולם במדת הדין, ראה שאין העולם מתקיים שיתף עמו מדת הרחמים, ולכאו' יפלא הלא הוא ית' הוא טוב ומטיב לכל וחפץ חסד הוא כו', א\"כ מדוע עלה במח' לברוא כו' במדת הדין, הלא לכאו' זהו היפך מדת חסדו שחפץ חסד הוא. אך הענין הוא דכתי' אשר ברא אלקים לעשות, לתקן, וכמארז\"ל אפי' תורמסין צריכין תיקון כו', והתיקון הוא לברר עולם העשי' וניצוצי התהו שנפלו בשבירת הכלים כנודע, ולכן עלה במח' לברוא כו'",[["6","6","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560292\" data-slug=\"or-hatorah-hb\" data-id=\"8316560292\">בהג\"ה על ד</a>\"ה מים רבים שבפ' נח</b>: אוה\"ת נח (כרך ג') תריב, ב ואילך."],["7","7","<b>כמשנ\"ת בד\"ה ואעשך לגוי גדול (ו\"ל)</b>: ד\"ה ואעשך לגוי גדול — תרל\"ו, נדפס בסה\"מ תרל\"ה ח\"ב ע' תסה ואילך."],["8","8","<b>כנודע מענין בעבר הנהר ישבו אבותיכם</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370117\" data-slug=\"torah-or\" data-id=\"3901370117\">תו\"א וישלח כה, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380278\" data-slug=\"likkutei-torah\" data-id=\"4001380278\">לקו\"ת בחוקותי מז, א</a>. מאמרי אדה\"ז תקס\"ד ע' קטז ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200225\" data-slug=\"or-hatorah-hb\" data-id=\"8159200225\">אוה\"ת בחוקותי (כרך ג) ע' תתקמא</a>-ב. וראה גם סה\"מ תרנ\"ז ע' ס ואילך. ובכ\"מ."],["9","9","<b>לו ישמעאל יחי' לפניך שעם היותו מכירו כו'</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370052\" data-slug=\"torah-or\" data-id=\"3901370052\">תו\"א לך לך יב, א</a> ושם: ואעפ\"י שהוא יודע מהו ישמעאל. וראה אוה\"ת חיי\"ש קכא, א (תמה, רע\"א): שאילולי היה יודע שיצא לתרבות רעה כ\"כ לא היה רוצה כלל להחזיקו אלא היה סבור שיהיה גם הוא הגון וחשוב רק לא כיצחק. ובס' מאמרי אדה\"ז תקע\"א ע' קעה: ודבר זה נעלם מאברהם. וב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670332\" data-slug=\"torat-chaim\" data-id=\"2300670332\">תו\"ח חיי שרה קכו, סע\"א</a>: לא ידע אברהם ונעלם ממנו שישמעאל יצא לתרבות רעה."],["10","10","<b>בהג\"ה לד\"ה השמי' כסאי</b>: סה\"מ תרל\"ח ע' רפח-ט."]]],[2000460081,"במדת הדין, שאם הי' ע\"פ החסד הנ\"ל לבד לא הי' נמשך בחי' הבירור כלל, וכמארז\"ל במד\"ר חטאין סגיאין, לכן עלה במח' כו', רק מפני שראה שא\"א להיות קיום העולם שיתף מדת הרחמים כו'.\n<b>ועפ\"ז</b> יובן ג\"כ שבחי' חסד זה דאברם ששרשו מבחי' כי חפץ חסד חסד דלגאו כו', צריך לבחי' מגן דוקא, שאל\"כ מצד ריבוי בחי' חסדו הנ\"ל ה\"ז היפך מכוון בחי' התיקון הנ\"ל כמובן כו'. וז\"ע החתימה שחותמין מגן אברהם שבחי' אברהם צריך למגן. וע' מענין חותם בברוך בד\"ה להבין ענין הברכות בפ' בראשית<sup data-n=\"11\">11</sup>.\n<b>והנה</b> בפי' מגן פי' אדמו\"ר נ\"ע ז\"ל בד\"ה אנכי מגן לך<sup data-n=\"12\">12</sup> וז\"ל מגן נק' דבר המכסה, למשל במלחמה נק' מגן מה שמכסה בו<sup data-n=\"13\">13</sup> שלא ישלוט עליו הקשת, עכ\"ל, ועפ\"ז פירש הפסוק שמש ומגן כו' שהשמש אם לא הי' לו נרתק לא היו יכולים לסבול אורו הגדול, והנרתק הוא המגין שנוכל לסבול, רק לע\"ל הקב\"ה מוציא חמה מנרתיקה כו'.\n<b>אך</b> ברוב הדרושים<sup data-n=\"14\">14</sup> פי' דבחי' מגן ז\"ע הפרוכת, שהוא הפרסא שבין אצי' לבריאה כמ\"ש בכ\"ד, וע' בפ' תצוה בד\"ה ואתה תצוה<sup data-n=\"15\">15</sup> גבי וענין הפרוכת הוא כי הנה כתי' כי שמש ומגן כו', ועד\"ז נת' בפ' בראשית בד\"ה אעשה לו עזר כו' ובכ\"ד<sup data-n=\"16\">16</sup>. וכן פי' בעה\"מ דף מ\"ה ע\"ג שער ח' פ\"ד, וז\"ל החוט הזה של א\"ס כו' נתפשט החוט בתוך א\"ק ונעשה פרסא, פי' פרוכת שהוא מסך כו' בסוד פסוק שמש ומגן כו', כדי שלא יצא האור יותר מדאי ויהי' ח\"ו העולם חרב כמו שהי' בעולם התהו, והמסך הזה מעכב השפע שלא יצא חוצה יותר ממה שיכולים לסבול העולמות, וכן יש בין כל עולם ועולם מסך מבדיל בסוד והבדילה הפרוכת לכם עכ\"ל, וע\"ש שע\"ד פ\"ג ופ\"ט ושער ו' פך\"ב. ומדבריו מבואר שבעולם התהו לא היו פרסות כמו בעולם התיקון, וע\"כ זה הי' סיבה שנחרב עולם התהו כו', וכן האריך שם שער ז' פ\"ד. וע' בע\"ח שער א\"א בתחילתו, ובביאור האד\"ר בתחילתו גבי ופריס קמי' חד פרסא, שגם בעולם התהו הי' פרסא א', ואעפ\"כ לא אתקיימו כו' עד ולבתר זמנא הוא אסתלק והוה מסתכל בההוא פרסא ואתתקן כו', דהיינו הסתלקות האור, וגם שנעשה פרסא בין עולמות א\"ס ואצי'<sup data-n=\"17\">17</sup> אז נתקיימו, ע' בספר רוח דוד. עכ\"פ עיקר",[["11","11","<b>בד\"ה לה\"ע הברכות בפ' בראשית</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370024\" data-slug=\"torah-or\" data-id=\"3901370024\">תו\"א בראשית ו, ג</a> ואילך."],["12","12","<b>בד\"ה אנכי מגן לך</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370052\" data-slug=\"torah-or\" data-id=\"3901370052\">תו\"א לך לך יב, א</a> שם."],["13","13","<b>מגן נק' דבר המכסה. . מה שמכסה בו</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490049\" data-slug=\"or-hatorah-hb\" data-id=\"8316490049\">אוה\"ת לך לך (כרך ד) שם תרצד, א</a>: והנה לפי פי' זה המל' מצד עצמה נק' מגן שהטפה מז\"א נקלט בה כו' אך ברוב הדרושים כו'."],["14","14","<b>אך ברוב הדרושים</b>: ראה הערה הקודמת. ובהנחת כ\"ק אדמו\"ר מוהרש\"ב (לקמן): נמצא ההפרש בין ב' הפירושים, דלפירוש הא' המגן הוא כדי שלא יומשך לסט\"א. ולפירוש הב' המגן הוא כדי שיוכלו בי\"ע לקבל האור."],["15","15","<b>בפ' תצוה בד\"ה ואתה תצוה</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370365\" data-slug=\"torah-or\" data-id=\"3901370365\">תו\"א פא, ד</a>."],["16","16","<b>בפ' בראשית בד\"ה אעשה לו עזר כו' ובכ\"ד</b>: [ ובכמה דוכתי]. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370017\" data-slug=\"torah-or\" data-id=\"3901370017\">תו\"א ד, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380514\" data-slug=\"likkutei-torah\" data-id=\"4001380514\">לקו\"ת שלח נ, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380593\" data-slug=\"likkutei-torah\" data-id=\"4001380593\">בלק סח, ד</a>. ועוד. ועי' ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370514\" data-slug=\"torah-or\" data-id=\"3901370514\">תו\"א ויקהל קטו, ב</a>."],["17","17","<b>וגם שנעשה פרסא בין עולמות א\"ס ואצי'</b>: כ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490007\" data-slug=\"or-hatorah-hb\" data-id=\"8316490007\">אוה\"ת לך לך (כרך ד</a>) שם. ובהנחת כ\"ק אדמו\"ר מוהרש\"ב מעיר ע\"ז: בין אצי' ר\"ל דכתר ג\"כ בכלל אצי' יחשב, דבין כתר לאצי' לא יש פרסא כו', וא\"כ צ\"ל מה הם עולמות הא\"ס שכ', וצ\"ע."]]],[2000460082,"המסכים והפרסות הוא שנעשו בעולם התיקון, וכ\"מ בזח\"א נח דס\"ה ע\"א ובמק\"מ שם.\n<b>ועפ\"ז</b> יובן ענין אחד<sup data-n=\"18\">18</sup>, דהנה בעמה\"מ ריש שער ז' דף מ\"ב סע\"ג פי' דעולם התהו הוא בחי' נפש, ועולם התיקון הוא בחי' רוח, והעולם שיהי' כשיחדש הקב\"ה עולמו הוא בחי' נשמה, נמצא לפ\"ז עולם התיקון גבוה יותר בעצם מעולם התהו, כמעלת רוח על הנפש, (ע' בביאור שני דהשמי' כסאי קרוב לסופו<sup data-n=\"19\">19</sup>). גם בע\"ח מבואר דעגולים הוא בחי' נפש, ויושר הוא בחי' רוח, ומבואר בשער הנקודי' במה\"ב פ\"ז שעולם הנקודי' שבהם הי' שבה\"כ נאצלו רק בבחי' נפש, ולכן נשברו שלא יכלו לקבל האור כו', והתיקון הוא בחי' יושר בחי' רוח ע\"ש באריכות. וכן ביאר רבינו אדמו\"ר נ\"ע ז\"ל בפ' שמות בד\"ה מי שם פה לאדם<sup data-n=\"20\">20</sup>, ושלכן יש בתיקון מעלה יתירה מה שאינה בעולם התהו, והו\"ע נעוץ תחילתן בסופן (וצ\"ע אם כוונתו שכוונת נעיצת התחילה הוא בסוף דוקא יותר מבראש המתפשט כמשנ\"ת בד\"ה ועמדו רגליו<sup data-n=\"21\">21</sup>, או ענין ההתכללות לבד<sup data-n=\"22\">22</sup> שהראש מצטרך להרגל שז\"ע נעוץ תחילתן בסופן וסופן בתחילתן כו'), שזהו הנמצא דוקא בבחי' יושר שהוא פרצוף אדם כו', שאז יתכן לומר שיש בחי' ברגל מה שאינו אפי' בהראש, משא\"כ בעולם התהו שהיו בבחי' עגולים לא הי' בחי' זו. וא\"כ מכ\"ז משמע שהתיקון שרשו גבוה מהתהו, וכן הסברא נותן, כשסותר (בכוונה) על מנת לבנות (ע' בהג\"ה לד\"ה ראה אנכי נותן שבלק\"ת<sup data-n=\"23\">23</sup> בענין אזרח), ודאי הבנין עדיף כו'.\n<b>אך</b> א\"כ לכאו' זהו סתירה למ\"ש ברוב הדרושי' דעולם התהו הוא בחי' לפני מלך מלך כו' שהוא קדם במעלה לעולם התיקון, והיינו ששם הי' ריבוי האור, עד שזהו תכלית ירידת הנשמה להתלבש בגוף ונה\"ב לפי שנה\"ב שרשו מעולם התהו, ועי\"ז דוקא נעשה עליית נה\"א, וכמבואר בפ' נח בד\"ה מים רבים<sup data-n=\"24\">24</sup> ובכ\"ד, וע' בפ' וישלח בד\"ה וישלח יעקב, ובד\"ה ויקח מן הבא בידו מנחה<sup data-n=\"25\">25</sup>, ובפ' בשלח בד\"ה בשלח פרעה<sup data-n=\"26\">26</sup>, וזהו כוונת כל הדרושי' של אדמו\"ר נ\"ע ז\"ל.",[["18","18","<b>ועפ\"ז יובן ענין אחד</b>: בהבא לקמן ראה אוה\"ת לך לך שם תרצד, ד ואילך."],["19","19","<b>בביאור שני דהשמי' כסאי קרוב לסופו</b>: <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560019\" data-slug=\"or-hatorah-hb\" data-id=\"8316560019\">אוה\"ת בראשית (כרך ג) תעו, א</a>-ב. ובשינויים בסד\"ה בראשית ברא בסוף סה\"מ תרל\"ח (ע' שמח ואילך)."],["20","20","<b>בפ' שמות בד\"ה מי שם פה לאדם</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370232\" data-slug=\"torah-or\" data-id=\"3901370232\">תו\"א נא, ד</a> ואילך."],["21","21","<b>כמשנ\"ת בד\"ה ועמדו רגליו</b>: ראה סה\"מ תקע\"א ע' ס. סה\"מ תר\"ל ע' שכ."],["22","22","<b>וצ\"ע אם כוונתו שכוונת נעיצת התחילה הוא בסוף. . או ענין ההתכללות לבד</b>: בהנחת כ\"ק אדמו\"ר מוהרש\"ב מציין שבעת אמירת המאמר הכריע כ\"ק אדמו\"ר מהר\"ש שהראש צריך להרגל."],["23","23","<b>בהגה\"ה לד\"ה ראה אנכי שבלק\"ת</b>: <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450636\" data-slug=\"or-hatorah-hb\" data-id=\"8316450636\">אוה\"ת ראה ע' תרלו</a>."],["24","24","<b>בפ' נח בד\"ה מים רבים</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370039\" data-slug=\"torah-or\" data-id=\"3901370039\">תו\"א ט, ג</a> ואילך."],["25","25","<b>בד\"ה וישלח יעקב ובד\"ה ויקח מן הבא בידו מנחה</b>: תו\"א כד, א ואילך. כה, ג ואילך."],["26","26","<b>ובפ' בשלח בד\"ה בשלח פרעה</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370274\" data-slug=\"torah-or\" data-id=\"3901370274\">תו\"א סא, א</a> ואילך."]]],[2000460083,"<b>אך</b> כ\"ז יובן ע\"פ המבואר בפ' לך בד\"ה והבדילה הפרוכת<sup data-n=\"27\">27</sup> בענין החשמל המלביש לזו\"נ דאצי', שהו\"ע המסך שבין אצי' לבריאה, שאע\"פ שהוא חיצוני' אצלן עכ\"ז שרשו גבוה מהן, כי זו\"נ הם מדות דאצי' והחשמל שרשו מהבינה, וכענין משלי שלמה ששרש המשל נמשך משכל עליון מאד, שלכן שלמה דוקא הי' יכול לאמר משלים כו' ע\"ש באריכות, והנה עם היות שרשו גבוה יותר עכ\"ז הוא עצמו למטה מזו\"נ וגורם המעטת האור, עד שהאור שעובר ונמשך דרך המסך אינו ערוך כלל לגבי האור שלמעלה מהמסך ע\"ד כי שמש ומגן כו', וכנודע מענין אור של תולדה כו'. וכך עד\"ז ממש י\"ל בענין התהו והתיקון, כי בתהו לא הי' פרוכת ומסכי' כ\"כ, א\"כ בא האור בריבוי מאד, משא\"כ בתיקון שנעשו פרוכת ומסכים א\"כ בא האור במיעוט. וז\"ע המבואר בכל הדרושי' שעולם התהו הוא גבוה יותר מצד ריבוי האור שהי' שם משא\"כ בתיקון, וזהו שנא' גבי יעקב כי קטן הוא בחי' יו\"ד עקב שהאור נמשך ע\"י צמצומי' כו'. אך עכ\"ז הרי שרש עולם התיקון שהוא ענין המשכת הפרסות והמסכים והלבושי' דתיקון הרי הם נמשכים מבחי' שלמעלה גם מריבוי האור דעולם התהו, ע\"ד הנ\"ל בענין החשמ\"ל כו', וכך ז' מלכי' דתהו הם ז' מדות, והתיקון נמשך מבחי' גבוה יותר כו', וכנודע ג\"כ שמלך השמיני הדר (שרש עולם התיקון) הוא גבוה יותר מז' מלכין קדמאין, שהם ז\"ת דמל' דא\"ק, ומלך הדר הוא יסוד דא\"ק, וזהו עיקר התיקון כמ\"ש באד\"ר דקמ\"ב, אלא שמשם נמשך האור ע\"י פרסות ומסכי' ושאר התיקונים להמעיט גילוי האור.\n<b>ועפ\"ז</b> יובן בטוב טעם דברי המד\"ר תולדות פ' ס\"ג בענין מטרונא ששאלה את ר' יוסי בן חלפתא כו' שהשיב לה משל שאם תניחי שתי מרגליות בשפופרת א' לא זו שאתה נותנת ראשונה יוצאה אחרונה כו'. ולכאו' הלא נת' בפ' בשלח בד\"ה בשלח פרעה<sup data-n=\"28\">28</sup> בענין בנה הגדול לפי שעולם התהו קדם לעולם התיקון וכנ\"ל ממ\"ש בפ' וישלח וה\"ה הבכור והראשון, וא\"כ איך אומר ר' יוסי משל שבאמת הוא היפך זה. אך לפמשנ\"ת שניהם אמת, דמצד סדר ההשתלשלות עולם התהו קדם, וגם בו ריבוי האור יותר הרבה מבעולם התיקון, (וכמ\"ש מזה במ\"א בהג\"ה לד\"ה אם בחוקתי ובהביאור<sup data-n=\"29\">29</sup> שם משל ע\"ז מעולם התיקון מאור שנברא ביום ראשון כו' מסוף העולם ועד סופו, ונת' שם מהו מסוף דהל\"ל מראש כו' אלא שהכוונה על ב' עולמות עלמא דאתכסי' ועלמא דאתגלי', וכשמיעטו כו' ע\"ש שזהו שלא בערך כלל), אך כ\"ז הוא בסדר השתלשלות שדומה ללידה, אבל בשרשן עולם התיקון גבוה יותר שהוא מבחי' רוח כו', ועולם התהו הוא מבחי' נפש כנ\"ל. וקרוב ענין זה למשנ\"ת בעולם התיקון עצמו בענין שמי' וארץ, דבסדר ההשתלשלות שמי' קדמו, ובשרשן ארץ קדמה, וכמ\"ש מזה בפ' ויגש בד\"ה ויגש",[["27","27","<b>בפ' לך בד\"ה והבדילה הפרוכת</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370054\" data-slug=\"torah-or\" data-id=\"3901370054\">תו\"א יב, ג</a> ואילך."],["28","28","<b>נת' בפ' בשלח בד\"ה בשלח פרעה</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370275\" data-slug=\"torah-or\" data-id=\"3901370275\">תו\"א שם סא, ב</a>."],["29","29","<b>בהג\"ה לד\"ה אם בחוקתי ובהביאור</b>: סה\"מ תרכ\"ו ע' צו. תר\"ל ס\"ע קמא-ב. והביאור ע\"ז שם ע' קנ."]]],[2000460084,"אליו יהודה<sup data-n=\"30\">30</sup>, ונת' במ\"א בד\"ה השמי' כסאי<sup data-n=\"31\">31</sup> בענין הפרסא ששרשה גבוה מאד היינו מבחי' כתר.\n<b>וזהו</b> אנכי מגן<sup data-n=\"32\">32</sup> שבחי' המגן והפרסא (להגן על אור בחי' אברהם דלעילא שבבחי' כי חפץ חסד הוא), שרשה מבחי' אנכי כו' (והיינו בחי' אנכי מי שאנכי. ובעבודה בנפש האדם) למטה פי' אנכי מגן היינו מצות מעשיות, שהם מבחי' אשר אנכי מצוך, (שלהיותם מפנימיות רצונו ית' א\"א לבוא למטה כ\"א בהתלבשות דברי' גשמי' דוקא, ובזה גדלה מעלתם גם על בחי' ההתבוננות דק\"ש<sup data-n=\"33\">33</sup> מה שמתבונן איך שה' אלקינו וה' אחד, ושע\"י אריכות ההתבוננות בא יבא גם לבחי' אהבה דבכל מאדך לדבקה בו כו', עכ\"ז איך יגיע לזה זהו ע\"י מעשה המצות גשמי' דוקא שהם מפנימי' רצונו ית' כנ\"ל ונעוץ סופן בתחלתן שהם מבחי' אשר אנכי מי שאנכי מצוך (ל' צוותא שעי\"ז נעשה כנס\"י אחות לנו קטנה ל' אחות שמתאחדת בתכלית עם מהותו ועצמותו ית' כבי') ולא מה שנמשך מבחי' אור וזיו לבד שזה יכול לבוא בהשגה בג\"ע כו' וכן ע\"י העמקת הדעת בבחי' ההתבוננות בק\"ש. אלא שמצות ק\"ש עצמה בדבור וכן ת\"ת בדבור הם ג\"כ כמו כל המצות שנתלבשו בדברי גשמיי', דעקימת שפתיו הוי מעשה כנודע מדרז\"ל. וזהו והיו הדברי' האלה שבד\"ת הכתוב מדבר, אשר מצות לימוד התורה שכנגד כולם שזהו מבחי' אשר אנכי מהו\"ע מצוך היום לעשותם דוקא בהתלבשות הנשמה בגוף דוקא, שאז ביכולתה לקיים ושננתם כו' ודברת בעקימת שפתיו, וקשרתם כו' וכתבתם מצות מעשיות, ולא בהיות הנשמה למעלה קודם התלבשותה בגוף שאז הי' באהוי\"ר דג\"ע שזהו רק זיו והארה כו', משא\"כ בהתלבשותה בגוף היום ה\"ה מקיימת מצות מעשיו' שנמשכי' מבחי' אנכי כו') שהם הם המגן שבהם וע\"י נמשך ומתלבש בחי' כי חפץ חסד הוא.\n<b>ועוי\"ל</b> להבין בעומק יותר ענין בחי' המגן ומכסה דמצות מעשיות, ע\"פ מארז\"ל ולא עם הארץ חסיד<sup data-n=\"34\">34</sup>, שבפי' תיבת חסיד יש ב' פי', והא' הוא חסיד מלשון חסד וקאי על אור האהבה דפרשה ראשונה שבק\"ש, שעם היות שואהבת הוא בגימ' ב\"פ אור, מ\"מ בלתי גניזת האור שהיא כלי המצות א\"א להתקיים האור, וע' בפ' מקץ בד\"ה ויהי מקץ דרוש הראשון קרוב לסופו<sup data-n=\"35\">35</sup>, כי כל אור אינו מאיר ונמשך כ\"א כשיש כלי במה שיתאחז דוקא, ולכן להיות בחי' אורות האהבה מתגלי' בנפש הוא דוקא ע\"י",[["30","30","<b>בפ' ויגש בד\"ה ויגש אליו יהודה</b>: תו\"א מג, ג ואילך. [ועי' בציונים ומ\"מ בסוף הספר שם]. וראה גם ד\"ה ויגש בסה\"מ תרכ\"ט ע' כב ואילך."],["31","31","<b>במ\"א בד\"ה השמי' כסאי</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381332\" data-slug=\"likkutei-torah\" data-id=\"4001381332\">לקו\"ת שה\"ש נא, א</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560025\" data-slug=\"or-hatorah-hb\" data-id=\"8316560025\">אוה\"ת בראשית ג, א</a>. כרך ג תעט, א ואילך."],["32","32","<b>וזהו אנכי מגן</b>: הבא לקמן בפיסקא זו הוא ע\"פ לשון ה<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490051\" data-slug=\"or-hatorah-hb\" data-id=\"8316490051\">אוה\"ת לך לך שם תרצה, א</a> בתוס' הגהות (הבאות בחצאי עיגול)."],["33","33","<b>ובזה גדלה מעלתם גם על בחי' ההתבוננות דק\"ש</b>: בצידי הגליון נרשם בגוכי\"ק: מים דפ' נח בסופו [סד\"ה מים רבים בתו\"א פ' נח שם ט, סע\"ב-ג]."],["34","34","<b>ועוי\"ל. . ע\"פ מארז\"ל ולא עם הארץ חסיד</b>: בצידי הגליון נרשם בגוכי\"ק: ביאור וקיבל [ביאור לד\"ה וקיבל היהודים ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370435\" data-slug=\"torah-or\" data-id=\"3901370435\">תו\"א מג\"א צז, ב</a>. וקאי על הבא לקמן עד קרוב לסוף הפיסקא]."],["35","35","<b>בפ' מקץ בד\"ה ויהי מקץ דרוש הראשון קרוב לסופו</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370146\" data-slug=\"torah-or\" data-id=\"3901370146\">תו\"א לא, ב</a>."]]],[2000460085,"הכלים דתומ\"צ שהן הן כלים להשראת האור, וממילא מובן דעם הארץ שאינו בתורה ומצות א\"א לו כלל להיות נמשך בו אור האהבה, ולכן הקדימו ישראל נעשה שהוא הכלים לנשמע שהוא המשכת אור פרטי לכל מצוה או אור המצות בכלל, והעיקר הוא בחי' תוס' אור מאוא\"ס ב\"ה מחמת ריבוי הכלים כו', וכענין שמצינו (מלכי' ב' ד') דכתי' אין עוד כלי ויעמוד השמן, ואילו היו עוד כלים הי' עוד ריבוי המשכת האורות כו'. ועד\"ז יובן בנמשל למעלה דכתי' כי הוי' אלקיך אש אוכלה הוא, וכמשל האש שבהעדר הפתילה מסתלק האור לשרשו כו', וכן הוא בהמשכת אוא\"ס, כשיש כלים דתומ\"צ הנה בהם וע\"י יומשך ויתאחז אור ההמשכה כו', משא\"כ בהעדר הכלי מסתלק האור למקורו ושרשו במאציל העליון ב\"ה. וגם כי המצות נק' אברי' כנודע שרמ\"ח פקודי' הם רמ\"ח איברי' דמלכא, ונת' במ\"א ההפרש בין אברי' לכלי'<sup data-n=\"36\">36</sup>, שהכלי עדיין אינו מכריח שיבא האור כו' משא\"כ האבר כשהוא בריא ממשיך בחי' חיות הנפש כו').\n<b>והנה</b> בחי' חסד יתפרש גם על בחי' חסד דאברהם שנת' כאן שהוא בחי' חפץ חסד, חסד דקשוט כו' ג\"כ, והיינו כנודע שיש מצות הוי', ויש בחי' מצותי כו', וכמ\"ש בלק\"ת בביאור ע\"פ אני ה' אלקי' דפ' ציצית דרוש השלישי פ\"ד<sup data-n=\"37\">37</sup> בענין חסדי הוי', ותורת הוי' (שתורת הוי' נק' חפצו כו') ובתורתו כו'. וכ\"ה במצות, מצות הוי' הם רמ\"ח איברי' דש' הוי' בחי' כלי' דט\"ס דז\"א כו', ויש בחי' מצותי, וכמ\"ש בד\"ה אלה מועדי הוי'<sup data-n=\"38\">38</sup> בענין ב' בחי' מועדי הוי' ובחי' מועדי כו'. ויש לבאר זה ע\"פ משארז\"ל במד\"ר ס\"פ שלח פי\"ז ע\"פ אור זרוע וע\"פ ה' חפץ למען צדקו (ישעי' מ\"ג), זרע הקב\"ה את התורה ואת המצות להנחילם לישראל לחיי העוה\"ב ע\"ש, ונת' מזה במ\"א שז\"ע הזריעה שבהם<sup data-n=\"39\">39</sup> וע\"י יומשך בחי' חפץ הוי'<sup data-n=\"e1\">*</sup> שלמעלה מבחי' רצון שיתגלה לע\"ל למטה",[["36","36","<b>ונת' במ\"א ההפרש בין אברי' לכלי'</b>: סה\"מ תרל\"ג ח\"ב ע' שנ ואילך [ועי' בנסמן במ\"מ בתחילת המאמר שם]. ס' מאמרי אדמו\"ר הצ\"צ — הנחות תרט\"ו ע' סד וע' סט [ובנסמן במ\"מ שם ע' נט]."],["37","37","<b>בלק\"ת בביאור ע\"פ אני. . דרוש השלישי פ\"ד</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380516\" data-slug=\"likkutei-torah\" data-id=\"4001380516\">לקו\"ת שלח נא, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380488\" data-slug=\"likkutei-torah\" data-id=\"4001380488\">וראה שם מד, א</a>. מו, ג."],["38","38","<b>בד\"ה אלה מועדי הוי'</b>: <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200123\" data-slug=\"or-hatorah-hb\" data-id=\"8159200123\">אוה\"ת אמור כרך ג' ע' תתלז</a> ואילך. סה\"מ תרכ\"ו ע' רעג ואילך. וראה סה\"מ תרכ\"ז ע' תכא ואילך."],["39","39","<b>ונת' מזה במ\"א שז\"ע הזריעה שבהם</b>: ראה רשימות הצ\"צ לתהלים (יהל אור) ע' שנב ואילך. סה\"מ תרכ\"ז ע' שנה ואילך."],["e1","*","<b>שבהם וע\"י יומשך בחי' חפץ הוי'</b>: בצידי הגליון נרשם בגוכי\"ק:\nואולי י\"ל חפץ הוי' הוא למעלה גם ממ\"ש בע\"ח כשעלה ברצונו כו', להיות כי חפץ הוא פנימיות הרצון כו', ואפ\"ל עלה ברצונו כו' שייך לאצי' העולמות, והמכוון הוא בשביל התו' שנק' ראשית ובשביל בראתי גימ' תרי\"ג, שבשביל זה אדם עלי' על בחי' הארץ שנמשכת מבחי' אנכי בראתי כמ\"ש מזה במ\"א, ועפ\"ז יובן מ\"ש בתו' ה' חפץ דוקא, וכ\"ה בזריעת כל המצות כו' וצ\"ע."]]],[2000460086,"כו', ועכשיו הוא להוסיף אורות באצי', וא\"כ מובן איך שהמצות ששרשם מבחי' אנכי הם בחי' מגן לגילוי אור החסד דאברהם בחי' חסד דלגאו כו' שצריך למגן כו'.\n<b>וזהו</b> בך דוקא חותמי' ולא בכולן, כי יצחק הוא מדת הפחד, וגם יעקב שהי' מרכבה למדת הת\"ת, עכ\"ז נת' בכ\"ד שנותן מקום למדת הגבורה, ע' בד\"ה וידבר אלקי' כו' דברי חכמי' כדרבונות<sup data-n=\"40\">40</sup>, ובענין כל ת\"ח שמורה כו' משבט יהודא או מיששכר כו'<sup data-n=\"41\">41</sup>, וע' בד\"ה ועבר ה' לנגוף ובהג\"ה לשם<sup data-n=\"42\">42</sup>, וא\"כ מובן שבך דוקא שהחסד שלך שרשו מבחי' חפץ חסד, חסד דלגאו צריך לחותם דוקא ע\"ד שבקש משה ונפלינו אני ועמך, וזהו ג\"כ ענין חותם בברוך, ולכן פי' מהרש\"ל שתי' והיה הוא ש' הוי' שז\"ע החתימה שחותמין ברוך אתה ה' מגן אברהם שזהו פי' והיה ברכה כו'.",[["40","40","<b>בד\"ה וידבר אלקי' כו' דברי חכמים כדרבונות</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460075\" data-slug=\"or-hatorah-hb\" data-id=\"8316460075\">אוה\"ת יתרו ע' תתצ</a> ואילך. סה\"מ תרכ\"ז ע' ש ואילך."],["41","41","<b>ובענין כל ת\"ח שמורה כו' משבט יהודא או מיששכר כו'</b>: סה\"מ תרכ\"ז שם ע' שיד ואילך [שם מביא מגמ' יומא דכ\"ו ע\"א: לא משכחת צורבא מרבנן דמורי (שמורה הוראות בישראל, רש\"י) אלא דאתי משבט לוי או משבט יששכר כו' ואימא יהודה כו']."],["42","42","<b>וע' בד\"ה ועבר ה' לנגוף ובהג\"ה לשם</b>: ראה סה\"מ תקס\"ז ע' קי ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540700\" data-slug=\"torat-chaim\" data-id=\"2300540700\">תו\"ח שמות קכג, א</a> ואילך. אוה\"ת בא (כרך ז) ע' ב'תרלג ואילך. כרך ח' ע' ב'תתקמד ואילך."]]],[2000460087,"<h3>כרמי כו' האלף לך שלמה כו' (א)</h3>\n<b></b><b>בס\"ד (ש\"פ וירא, ט\"ל).</b>\n<b>שה\"ש ח' י\"ב. </b>\n<b></b>מליץ א' מני אלף כו' ענין ההבדלות כו' מילה והבדילה הפרוכת\nוירא\n<b>כרמי</b> כו' האלף לך שלמה<sup data-n=\"43\">1</sup> ומאתים לנוטרים את פריו, וארז\"ל בגמ' שבועות דל\"ה ע\"ב כל שלמה האמורים בשיר השירים קדש, שיר למי שהשלום שלו חוץ מזה כרמי כו' לך שלמה, שלמה לדידיה, ולכן שלמה זה הוא חול. ובזח\"ב פקודי דרכ\"ז ע\"א (בפי' פסוק ואת האלף) פי' שאלף זה דהאלף לך שלמה הוא חול, ופי' שחול לאו איהו בסטרא דקדושה, ולכן יש הבדלה בין קדש לחול, ורזא דקרא הכי הוא (ויקרא בפ' שמיני סי' יו\"ד) ולהבדיל בין הקדש ובין החול כו', ועכ\"ד אע\"ג דפרישו אית לקדש מן החול חולקא חדא אית ליה בקדושה מסטרא דשמאלא, הה\"ד האלף לך שלמה, דאינון אלף יומי החול (סה\"מ ט\"ו א'<sup data-n=\"44\">2</sup>), ופי' במק\"מ שם בשם נ\"ב שהוא מהרח\"ו האלף חול שהם ע\"ס דנוגה, וענין הבדלה שבין קדש לחול, פי'",[["43","1","<b>כרמי כו' האלף לך שלמה</b>: מאמר זה מיוסד על ד\"ה ולא יקרא עוד שמך אברם, ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490095\" data-slug=\"or-hatorah-hb\" data-id=\"8316490095\">אוה\"ת לך לך (כרך ד') תשיז, א</a> ואילך. [מאמר האוה\"ת מיוסד על <a class=\"ft-cite\" href=\"#/read/torah-or/3901370052\" data-slug=\"torah-or\" data-id=\"3901370052\">תו\"א לך לך יב, א</a>. וסידור עם דא\"ח קסה, א. ובהערת כ\"ק אדמו\"ר זי\"ע (נדפס לעיל ע' 5) מציין כאן: בדרוש זה ושלאחריו ובד\"ה ויירא ויאמר נתבארו עניני ד\"ה ולא יקרא עוד וביאורו (שבתו\"א ולקו\"ת לג\"פ)]. לקמן בהוספות נדפס הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע ממאמר זה [ומתחיל: כרמי שלי לפני האלף לך שלמה]. וראה גם ד\"ה כרמי בפלח הרמון שה\"ש קכז, ב. וראה שם בראשית לח, ד."],["44","2","<b>סה\"מ ט\"ו א'</b>: ס' הדרת מלך לזח\"א דף טו, א."]]],[2000460088,"במק\"מ בין הקדושה לק\"נ, ועכ\"ד אע\"ג דפרישו אית מן הקדש לחול חולקא חדא כו' כנ\"ל, פי' המק\"מ חולקא חדא הם הבירורי' שבק\"נ. ואאמו\"ר נ\"ע ז\"ל פי'<sup data-n=\"45\">3</sup> חולקא חדא אית לי' בקדושה שזהו מקיף של העשר ספירות דקליפת נוגה שהוא לבונה, וכמבואר ענינו בפ' תולדות בד\"ה ראה ריח בני, ובהג\"ה לשם<sup data-n=\"46\">4</sup>. וצ\"ל אם חלוקים הם בפירושם, או אולי י\"ל שענינם אחד הוא.\n<b>וילה\"ק</b> פירוש הפסוקי' (איוב ל\"ג ך\"ג ך\"ד) אם יש עליו מלאך מליץ אחד מני אלף כו' ויחננו ויאמר פדעהו מרדת שחת מצאתי כפר, ופי' רש\"י ז\"ל אחד מני אלף, במגידי פשעו והוא יליץ ישרו. ויחננו, המקום. פדעהו, כמו פדאהו אל\"ף מתחלפת בעי\"ן והענין מוכיח, מצאתי כפר והוא פדיון עכ\"ל, (והוא במענה ראשונה דאליהו כו' ממשפחת רם<sup data-n=\"47\">5</sup>). ויש בפסוקי' אלו כמה דקדוקי', הא' מהו מספר אחד מן אלף שלכאו' חלק א' נגד תתקצ\"ט הוא חלק קטן מאד, ואיך עי\"ז כו'. גם לשון במגידי פשעו והוא יליץ אינו מובן, אם האחד הוא ג\"כ מן המגידי' דאל\"ף אלא שמ\"מ יליץ ישרו, ומפני כי חנון ורחום ה' יחננו המקום, או שחלוק הוא לגמרי מהם, ורק אם אחד נגד תתקצ\"ט יליץ ישרו ג\"כ יחננו המקום. גם למה בחר רש\"י לשון המקום, וגם למה כתי' פדעהו בעי\"ן שיצטרך לפרש כמו פדאהו שהעי\"ן יתחלף באל\"ף<sup data-n=\"e2\">*</sup>, וגם למה כל ענין זה אמר אליהו כו' דוקא. ויובן בהקדם ענין איך שע\"י מליץ אחד יפדה מרדת שחת, שזהו לכאו' מעומק ומיצוי הדין הקשה, וכמ\"ש בס' קה\"י ע' שחת שהוא היכל ב' דהיכל הטומאה, והוא בחי' הוד דקלי' כמ\"ש בזח\"ב פקודי דרס\"ג ע\"ב ודרס\"ד, ופי' דשחת הוא הוד דנוק' דזעיר דקלי', נוק' דקלי' הוא נחש, וע\"כ שחת ר\"ת חויא תקיפא שלטא, שבאמת זהו חסד גדול מאד שע\"י מליץ אחד שיגיד ישרו יפדה מעומק הנ\"ל<sup data-n=\"e3\">*</sup>.",[["45","3","<b>ואאמו\"ר נ\"ע ז\"ל פי'</b>: ד\"ה כרמי כו', באוה\"ת שה\"ש ר\"ע תשסב."],["46","4","<b>בפ' תולדות בד\"ה ראה ריח בני ובהג\"ה לשם</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370093\" data-slug=\"torah-or\" data-id=\"3901370093\">תו\"א כ, א</a> ואילך. אוה\"ת תולדות קנב, א ואילך. ולקמן ד\"ה ראה ריח בני."],["47","5","<b>במענה ראשונה דאליהו כו' ממשפחת רם</b>: ראה איוב שם לב, ב: ויחר אף אליהוא בן ברכאל הבוזי ממשפחת רם באיוב. ובהמשך הפסוקים שם (לב, ו. לד, א. לה, א. לו, א): ויען אליהוא גו' ויאמר."],["e2","*","<b>שהעי\"ן יתחלף באל\"ף</b>: בשולי הגליון נרשם בגוכי\"ק:\nמיער עי\"ן תלויה, וא\"ו רברבא בח\"א* מפסיק כח הנחש."],["e3","*","<b>זהו חסד גדול מאד שע\"י מליץ אחד שיגיד ישרו יפדה מעומק הנ\"ל</b>: בשולי הגליון נרשם בגוכי\"ק:\nלהעיר למ\"ש המק\"מ פקודי רך\"ז סע\"א חולקא חדא פי' הבירורי' שבק\"נ מפסוק אם כו' מליץ אחד מני אלף, ר\"ל שאם בירר חלקו בנוגה די שעי\"ז פדעהו גם משחת ג' קליפות, כי הא בהא תליא שכשבירר בק\"נ שזהו בלעו\"ז כמו אצי' לה' בקדושה, אז ממילא כהמס דונג כו' ואין תקומה למה שבג' קליפות וממילא יוצא ליכלל בקדושה."]]],[2000460089,"<b>ויובן</b> ע\"פ מ\"ש ולהבדיל בין הקדש ובין החול ובין הטמא הובא לעיל בזהר, שבאמת יש כמה מיני הבדלות, והבדלה ראשונה שנא' בתורה בעשרה מאמרות הוא מ\"ש ביום אחד למעשה בראשית ויבדל אלקי' בין האור כו', שהבדלה זו היא מקור לכל ההבדלות והפרוכות והמסכי' ופרגודים כו', כי גם בקדושה יש ג\"כ כמה בחי' הבדלות כמ\"ש והבדילה הפרוכת לכם בין הקדש ובין קדש הקדשים, שגם בין קדש לקדש הקדשים ג\"כ יש פרוכת שמבדלת, ובגמ' (כתובות דק\"ו ע\"א) אמרו י\"ג פרוכות היו במקדש שני, ז' כנגד ז' שערי' כו', וכן בענין ההבדלות ארז\"ל בפסחי' בפ' ע\"פ<sup data-n=\"48\">6</sup> הפוחת אל יפחות מג' והמוסיף אל יוסיף על ז' הבדלות שנא' בתורה.\n<b>ולהבין</b> שרש ענין ההבדלות צ\"ל תחילה מ\"ש אשר ברא אלקי' לעשות, לתקן, שענין עשי' זו דכתי' הוא ע\"ד מ\"ש ועשתה את צפרני' שתרגומו הוא ותתקן, כי כל מה שברא אלקי' בששת ימי בראשית לא בראו בכוונה שיהי' נמצא בו כל השלימות בתכלית גמר מלאכתה, אלא הניח בו דבר שלא נשלם עדיין, ועם היות כי תהי' הבריאה חסר דבר מ\"ה שצריך שיתוקן ויושלם ע\"י עבודת האדם כמ\"ש ואדם אין לעבוד, מכלל שעיקר הבריאה הי' בשביל שיעבוד האדם כו' כדכתי' ויניחהו בג\"ע לעבדה ולשמרה שארז\"ל (הובא באוה\"ח) לעבדה זו רמ\"ח מ\"ע ולשמרה שס\"ה מל\"ת, שע\"י עבודה זו יושלם ויתוקן בריאת העולם, וזהו פי' כוונת אומרו לעשות שפי' לתקן, שהכוונה בזה עמוק מאד<sup data-n=\"49\">7</sup>. ואם כי לכאו' הכוונה היא בכדי שיהי' שייכת עבודת האדם באתעדל\"ת, שלכאו' אי\"ז כוונה עמוקה כ\"כ כו'. אמנם באמת גם בזה יש למצוא עומק הרבה, וכמ\"ש במ\"א שבאמת כל ענין העבודה דכתי' כמ\"פ בתורה אינו מובן, שהלא הוא ית' שלימותא דכולהו כנודע וא\"כ כלום חסר ח\"ו שיצטרך לעבודת האדם כו', ומהו דכתי' ועבדתם את הוי' אלקיכם, ולעבדו בכל לבבכם שארז\"ל איזהו עבודה שבלב זו תפילה, וכן אומרו לעבדה ולשמרה תרי\"ג מצות כנ\"ל וכדומה, הלא מצינו גם בדרז\"ל שא' וכי מאי איכפת לי' להקב\"ה אם שוחט מן העורף או שוחט מן הצואר כו' לצרף בהן כו' א\"כ אינו צריך כלל לעבודתינו, ולפ\"ז יקשה ג\"כ למה הניח דבר שיבא ע\"י עשיותינו שז\"ע לעשות לתקן כנ\"ל. אלא שכמו שתירצו שם (בד\"ה ועבדתם דתקס\"ח, ובס' שמות ובכ\"ד<sup data-n=\"50\">8</sup>) שבמה שהזכיר לשון עבודה הזכיר ג\"כ לשון ש' הוי' אלקיכם (הגם שזהו בס' שמות היינו בד' ספרים הראשוני' כמ\"ש במ\"א בפי' דברי הרמב\"ן בענין כשלישי המדבר<sup data-n=\"51\">9</sup> כו') שמורה על זו\"נ שרש נש\"י, משא\"כ מ\"ש אנת הוא שלימותא",[["48","6","<b>בפ' ע\"פ</b>: בפרק ערבי פסחים (דף קד, א)."],["49","7","<b>חסר דבר מ\"ה. . שהכוונה בזה עמוק מאד</b>: לשון המאמר בסידור עם דא\"ח שם [וע\"ז קאי הביאור דלהלן]."],["50","8","<b>וכמ\"ש במ\"א שבאמת כל ענין העבודה. . כלום חסר ח\"ו. . בד\"ה ועבדתם דתקס\"ח ובס' שמות ובכ\"ד</b>: ד\"ה ועבדתם בסה\"מ תקס\"ח ח\"א ע' תב. אוה\"ת משפטים ע' א'קצח. סה\"מ תרל\"ג ח\"ב ס\"ע תכט ואילך. וש\"נ."],["51","9","<b>במ\"א בפי' דברי הרמב\"ן בענין כשלישי המדבר</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200123\" data-slug=\"or-hatorah-hb\" data-id=\"8159200123\">אוה\"ת אמור (כרך ג) ע' תתלז</a> ואילך. סה\"מ תרכ\"ו ע' רעג ואילך. תרכ\"ז ע' תכא ואילך."]]],[2000460090,"דכולהו קאי על בחי' אוא\"ס שהגבה למעלה מעלה לאין קץ כו' כמש\"ש. וכמ\"כ יובן בענין לעשות לתקן ג\"כ כו', ואילולי לא הניח בתחילת הבריאה דבר מה שלא נשלם עדיין, מלבד מה שאז לא הי' שייך באמת כלל ענין העבודה שהרי הי' הכל נשלם כו', הנה הנא' בעשרה מאמרות ה\"ז הוא הנותן כח וחיות לדבר ההוא שיעשה גם לאחר זמן כו', לכן אמר לשון לעשות שיורה שע\"י עבודתינו בבחי' תרי\"ג מצות יתתקן מה שחסר בכוונה בהבריאה (וי\"ל שהיינו בחי' מ\"ה בחי' ביטול היש לאין ובחי' ביטול אמיתי, שע\"ז מורה לשון דבר מ\"ה כו' וכמארז\"ל כתובות דף ה' גדולים מעשה צדיקים (היינו המקיימים תומ\"צ שע\"ש זה נק' צדיק כמ\"ש וצדקה כו' כל המצוה, ועמך כולם צדיקי' כו') ממעשה שמים וארץ, כי בריאת שמים וארץ הוא יש מאין, אבל ע\"י לעבדה ולשמרה ממשיכי' להיות ביטול היש לאין כו' כמ\"ש במ\"א באריכות<sup data-n=\"52\">10</sup>). ומה גם שבכדי שיפעול אתעדל\"ת של האדם שהוא נברא לתקן מעשה בראשית שברא אלקי' בע\"מ כו', זהו ג\"כ דבר גדול, וא\"כ ה\"ז כוונה עמוקה מאד כו'.\n<b>ועוי\"ל</b> בעומק יותר דאי משום אתעדל\"ת כנ\"ל זהו שייך לכאו' רק בגוף בריאת האדם שבראו בשני יצרין כמ\"ש וייצר בשני יודי\"ן שארז\"ל בשני יצרין יצ\"ט ויצה\"ר (שגם בזה נודע שיו\"ד א' דגושה והשני הוא היו\"ד שיוצא מהחיריק, שנמצא יו\"ד א' מורגש והשני אינו מורגש שהכוונה בזה שהיצ\"ט יהי' לו יתרון כח ועוז לשלוט על היצה\"ר להכניעו ולהשפילו עד שיהי' כפוף ובטל להנהגת השכל ע\"פ השכלת ודעת הנה\"א הוא שרש היצ\"ט שבאדם כמ\"ש הרמ\"ז כו') שזהו בכדי שיהי' שייך עבודה כנ\"ל, אמנם באמת אפ\"ל עוד כי גם באצי' הגם שאין שם חסרון כו', עכ\"ז נאצל בשני אופנים, האחד מה שבא בסוד שרש, הב' מה שבא בסוד תוס', שבחי' התוס' וריבוי אור הזה שתוספתו של הקב\"ה מרובה על העיקר כו' כנודע זהו נמשך ע\"י עבודת האדם, וע' מזה בהקדמת מהר\"נ שפירא להפע\"ח (הובא בלק\"ת בהביאור ע\"פ שבת שבתון<sup data-n=\"53\">11</sup>), וכיוון שכן שגם באצי' לא נאצל בשלימות כו' (שלפ\"ז יתפרש ועבדתם את הוי' אלקיכם שנז' לעיל על זו\"נ דאצי' כו'), לכן מזה נמשך שבבי\"ע לא נבראו בבחי' השלימות ממש כו' שחסר דבר בחי' המ\"ה כנ\"ל ממש (ועמ\"ש במ\"א בענין ופלגשו ושמה ראומה שפי' ראו מ\"ה כו', ע' בלק\"ת בסוף ד\"ה את שבתותי תשמורו בהג\"ה<sup data-n=\"54\">12</sup>, וי\"ל שזהו עוד גרוע מאשר חסר המ\"ה, שבחי' מ\"ה עם חסרון שרצונה שיהי' רואי' אותה כו' ה\"ה גרוע מאשר חסר לגמרי בחי' הביטול היש דמ\"ה שאפשר שכשיגיע בעבודה לבחי' ביטול היש יהי' בחי' מ\"ה כדבעי כו' משא\"כ כשיש בה בחי' מ\"ה, ובחי' ביטול זה דמ\"ה יש בו חסרון כ\"כ עד שכוונתה שיהי' ראו",[["52","10","<b>גדולים מעשה צדיקים. . היות ביטול היש לאין כו' כמ\"ש במ\"א באריכות</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370295\" data-slug=\"torah-or\" data-id=\"3901370295\">תו\"א בשלח סו, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380393\" data-slug=\"likkutei-torah\" data-id=\"4001380393\">לקו\"ת נשא כא, ב</a>. סה\"מ תרכ\"ז ע' רנה. סה\"מ תרל\"ג ח\"א ע' רסח. ח\"ב ע' תל ואילך. וש\"נ."],["53","11","<b>הובא בלק\"ת בהביאור ע\"פ שבת שבתון</b>: דרושים ליוהכ\"פ ע, ג."],["54","12","<b>ועמ\"ש במ\"א בענין ופלגשו ושמה ראומה. . בלק\"ת בסוף ד\"ה את שבתותי תשמורו בהג\"ה</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380260\" data-slug=\"likkutei-torah\" data-id=\"4001380260\">לקו\"ת בהר מג, א</a>. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380173\" data-slug=\"likkutei-torah\" data-id=\"4001380173\">לקו\"ת תזריע כג, ב</a>. סה\"מ תרל\"ג ח\"ב ע' תיד. וש\"נ."]]],[2000460091,"בחי' המ\"ה שבה ה\"ז אפשר גרוע יותר בדקות, ולכן נחשבת לבחי' קלי' נגד האצי' כו' כנודע, וצ\"ע).\n<b>וע\"פ</b> הקדמה יובן ג\"כ מארז\"ל במד\"ר פ' בראשית פי\"א ששאל כו' על טעם המילה, מפני מה לא ניתנה לאדה\"ר, שמתוך התשובה ניכרי' דברי שאלתו שאם אינו חפץ בערלה, למה נברא האדם בערלה, ושיצטרך האדם למול בשר ערלתו כו', שהשיב לו להוציאך חלק אי אפשר, אלא כל מה שנברא בשי\"ב צריך עשייה, כגון החרדל צריך למתוק, התורמסין צריכי' למתוק, החטין צריכין להטחן, אפי' אדם צריך תיקון, ופי' המ\"כ, וז\"ל ואומר לך למה ציוני הש\"י לחסר בברייתו, ולמה לא בראוהו נולד מהול, לפי שכל הנברא משי\"ב צריך תיקון, ורש\"י פי' מדכתי' אשר ברא אלקי' לעשות, אפי' מה שכבר נברא צריך לעשות עוד בתיקונו עכ\"ל, ונמצא כי הי' המשל הזה מתיקון התורמסין תשובה לשאלתו אם אינו חפץ כו', אשר לכאו' עדיין אינו מובן כ\"כ ענין תשובתו, ואיך המשל דומה לנמשל כו', אך ע\"י הקדמה הנ\"ל בכלל שע\"י העבודה מוסיפי' כח בגבורה של מעלה כו' שגם באצי' העליון מוסיפי' תוס' אורות שז\"ע תיקון, שזהו מה שלא נאצל בסוד שרש כו' א\"כ מזה נמשך בבריאת צומח חי מדבר שבבי\"ע שצריכי' תיקון ממש, ושע\"י תיקונם בעבודת האדם יומשך התיקון גם באצי' בסוד תוס' כו' שזהו הקדמה להתחיל להבין דברי המשל הנ\"ל ודמיונו להנמשל כו'.\n<b>ואמנם</b> להבין היטב דברי המשל הנ\"ל ודמיונו יובן בהקדם פי' דברי הפסוק דכתי' והבדילה הפרכת לכם בין הקדש ובין קדהק\"ד, ותרגום פרוכת הוא פרסא כידוע, ונודע כי בחי' הפרוכת שהי' בבהמק\"ד להבדיל בין קד\"ק להיכל, הענין הוא משום דבהיכל קדהק\"ד שבבהמ\"ק הי' גילוי אור האלקי מהיכל קדהק\"ד דבריאה, שבו מתנוצץ הארה מקדהק\"ד דאצי' כמשנ\"ת בסידור בד\"ה ביאור למ\"ש בסש\"ב פנ\"ב נ\"ג<sup data-n=\"55\">13</sup>, והוא שער הת\"ת (וע' בע\"ח שער כסה\"כ פ\"ה דשרש היכל קדהק\"ד שרשו מאד נעלה וע' בביאור ע\"פ שבת שבתון<sup data-n=\"56\">14</sup> בשם זהר הרקיע פ' בראשית), ששם גילוי אוא\"ס ממש, ולכן צ\"ל הבדלה בין בחי' קדה\"ק לבחי' קדש כו', ומזה נמשך אח\"כ הבדלה בין קדש לחול שזהו עיקר ההבדלה כנודע וכמ\"ש בש\"ע או\"ח<sup data-n=\"57\">15</sup>. ושרש ענין בחי' המסך והפרסא זו שאם הי' השפע נמשכת מאצי' לבי\"ע בגילוי ע\"ד מעילה לעלול לא הי' התהוות המלאכים, ולא בחי' ריבוי ההתחלקות, וכ\"ש שלא הי' ההתהוות הגשמיות מן הרוחניות, שאין לך בריאה יש",[["55","13","<b>בסידור בד\"ה ביאור למ\"ש בסש\"ב פנ\"ב נ\"ג</b>: סידור עם דא\"ח צז, ג ואילך. (בשער התלמוד תורה)."],["56","14","<b>בביאור ע\"פ שבת שבתון</b>: לקו\"ת דרושים ליוהכ\"פ עא, ב."],["57","15","<b>וכמ\"ש בש\"ע או\"ח</b>: ראה או\"ח סרצ\"ט ס\"י. שו\"ע אדה\"ז סקפ\"ח סי\"ז. סרצ\"ו סי\"ט. סרצ\"ט סי\"א ואילך. סתע\"ג ס\"ט."]]],[2000460092,"מאין גדול מזה כו' כנודע ממ\"ש במ\"א<sup data-n=\"58\">16</sup>, אלא כ\"ז נעשה ע\"י שיש פרסא ומסך שמעלים ומסתיר האור שלא יהא נמשך רק אור של תולדה, ומתהוים עי\"ז בבחי' יש מאין, ונז' ג\"כ ענין הפרסא זו בברייתא דר' שמעון שהביא הפרד\"ס שער הראשון פרק שביעי וז\"ל הי\"א פרגוד זהו כסא הכבוד עכ\"ל, וכ' הפרדס מקום הפסק והוא פרוכת ומסך בין האצי' לשאר דברי' שתחת האצי' עכ\"ל, ועד\"ז יש מסך בין עולם לעולם כו' עד שנתהוו שמי' וארץ וכל צבאם בבחי' הגשם ממש כו', וזהו שאנו אומרי' בנוסח ברכת יוצ\"א המחדש בטובו בכי\"ת מע\"ב, ומהו החידוש בכ\"י, אלא שזהו החידוש יש מאין שמחדש הישינות בכ\"י תמיד והיינו מה שמתהוה ע\"י סיבת הפרסא כו'.\n<b>ומעתה</b> יובן ענין בחי' ההבדלה שבין קדש לחול שזהו עיקר ההבדלה כנ\"ל, והשייך להבין ענין האלף לך שלמה, דהנה בנוסח ההבדלה במוש\"ק המבדיל בין קדש לחול, שזהו אינו כמו שמבדילין במוצאי שבת ליו\"ט המבדיל בין קדש לקדש, בהיות ידוע שהיו\"ט נק' מקראי קדש שקוראי' בהם בחי' הקדש העליון שז\"ע שחותמי' ביו\"ט מקדש ישראל והזמנים דישראל אינהו דקדשינהו לזמנים שהם קוראי' וממשיכים בחי' הקדש עליון בבחי' הזמני' שהם המועדי', וכמ\"ש אשר תקראו אתם וארז\"ל אתם אפי' כו' וכנודע שיו\"ט הם בחי' מוחין דאימא, משא\"כ שבת היא בחי' מוחין דאבא, והוא מקדשי וקיימי כמ\"ש בפ' יתרו בד\"ה זכור את יום השבת לקדשו, ובמ\"א בד\"ה ביום השמיני עצרת<sup data-n=\"59\">17</sup>, מקדש ישראל והזמנים, ולכן מבדילי' בין קדש לקדש, משא\"כ הבדלה שבמוצ\"ש לחול היא ההבדלה והמסך שמבדיל יותר גם מבחי' הפרגוד הנ\"ל הנז' בברייתא הנ\"ל ששם גם אחרי הפרגוד יש בחי' ביטול היש לאין, והיינו כי הם בי\"ע דקדושה, שעם היות שהכלים דע\"ס דבי\"ע הם ג\"כ נבראי', כמ\"ש באגה\"ק סי' ך' ד\"ה איהו וחיוהי, מ\"מ הם בבחי' ביטול, משא\"כ בחי' חול הוא ק\"נ כמשנ\"ת לעיל מהזח\"ב פקודי דרכ\"ז סע\"א והמק\"מ שם בשם הרח\"ו שהוא מהאריז\"ל, שהבדלה זו היא מסך מבדיל יותר כו' ועכ\"ז אמרו בזהר חולקא חדא אית ליה בקדושה מסטרא דשמאלא, שפי' המק\"מ הם הבירורי' שבק\"נ, והיינו מה שנפל בשה\"כ שצריכי' לבררם ולהעלותם משם, (ועמ\"ש במ\"א בענין ובקשתם משם<sup data-n=\"60\">18</sup>, קראו שם פרעה, רק י\"ל שם הוא הבירורי' שעוד למטה יותר מנוגה).\n<b>ולפ\"ז</b> פי' האלף לך שלמה היינו ששלמה עסק לברר בירורי' דק\"נ עד שע\"ס דק\"נ שזהו פי' האלף כו' נעשו לך שלמה, שלמה לדידיה, והיינו כי שלמה שלמטה שמו הי' ע\"ש בחי' השלום כמ\"ש ושלום יהי' בימיו, וא\"כ גם מה ששלמה",[["58","16","<b>שאין לך בריאה יש מאין גדול מזה כו' כנודע ממ\"ש במ\"א</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380799\" data-slug=\"likkutei-torah\" data-id=\"4001380799\">לקו\"ת פ' ראה כ, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380940\" data-slug=\"likkutei-torah\" data-id=\"4001380940\">דרושים לר\"ה נה, ב</a>. דרמ\"צ קפז, ב. סה\"מ תרכ\"ז ע' שפז וע' תיח (הוצאת קה\"ת תש\"ס). ובכ\"מ."],["59","17","<b>בפ' יתרו בד\"ה זכור את יום השבת לקדשו ובמ\"א בד\"ה ביום השמיני עצרת</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370310\" data-slug=\"torah-or\" data-id=\"3901370310\">תו\"א סט, ג</a> ואילך. אוה\"ת שמע\"צ (כרך ו') ע' ב'תקמ ואילך. וש\"נ."],["60","18","<b>ועמ\"ש במ\"א בענין ובקשתם משם</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380541\" data-slug=\"likkutei-torah\" data-id=\"4001380541\">לקו\"ת חוקת נו, ב</a>. ראה לב, ג. אוה\"ת פ' חוקת ע' תשעז. תשעט. תתיד."]]],[2000460093,"לדידיה אינו גרוע עכ\"פ מכמו בחי' שלום בפשמ\"ט שנת' במ\"א בפי' שלום בפשמ\"ט היינו הארת כחות נפש האלקית המלובשת בגוף ונה\"ב שלא יהא מונע ומעכב מצד הגוף ונה\"ב רק שיהיו כולם מסכימים ומתרצים לייחוד זה, ע' בפ' יתרו בד\"ה בחדש השלישי<sup data-n=\"61\">19</sup>, ועי\"ז נעשה האלף לך שלמה, בחי' בירורי' דנוגה יהיו לך שלמה שישלימו אתו ע\"ד שלום הנה\"ב וכוחות הגוף הנ\"ל כו'.\n<b>וענין</b> מה שע\"ס דנוגה נק' אלף י\"ל ע\"ד שנזכר בזהר ר\"פ ויגש בענין שלא נברא העולם באל\"ף, משום שממנו יש יניקה לארור, ולכן נברא העולם בבי\"ת שיש בו סימן ברכה, ופי' רבינו אדמו\"ר נ\"ע ז\"ל<sup data-n=\"62\">20</sup> כי אף שאל\"ף גבוה מהבי\"ת, כי אל\"ף בכתר ובי\"ת בחכ', בחכמה יבנה בית, אלא כי מכתר מאריך אף לרשעים משום דשם כחשיכה כאורה, שממית בידי' תתפש, וזהו אם תגביהי כנשר שיניקתם מרוממות הא\"ס כמ\"ש בפ' וישלח בד\"ה ויאבק איש עמו<sup data-n=\"63\">21</sup>, ובד\"ה כי עמך מקור חיים בפ' מקץ<sup data-n=\"64\">22</sup>, ומ\"מ בשעת מ\"ת בעשה\"ד פתח באל\"ף, אנכי, כי אחר שכבר נברא העולם בבי\"ת שוב אין יניקה גם מהאל\"ף, וזהו פי' אב<sup data-n=\"65\">23</sup>, ואזי האלף לך שלמה, שגם מק\"נ היונקת ממקום גבוה יתברר ויוכלל בקדושה, וז\"פ שלמה לדידיה ע\"י הבירורים כו', (וי\"ל ג\"כ שז\"ע אף חכמתי עמדה לי חכמתי שלמדתי באף עמדה לי, כי עיקר קבלת הנוגה הוא ממל' דעשי' ע\"י הפרסא המבדלת בין קדש לחול בבחי' העלם והסתר גמור וכנ\"ל שזהו מסך המבדיל, ונודע מענין אף עשיתיו שאף מפסיק הענין בין יצי' לעשייה ועכ\"ז אף מרבה בחי' רביעית כמ\"ש בלק\"ת פ' בלק בד\"ה מי מנה עפר יעקב<sup data-n=\"66\">24</sup>, וכמו\"כ י\"ל כאן שע\"י חכמתי שלמדתי באף עשיתיו הם דיני ההלכות להבדיל כו' (וע' במד\"ר שה\"ש שעשה אזנים לקופה), לברר ק\"נ היא עמדה לי עד שהאלף דע\"ס דנוגה נעשים לך שלמה כו'<sup data-n=\"e4\">*</sup>.",[["61","19","<b>במ\"א בפי' שלום בפשמ\"ט. . בפ' יתרו בד\"ה בחדש השלישי</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370301\" data-slug=\"torah-or\" data-id=\"3901370301\">תו\"א סז, ב</a>. וראה גם סה\"מ תרל\"ב ח\"א ע' פד. תרל\"ג ח\"א ע' נט. ח\"ב ע' ס."],["62","20","<b>ופי' רבינו אדמו\"ר נ\"ע ז\"ל</b>: ראה סה\"מ תקס\"ח ח\"ב ע' תרסב ואילך. ביאוה\"ז להצ\"צ ע' תשיג ואילך. וראה לקמן ד\"ה אתה אחד (ע' מה). וש\"נ."],["63","21","<b>בפ' וישלח בד\"ה ויאבק איש עמו</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370121\" data-slug=\"torah-or\" data-id=\"3901370121\">תו\"א כו, א</a> ואילך. לקמן ד\"ה אתה אחד."],["64","22","<b>ובד\"ה כי עמך מקור חיים בפ' מקץ</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370159\" data-slug=\"torah-or\" data-id=\"3901370159\">תו\"א לד, ג</a>."],["65","23","<b>וזהו פי' אב</b>: ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490101\" data-slug=\"or-hatorah-hb\" data-id=\"8316490101\">אוה\"ת לך לך שם תשכ, א</a>: וזהו פי' אם כו' [ואפשר כוונתו שם על הפסוק (דלעיל) אם תגביה כנשר משם אורידך וגו']."],["66","24","<b>בלק\"ת פ' בלק בד\"ה מי מנה עפר יעקב</b>: סט, ג ואילך."],["e4","*","<b>כו'</b>: בשולי הגליון נרשם בגוכי\"ק:\nי\"ל לי היינו ארבעי' ד' יודין כמ\"ש בענין ודודי לי היינו נגד אבי\"ע שז\"ע שאף עשיתיו מרבה בחי' רביעי' רצה\"ע שנת' בד\"ה מי מנה שהכוונה שם על אצי'."]]],[2000460094,"<h3>[האלף לך שלמה] ואמנם כו' שלמה זה חול כו' (ב)</h3>\n<b></b><b>בס\"ד. (ש\"פ חיי שרה, ט\"ל).</b>\nקדש ישראל כו' יאשמו כו'\nחיי שרה\n<b>ואמנם</b> עדיין צ\"ל, דאם כמשנ\"ת דפי' האלף לך שלמה היינו מה ששלמה הי' מברר ק\"נ שעי\"ז נעשה בחי' האלף דק\"נ בבחי' לך שלמה שהשלימו אתו להתרצות ולהסכים ע\"ד בחי' שלום בפשמ\"ט כמשנת\"ל, אמאי שלמה זה חול כנ\"ל (שבועות דל\"ה ב' ובזח\"ב פקודי דרכ\"ז ב'). אך הענין יובן ע\"פ מש\"כ באגה\"ק סי' ך\"ו שכשהמל' מתלבשת בק\"נ לברר עה\"ד טו\"ר, נקראת גם היא עה\"ד טו\"ר ע\"ש באריכות, ועד\"ז כ' המאו\"א אות ח' סעי' ע\"ו חולין במט\"ט עשוים בטהרה, אך תרומה קדש בבריאה עכ\"ל, והנראה כי מפרש מט\"ט ו\"ק דיצי' שהם בחי' שתא סדרי משנה איסור והיתר, כשר פסול, טמא טהור שהוא בחי' הבירורי' לברר ולהעלות מק\"נ כמ\"ש בבה\"ז פ' בראשית בד\"ה לא טוב היות האדם<sup data-n=\"67\">1</sup>, וה\"ז ע\"ד שמפרש באגה\"ק הנ\"ל. והנה בגמ' שבועות שם, וי\"א זה קדש, וזה חול דמטתו. והיינו שמ\"ש הנה מטתו שלשלמה ששים גבורי', שלמה זה חול הוא, אבל מ\"ש האלף לך שלמה הוא קדש, והיינו מלך שהשלום שלו כמו בכל שה\"ש, וכ\"מ מהמד\"ר במקומו תני ר' חייא כו' ע\"ש, ולפ\"ז פי' שלמה יתפרש גם על בחי' שלום בפשמ\"ע ולא כמו שלמה לדידיה שהוא עכ\"פ שלום בפשמ\"ט כנ\"ל אלא גם על בחי' שלום בפשמ\"ע כו' שבעבודה בנפש האדם זה\"ע בחי' גילוי אוא\"ס ב\"ה ממש בנפש האלקית להיות קשורה ומיוחדת בבחי' ביטול ממש, כי שלום היינו התקשרות כו'.\n<b>והענין</b> הוא שבפי' האלף לך שלמה<sup data-n=\"68\">2</sup> פי' הת\"י אלף הם עשרת השבטים שע\"פ הנביא אחיה השלוני נפרדו ממלכות רחבעם, ומאתים הם יהודה ובנימין שנשארו תחת מלכי יהודה, והנה י\"ב שבטים הם בחי' י\"ב בקר דבריאה, ושרשם י\"ב גבולי אלכסון כמ\"ש ששם עלו שבטים שבטי י\"ה כו' וכמ\"ש במ\"א באריכות<sup data-n=\"69\">3</sup>.\n<b>והנה</b> לע\"ל כתי' ונקבצו<sup data-n=\"70\">4</sup> בני יהודה ובני ישראל כו', פי' יהודה הוא מל' הפעם אודה שהוא בחי' הודאה שמלמטה למעלה שמודה שכן הוא, ועכ\"ז היא בחי' השתחואה ביטול כמ\"ש בפ' ויחי בד\"ה יהודה אתה<sup data-n=\"71\">5</sup>, ומ\"מ הוא בחי' יחו\"ת דעת תחתון, וישראל הוא בחי' מלמעלמ\"ט ישר אל, לי ראש ומוחין בחי' יחו\"ע ד\"ע כו', ונקבצו יחדיו שיהי' הכל ביחד, ושמו להם ראש אחד, שעכשיו הם שני בחי' יחו\"ע",[["67","1","<b>בבה\"ז. . בד\"ה לא טוב היות האדם</b>: דף ב, ג ואילך."],["68","2","<b>ואמנם עדיין צ\"ל כו' האלף לך שלמה</b>: מאמר זה הוא המשך למאמר שלפנ\"ז ד\"ה כרמי גו' האלף, והוא מיוסד על <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770393\" data-slug=\"or-hatorah-hb\" data-id=\"8316770393\">אוה\"ת שה\"ש כרך ב' ע' תשסא</a> ואילך (ד\"ה כרמי שלי). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380642\" data-slug=\"likkutei-torah\" data-id=\"4001380642\">לקו\"ת פינחס פ, ג</a> ואילך (ד\"ה קדש ישראל). לקמן בהוספות נדפס הנחת כ\"ק אדמו\"ר מוהרש\"ב ממאמר זה [ומתחיל: ד\"ה האלף לך שלמה]."],["69","3","<b>והנה י\"ב שבטים הם בחי' י\"ב בקר דבריאה. . וכמ\"ש במ\"א באריכות</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370133\" data-slug=\"torah-or\" data-id=\"3901370133\">תו\"א וישב כח, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370208\" data-slug=\"torah-or\" data-id=\"3901370208\">ויחי מה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380070\" data-slug=\"likkutei-torah\" data-id=\"4001380070\">לקו\"ת פקודי ז, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380700\" data-slug=\"likkutei-torah\" data-id=\"4001380700\">מסעי צד, א</a>. ד. דברים כז, ג."],["70","4","<b>והנה לע\"ל כתי' ונקבצו</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380334\" data-slug=\"likkutei-torah\" data-id=\"4001380334\">לקו\"ת במדבר ו, ג</a> ואילך [ד\"ה והי' מספר]."],["71","5","<b>בפ' ויחי בד\"ה יהודה אתה</b>: תו\"א מה, א ואילך."]]],[2000460095,"ויחו\"ת, וכענין שנא' כי לא מחשבותי מחשבותיכם שמלמעלה למטה כל מה שהוא מטה מטה הוא כאין ואפס לגבי שלמעלה הימנו, משא\"כ מלמטה למעלה הוא בהיפך שהבריאה היא יש מאין שלמטה הוא היש, אבל לע\"ל יהי' ראש אחד היינו כמ\"ש בזהר למהוי אחד באחד כו', והיינו מפני כי לע\"ל יהי' עליית והזדככות העולמות שבחי' עלמא דאתגלי' יזדכך להיות בבחי' מעלת עלמא דאתכסיא.\n<b>וזהו</b> דכתי' ביום ההוא יהי' הוי'<sup data-n=\"72\">6</sup>, ופי' בלק\"ת מהאריז\"ל שלע\"ל אותיות דש' הוי', יהי' כמו תיבת יהיה, והיינו ב\"פ י\"ה, ולא כמו עכשיו שהם ב' בחי' י\"ה ו\"ה, כ\"א ששניהם יהי' בבחי' י\"ה, ור\"ל שבחי' ו\"ה שהם בחי' זו\"נ בחי' מדות ודבור יהיו לע\"ל כמו בחי' י\"ה שהם או\"א, והיינו כי עכשיו בחי' המל' שהיא ה' אחרונה דש' הוי' בחי' דבר ה' מקבלת מבחי' וא\"ו (שעם היות שבראשו יו\"ד) שהו\"ע המשכה מלמעלמ\"ט, ועמ\"ש מזה בפ' ויצא בד\"ה ושבתי בשלום<sup data-n=\"73\">7</sup>, שזהו כמו מים יורדי' מגבוה לנמוך, מ\"מ ההמשכה אינו עצמיות היו\"ד ממש, כ\"א שהולך ומתקצר ונעשה דק יותר הרבה מיו\"ד עצמו שבראש הוא\"ו, והו\"ע קלישות האור כמ\"ש במ\"א בענין כפילא וקלישא<sup data-n=\"74\">8</sup>, ומבחי' הוא\"ו נמשך לבחי' ה' תתאה, וכמ\"ש במ\"א שכאשר המדות מאירי' בתוקף אינו יכול לדבר<sup data-n=\"75\">9</sup> מחמת ריבוי ההתפעלות, א\"כ גם המדה בהכרח שתתצמצם וכ\"ש היו\"ד שבראש הוא\"ו שרומז לבחי' מוחין שבמדות כו', אבל בחי' י\"ה אינו ע\"י המשכה, אלא כי היו\"ד עצמו מתגלה בה\"א והכל בחי' אחת, ולכן איתא בספרים בענין כתיבת ש' הוי'<sup data-n=\"76\">10</sup> שה\"א ראשונה דש' הוי' עושי' תחילה יו\"ד<sup data-n=\"e5\">*</sup> ואח\"כ ממשיכי' מיו\"ד זה עצמו רוחב גג הה\"א. אמנם לע\"ל יתעלה העולם שבחי' עלמא דאתגליא יהי' בבחי' ומדריגת עלמא דאתכסיא, ויהי' זו\"נ המדות והדבור ג\"כ בבחי' י\"ה שהם או\"א. וז\"ע ונקבצו בני יהודה ובנ\"י יחדיו שיחו\"ת יהי' ג\"כ במדריגת יחו\"ע, ופי' כי יהודה הוא בבחי' מל' איהי בהוד, וישראל לי ראש היינו בחי' ז\"א מהחזה ולמעלה שבו מאירין המוחין דאו\"א, ולעתיד תהיה ספירת המל' ג\"כ במדריגת ז\"א,",[["72","6","<b>וזהו דכתי' ביום ההוא יהי' הוי'</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380339\" data-slug=\"likkutei-torah\" data-id=\"4001380339\">לקו\"ת במדבר שם ז, ד</a>."],["73","7","<b>בפ' ויצא בד\"ה ושבתי בשלום</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370100\" data-slug=\"torah-or\" data-id=\"3901370100\">תו\"א ויצא כא, ב</a>."],["74","8","<b>במ\"א בענין כפילא וקלישא</b>: ראה תו\"א טו, ד."],["75","9","<b>וכמ\"ש במ\"א. . המדות מאירי'. . אינו יכול לדבר</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380936\" data-slug=\"likkutei-torah\" data-id=\"4001380936\">לקו\"ת</a> דרושים לר\"ה נד, ב-ג. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080137\" data-slug=\"or-hatorah-hb\" data-id=\"8160080137\">אוה\"ת ויקרא (כרך א) ע' קלז</a>. ובכ\"מ."],["76","10","<b>ולכן איתא בספרים בענין כתיבת ש' הוי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380339\" data-slug=\"likkutei-torah\" data-id=\"4001380339\">לקו\"ת במדבר שם ז, ד</a>. מסעי צה, ב ובהמ\"מ שם."],["e5","*","<b>שה\"א ראשונה. . עושי' תחילה יו\"ד</b>: בשולי הגליון נרשם בגוכי\"ק:\nלכאו' צ\"ע ממ\"ש שגם ה' אחרונה עושי' וא\"ו תחילה, ומיו\"ד שבראשו עושי' ה' אחרונה ה\"ז היפך משנ\"ת כאן בענין קלישא שמתקלש האור ע\"י אורך הוא\"ו. וי\"ל ע\"ד שבי\"ה יש הבן בחכ' וחכם בבינה, עד\"ז עושי' בכתי' ה' אחרונה בתפילין דוקא שגם בו\"ה דעכשיו יהי' ג\"כ כמו בי\"ה, אמנם עכשיו ההמשכה היא בסיום הוא\"ו בה' כמו שהדבור מקבל ממדות כו'."]]],[2000460096,"אור הלבנה כאור החמה, ואז ושמו עליהם ראש אחד שהוא בחי' תפארת דאימא שיהי' כתר לשניהם בשוה, וע' בכי\"ק בפ' תרומה גבי ענין הכרובי'<sup data-n=\"77\">11</sup> כו'.\n<b>והנה</b> הראש יהי' דוד<sup data-n=\"78\">12</sup>, וכמ\"ש ביחזקאל קח לך עץ אחד וכתוב עליו ליהודה כו' ולקח עץ אחד וכתוב עליו ליוסף עץ אפרים כו' אחד אל אחד כו' ונתתי אותם עליו את עץ יהודה כו' עד ועבדי דוד כו', והיינו כי עתה יוסף הוא למעלה מיהודה, שעשרת השבטי' היו בחלקו של ירבעם שהי' משבט אפרים, והי' מרובה בשבטי' מיהודה, ויוסף הוא המשפיע כמ\"ש אלה תולדות יעקב יוסף שהגילוי' של בחי' יעקב הוא ע\"י יוסף בחי' יסוד צ\"ע, וכתי' ויוסף הוא המשביר כו'. אך לע\"ל כשיהי' (איוב מ\"א) אחד באחד יגשו, ויתחברו שניהם בתכלית היחוד האמיתי אז יתעלה יהודה למעלה מיוסף, וכמ\"ש אשת חיל עטרת בעלה, ולכן אז ועבדי דוד דוקא, וזהו הראש אחד, ולכן בהמ\"ז על כוס יין המשומר שלע\"ל יברך דוד דוקא, כמארז\"ל שא' לי נאה לברך. וא\"כ אפ\"ל דע\"ז יתפרש האלף לך שלמה שיוחזרו עשרת השבטי' תח\"י דוד ושלמה, וכדעת הי\"א ששלמה זה קדש, והוא בחי' מלך שהשלום שלו, וי\"ל שלמה מל' ולע\"ל יומשך בו שרשו שבכתר שז\"ע מלך שהשלום שלו, ולכן הכוס של ברכה שיברך דוד יחזיק רך\"א לוגין כמנין ארך דהיינו בחי' כתר, וכמ\"ש והי' ה' למלך כו'.\n<b>והנה</b> רש\"י ז\"ל פי' ג\"כ דקאי על לע\"ל רק פי' שיחזירו אלף ויוסיפו חומש כדין המועל בקדשי'<sup data-n=\"e6\">*</sup>, היינו בבחי' קדש ישראל לה', ומאתים הוא חומשו של אלף וזהו כר\"י<sup data-n=\"79\">13</sup> בב\"מ פרק הזהב דנ\"ד ע\"א, ואנן קי\"ל כר' יאשיא שיהי' הוא וחומשו",[["77","11","<b>בכי\"ק בפ' תרומה גבי ענין הכרובים</b>: תו\"א פא, א ואילך."],["78","12","<b>והנה הראש יהי' דוד</b>: בהבא להלן ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370199\" data-slug=\"torah-or\" data-id=\"3901370199\">תו\"א ויגש מד, א</a> ואילך."],["79","13","<b>והנה רש\"י ז\"ל פי' ג\"כ. . וזהו כר\"י</b>: ענין זה נמצא בארוכה יותר להלן [פיסקא: והנה משנ\"ת לעיל]."],["e6","*","<b>במהדו\"ק של המאמר, נרשם כאן בגוכי\"ק (אך במהדו\"ב נשמט קטע זה)</b>:\nהביאו השל\"ה דשס\"ו א' בתושב\"כ ס\"פ פנחס, וע' בסש\"ב פל\"ז באריכות בענין מה שלע\"ל תצא ק\"נ מחלאתה וטומאתה ע\"י הבירורי' דעכשיו, וע\"ש גבי אתרוג שצ\"ל שלא מערלה שמה שג' שנים ערלי' יהיו לכם א\"א להתברר ע\"ש בהג\"ה, ולכאו' הלא קאי גם על נ\"נ שיש דיעה שהוא מג\"ק, אלא שצ\"ל שזהו ע\"י מצות ל\"ת כמ\"ש בסש\"ב שם, ומ\"מ העיקר קאי על מ\"ש ואת החזיר כי מפריס פרסה הוא, שהוא פסוק בפ\"ע, שזהו מה שלא ראה אבינו יעקב כמה עווקים הוא עולה שיש דיעה (ואפשר היא העיקר) שהוא מק\"נ, ורע שבדקות צריך בירור יותר וכבד יותר (כן שמעתי מהרז\"ו ע\"ה בשם רבינו), וגם אפ\"ל שמפני שק\"נ היא ממוצע בין הקדושה לג\"ק לכן בבירורה תלוי' העלאת הנצוצי' שע\"י מל\"ת גם מג\"ק להיות וארה\"ט אעביר וכענין כלי חרס שבירתן זהו תקנתן כו'."]]],[2000460097,"חמשה ע\"ש, וע' בשל\"ה דשס\"ו א' בתושב\"כ ס\"פ פנחס, ויובן זה ע\"פ מ\"ש חדלו לכם<sup data-n=\"80\">14</sup> מן האדם אשר נשמה באפו, שפי' בזח\"ב תצוה דקפ\"ב סע\"א וע\"ב שהחליף נשמתו מן נר\"נ שהיא העיקר בכעסו, ואי תימא הא רוגזא דרבנן, רוגזא דרבנן טב איהו לכל סטרין כו' אורייתא קא מרתחא ליה, דכתי' הלא כה דברי כאש, ובחי' נשמה זו לפי פי' הזהר דחשיב רק ד' בחי' נר\"נ ונשמתא לנשמתא<sup data-n=\"81\">15</sup> הנה היא כוללת חו\"ב<sup data-n=\"e7\">*</sup>, וע' בזח\"ב משפטים דקך\"א סע\"א, לא אעדי רחימותא מנהון עד דקרא לון ואנשי קדש, וענין מה שנש\"י נק' קדש ישראל לה' וגם ואנשי קדש זהו ע\"י העבודה שפועל בעצמו להיות בבחי' קדש ישראל לה', שיש ב' בחי' יעקב וישראל, יעקב הוא בחי' יו\"ד עקב היינו מה שיורד מבחי' יו\"ד לברר בירורי' מבחי' עקב, היינו מה שעקוב הלב מכל ואנוש הוא, פי' אנוש הוא חלש, עד שאינו יכול לצאת ממאסר הגוף המונע ומעכב מלבוא לבחי' הביטול לאלקות, כי מצד התבוננות אוא\"ס ב\"ה הסוכ\"ע, ואיך שבורא קדושי' ישתבח שמך שגם בחי' הקדושי' שקדושי' בכ\"י יהללוך סלה, כמ\"ש בלק\"ת פ' בהר בד\"ה את שבתותי תשמרו<sup data-n=\"82\">16</sup>, הם ג\"כ רק מבחי' שמך לבד, שאינו אלא בחי' זיו לבד, אבל הוא ית' בכבודו ובעצמו רם ונשא, והוא הוא הסוכ\"ע ומעלה ומטה שוים לפניו כו', וכמ\"ש אני הוי' לא שניתי, אשר מהעמקת הדעת בהתבוננות זו הי' צריך לבוא להשתפך הנפש אל חיק אבי' להיות נכספה וגם כלתה נפשי, מי לי בשמי' ועמך לא חפצתי בארץ, שו\"א הם געה\"ע והתחתון, וכאשר יתבונן בכ\"ז שהוא רק הארה בעלמא מבחי' ממכ\"ע, לא יחפוץ לא בגעה\"ת ולא בגעה\"ע כ\"א ליכלל ולבטל באוא\"ס ב\"ה עצמו\"ה הסוכ\"ע, וע\"ז הוא שמתמה הנביא",[["80","14","<b>ויובן זה ע\"פ מ\"ש חדלו לכם</b>: בכל הבא להלן [עד פיסקא: והנה משנ\"ת לעיל] מיוסד על ד\"ה קדש ישראל ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380642\" data-slug=\"likkutei-torah\" data-id=\"4001380642\">לקו\"ת פינחס פ, ג</a> ואילך."],["81","15","<b>שברוב המקומות פי'. . נשמתא לנשמתא קאי על ח\"י</b>: ראה סה\"מ תרל\"ג ח\"א ע' קצה. וש\"נ. ח\"ב ע' שכח. וש\"נ."],["82","16","<b>בלק\"ת פ' בהר בד\"ה את שבתותי תשמרו</b>: מא, ב ואילך."],["e7","*","<b>במהדו\"ק נרשם כאן בגוכי\"ק</b>:\nוכמובן ממ\"ש בזח\"ב משפטי' דקך\"א סע\"א ר' יצחק א' וכן יובלא אתקרי קדש, דכתי' יובל היא קדש תהי' לכם, וישראל כלילן מנייהו (כוונתו על חו\"ב ואפשר כח\"ב, ואם גם הכתר בכלל צ\"ל שזהו שרש החכ' היינו האין המוציא חכ', ולא נשמתא לנשמתא שזהו יחידה שבנפש), וחשיב שם ד' מדריגות ממלכת כהנים, גוי קדוש, עם קדוש, אנשי קדש, ולפי פי' המק\"מ קאי על נרנ\"ח, וצ\"ע לדבריו מה שבזהר אינו מחלק כ\"א על ד' בחי' לבד, אם לא שנאמר שחי' נכלל בכלל נשמה ודחוק לאמר כן שברוב המקומות פי' מ\"ש בזהר נשמתא לנשמתא קאי על ח\"י שנז' במד\"ר ובמדת\"ל, כי כל הכועס נשמתו מסתלקת ממנו, ובמק\"מ מביא מארז\"ל שכל הכועס אפי' שכינה אינה חשובה כנגדו, ופי' שכינתא עילאה בינה וכן מארז\"ל אם חכם הוא חכמתו מסתלקת, (מכאן ראי' דנשמה קאי על חו\"ב)."]]],[2000460098,"מדוע לא כליתם<sup data-n=\"83\">17</sup> פי' שמחמת התבוננות אני הוי' לא שניתי כנ\"ל ה\"צ לבוא לבחי' כלות הנפש ומדוע לא כליתם, אלא שהדבר הגורם לזה הוא מה שמעיד הכתוב באמרו ואתם בני יעקב, מל' עקוב הלב כנ\"ל שאנוש הוא בבחי' חלישות מפני כי כשל בעוני כחי שע\"י העוונות שאדם דש בעקביו נכשל ונתחלש כוחות הנפש, וכמ\"ש כ\"א עונותיכם היו מבדילים ביניכם לבין אלקיכם כו', ובאמת ל\"ד עוונות ממש, אלא גשמיות הגוף וחומריותו הוא שנעשה מסך מבדיל שהוא הוא המיצר וגבול שמגביל ומלביש את הנפש עד שמורידה לימשך אחרי' ואינה יכולה לעלות ולצאת ממנה כו', ולזה ניתנה התורה לישראל שהתו' נק' עוז ותושי', פי' תושי' שמתשת כח תאוות הגוף (כנודע מריש לקיש) והנה\"ב, ועוז שנותנת כח לנה\"א להתגבר על הגוף ונה\"ב לצאת ממאסרו הנ\"ל ולבוא לדבקה בו ית'. ואז נק' שמו ישראל שהוא ע\"ש כי שרית עם אלקי', וכידוע ששרש נה\"ב נמשך מק\"ך צירופי אלקי', משא\"כ נה\"א שרשה מש' הוי' כמ\"ש כי חלק הוי' עמו שנמשכת מבחי' ש' הוי', וזהו בראשית בשביל התו' שנק' ראשית ובשביל ישראל שנק' ראשית שנש\"י הם בחי' ראשית תבואתה ע\"י שירד מהיו\"ד שרש נש\"י לברר בחי' העקב הנ\"ל, וכשמנצח בחי' בירור זה נק' ישראל מל' כי שרית שמושל ושולט על הנה\"ב וכוחות הגוף לבלי ימנעו אותו מלדבקה בו אוא\"ס חיי החיים כו', ועי\"ז מתעלה בבחי' קדש העליון להיות ואנשי קדש תהיו לי בחי' קדש ישראל להוי' שהוא עולה ונכלל בפנימיות רצון העליון ב\"ה. אבל כשטורף נפשו באפו, שע\"י אפו הנה הוא טורף נפשו כמארז\"ל שנשמתו מסתלקת הימנו, שזהו שאה\"כ כל אוכליו יאשמו פי' אוכליו שאוכל בחי' האדם שלו עצמו דהיינו כח הארת נשמתו אשר מחודש בו בכל יום תמיד הנה הוא דוחה אותה ח\"ו עד שאינה יכולה להאיר בקרבו (להיות כי שרית עם אלקי') והיינו מחמת כעס, או מחמת תאוות, או מחמת גסות כמ\"ש לא יגורך רע כו' והנשמה היא חלק הוי', לכן בכל אלו וכיוצא בהן יכול לאכול בחי' ישראל שבו, וכמו שהאכילה נבלע כו' כן כתי' בהושע סי' ח' ח' ג\"כ לשון בליעה על ישראל, והיינו שנבלע בחי' ישראל שבו בז' מדות הרעות שהם מכוחות מצרים וכנען, לזאת כתי' כל אוכליו יאשמו, יביא אשם כמועל בקדשים שהי' מביא איל ומקריב השמנונית הוא החלב, וגם הדם החמימות ע\"ג המזבח, כן גם הוא מחוייב לעשות כן, להקריב חלבו ודמו, ולא סיגופי' בלבד, אלא מרירות להתמרמר לבו בקרבו, כדי שיהי' בבחי' לב נשבר ונדכה שזה גם ש' אלקי' לא תבזה, והיינו שבקרבנות כתי' קרבן לה', אבל לב נשבר כו' ה\"ז קרבן גם למה\"ד דש' אלקי' כו', וזהו דכתי' שמנת עבית כשית (בשין שמאלית), פי' בשמנונית ובגשמיות שלך כסית אור נשמתך עד שאינה יכולה להאיר ולשלוט בך, אך תיבת כשית כתי' בשין לרמז על זכות אבות שיש עוד זכות ג' אבות וכמארז\"ל במד\"ר בחקותי ס\"פ ל\"ו א\"ר אחא לעולם זכות אבות קיימת, וי\"ל חלב ודם זהו חו\"ג, ומרירות מעורר רחמי' כמ\"ש בהגהות לד\"ה ועבר ה' לנגוף<sup data-n=\"84\">18</sup> את מצרי' שז\"ע מרור שבקערה, וע\"י שמעורר ר\"ר על נפשו עי\"ז",[["83","17","<b>אני הוי' לא שניתי. . שמתמה הנביא מדוע לא כליתם</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370300\" data-slug=\"torah-or\" data-id=\"3901370300\">תו\"א יתרו סז, א</a>. סה\"מ תרל\"ג ח\"א ע' רצה."],["84","18","<b>בהגהות לד\"ה ועבר ה' לנגוף</b>: לע\"ע לא הגיעו לידינו הגהות אלו. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381188\" data-slug=\"likkutei-torah\" data-id=\"4001381188\">לקו\"ת שה\"ש יד, ד</a> ואילך. סה\"מ תרכ\"ט ע' קמב. תרל\"ב ח\"א ע' כד."]]],[2000460099,"יוצא ממסגר אסיר הוא בחי' ישראל היא הנשמה נה\"א שבאדם שנטרפה באפו בכעסו וכדומה כו',\nועפ\"ז יובן עוד בענין יאשמו<sup data-n=\"85\">19</sup> כי הנה במועל בקדשי' כתי', ואת אשר חטא מן הקדש ישלם וחמשיתו יוסף עליו, והחומש הוא אחד מן הארבעה מן הקרן עד שיהי' הוא וחומשו חמשה כמ\"ש בגמ' ב\"מ בפרק הזהב ובהרמב\"ם ה' מעילה<sup data-n=\"86\">20</sup>, והענין הוא כמבואר במ\"א ע\"פ ומספר את רובע ישראל<sup data-n=\"87\">21</sup> שבבחינת ישראל יש ד' בחי' היינו כמ\"ש ולכבודי בראתיו יצרתיו אף עשיתיו שהם ג' בחי' מח' דבור ומעשה, ואף דעשיתיו מרבה בחי' רביעית והוא בחי' רצה\"ע שלמעלה מעלה מבחי' מחדומ\"ע, והוא הנמשך ומתגלה בנפש ע\"י מעשה המצות, וד' בחי' אלו הם ממש ד' אותיות דש' הוי', וזהו קדש ישראל להוי', וכשמעל בקדשים ואכל בחי' ישראל שבו, צ\"ל תשובה בחי' תשוב ה', והוא בחי' עומקא דליבא, ממעמקים קראתיך, שזהו בחי' חמישית שלמעלה מד' מדריגות הנ\"ל שהן בחי' ומעלת הצדיקים, והיינו כמ\"ש במ\"א שהרצון עליון יש לו ב' בחי'<sup data-n=\"88\">22</sup>, הא' המלובש בחכמה שבחי' רצון זה נמשך ע\"י תורה ומצות שהן הן רצה\"ע המלובש בחכ' דאורייתא מחכ' נפקת, וז\"ע היו\"ד דש' הוי' שהוא בחי' חכ' שבו מלובש הרצה\"ע שהוא קוצו של יו\"ד, אך הבחי' הב' הוא בחי' רצון עליון שלמעלה מעלה מסדר ההשתלשלות ואינו מלובש כלל בבחי' חכ', ונק' רעוא דכל רעוין, והוא המתגלה בבעל תשובה ע\"י עומקא דליבא למעלה מכדי שתוכל נפשו שאת כו', ועז\"נ לפני ה' תטהרו, והוא ענין יוהכ\"פ יום שנתחייב בחמש תפילות וחמש כו' שנאמר בו וכפר על הקדש, והיינו ע\"י הכה\"ג שנכנס לקדה\"ק שלמעלה מבחי' קדש, עד שיש הבדלה בין קדש לקדה\"ק שמשם נמשך להיות וכפר על הקדש כו', בחי' קדש ישראל להוי' כו'.",[["85","19","<b>ועפ\"ז יובן עוד בענין יאשמו</b>: מכאן עד סוף הפיסקא הוא ע\"פ <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380643\" data-slug=\"likkutei-torah\" data-id=\"4001380643\">לקו\"ת פינחס שם פ, סע\"ד</a>."],["86","20","<b>כמ\"ש בגמ' ב\"מ בפרק הזהב ובהרמב\"ם הל' מעילה</b>: ב\"מ נד, א. רמב\"ם הל' מעילה פ\"א ה\"ה. הל' ערכין פ\"ד ה\"ה."],["87","21","<b>כמבואר במ\"א ע\"פ ומספר את רובע ישראל</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380593\" data-slug=\"likkutei-torah\" data-id=\"4001380593\">לקו\"ת בלק סח, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380596\" data-slug=\"likkutei-torah\" data-id=\"4001380596\">סט, ג</a> ואילך."],["88","22","<b>כמ\"ש במ\"א שהרצון עליון יש לו ב' בחי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370373\" data-slug=\"torah-or\" data-id=\"3901370373\">תו\"א פג, ד</a>. תו\"ח שמות תקכט, א [בהוצאה החדשה — שנח, א. שם הוא הנחת אדמו\"ר האמצעי ממאמר אדה\"ז]."]]],[2000460100,"<h3>והנה משנ\"ת כו' שהחומש זהו בחי' חמישית (ג)</h3>\n<b></b>חומש מלבר או מלגו כו' לבונה זכה כו' חולין עטה\"ק כו' ג' מיני ימים דק\"נ דמט\"ט דאצי'\nוהנה משנ\"ת<sup data-n=\"89\">1</sup> לעיל שהחומש זהו בחי' חמישית שהיא מכפרת על בחי' קדש ישראל שבחי' ישראל הוא ד' בחי', מחדו\"מ ורצון העליון, אבל החמישי' זהו רעדכ\"ר כנ\"ל, הנה זהו לפי מה שפסק הרמב\"ם ז\"ל כר' יאשי' בהזהב (ב\"מ דנ\"ד א'), אבל רש\"י פי' בפסוק זה ומאתים לנוטרי' את פריו, שמאתים הם חומשו של אלף, ולכן נראה שמפרש כר' יונתן, שר' יונתן אומר חומשו של קרן, והיינו חומש מלגאו, שעל אלף",[["89","1","<b>והנה משנ\"ת</b>: מאמר זה הוא המשך להמאמרים שלפנ\"ז, והוא מיוסד על ד\"ה ולהבדיל בין הקדש באוה\"ת שמיני ע' מט ואילך."]]],[2000460101,"צ\"ל ההוספה מאתים, דאילו לר' יאשי' צ\"ל ההוספה ר\"ן, ויש לפרש דעת רש\"י שסובר כת\"ק שבגמ' שבועות ששלמה זה חול, והוא ע\"ש שמברר ק\"נ דכתי' את זלע\"ז עשה האלקי' דכמו בקדושה יש ד' עולמות אבי\"ע כן גם בלעו\"ז יש ד' בחי' ק\"נ וג\"ק, וק\"נ היא כמו אצי' בקדושה, כ\"ה בלעו\"ז, ונודע כי בקדושה הוא עשר ולא תשע עשר ולא אחד עשר, אבל בסט\"א הם י\"א כתרין, והיינו מפני כי בקדושה החיות שמחי' הע\"ס הוא בפנימיותן, וכמ\"ש בת\"ז וההיא נביעא איהי כנשמתא לגופא דאיהו חיים לגופא, אבל בסט\"א אם הי' נמשך ג\"כ באופן זה הי' נבלע כמ\"ש בפ' תולדות בד\"ה ראה ריח בני ובהגהות לשם<sup data-n=\"90\">2</sup>, ולכן הם י\"א כתרין שבחי' המקיף דלבונה הוא נותן חיות בעשר כתרין, ועכ\"ז הנה הוא בבחי' מקיף על העשר כתרין די\"ס שלהן ואינו מתערב עמהן כו', ונודע כי בקדושה הי\"ס נחלקי' לחמשה פרצופים, א\"כ גם בלעו\"ז בי\"ס דנוגה ג\"כ צ\"ל שכן הוא, ומוסיף עליהם מקיף דלבונה זהו החומש מלגאו שהוא חלק ששית מלבר, והוא חומש כדברי ר' יונתן, חומשו של קרן.\n<b>והנה</b> בחי' לבונה זכה<sup data-n=\"91\">3</sup> היא ההבדלה שבין קדש לחול, והיינו שכמו בקדושה שמל' דאצי' נעשית עתיק לבריאה כנודע ממ\"ש במ\"א בענין מלך יחיד חי העולמי'<sup data-n=\"92\">4</sup> שבחי' מלך שבאצי' נעשה יחיד היינו בחי' עתיק בבריאה, ומ\"מ בחי' מל' דאצי' עצמה היא הפרוכת והפרסא שבין אצי' לבי\"ע, כן ממל' דעשייה נעשה ההבדלה שבין העשייה לק\"נ, שזהו הבדלה שבין קדש לחול, וזהו שנעשית עתיק לק\"נ<sup data-n=\"93\">5</sup>, וי\"ל שזהו המקיף דלבונה זכה שבי\"א סממני הקטרת שיש פי' שזהו מה שמל' דעשייה נעשית עתיק לק\"נ, ולכן ע\"י י\"א סממני הקטרת שמבררי' בחי' אחד עשר כתרין דסט\"א עי\"ז נמשך תוס' אור בקדושה מבחי' חד ולא בחושבן בחי' עתיק יומין כתר דאצי' בבחי' עשר תיקונין שהם ע\"ס דאצי' כמ\"ש בהגהות לד\"ה ראה ריח בני, והגם כי שם מובן שהבירור הוא<sup data-n=\"94\">6</sup> ממה שנבלע בפנימיותן שזהו מה שפנימיותן הוא רע, משא\"כ מקיף דלבונה הוא מבחי' קדושה עדיין רק שמחבר ע\"ס דעשיי' עם עשר כתרין דנוגה, מ\"מ י\"ל שהבירור הוא ע\"י המקיף דלבונה דוקא וכמו שרצה יצחק לפעול ע\"י המקיף, ואם כי טעה בזה שמעצמו א\"י להתברר כמש\"ש, כ\"א ע\"י יעקב ז\"א דאצי' דוקא מ\"מ בירור דיעקב ז\"א דאצי' ג\"כ מברר ע\"י המקיף דלבונה שהוא הנותן חיות בע\"ס דנוגה וע\"י מבררי' גם הנצוצות שנפלו בשה\"כ בע\"ס דנוגה בפנימיותן היינו מה שנבלע בהם להיות חיל בלע כו' ומבטנו יורישנו כו' היינו מה שנבלע בפנימיותן, רק כ\"ז הוא ע\"י המקיף דלבונה שהוא החיות דע\"ס.",[["90","2","<b>כמ\"ש בפ' תולדות בד\"ה ראה ריח בני ובהגהות לשם</b>: ראה לעיל רד\"ה כרמי כו' האלף לך שלמה. וש\"נ. לקמן ד\"ה ראה ריח בני. וש\"נ."],["91","3","<b>והנה בחי' לבונה זכה</b>: מכאן עד סוף המאמר נמצא ג\"כ לקמן בתוך ד\"ה ויירא ויאמר גו' (ושם כמה פיסקאות הם באריכות יותר)."],["92","4","<b>כנודע ממ\"ש במ\"א בענין מלך יחיד חי העולמים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370183\" data-slug=\"torah-or\" data-id=\"3901370183\">תו\"א מקץ מ, ג</a>. מא, ב. סה\"מ תרכ\"ז ע' יח וע' ע. ובכ\"מ."],["93","5","<b>וזהו שנעשית עתיק לק\"נ</b>: לקמן בד\"ה ויירא ויאמר גו' הלשון כאן: והוא ע\"י שממל' דמל' דעשי' נעשה ההבדלה שבין העשי' לק\"נ."],["94","6","<b>והגם כי שם מובן שהבירור הוא</b>: בד\"ה ויירא ויאמר גו' שם: והגם כי משם מובן שעיקר הבירור הוא."]]],[2000460102,"<b>והנה</b> לפ\"ז המבדיל בין קדש לקדש זהו אפי' ההבדלה שבין יצירה לעשייה ג\"כ, רק ההבדלה שבין עשייה לק\"נ זהו ההבדלה שבין קדש לחול ולמעלה מבחי' הבדלה זו הכל הם בחי' ההבדלות שבין קדש לקדש כו'.\n<b>והנה</b> בזח\"ג פ' אמור<sup data-n=\"95\">7</sup> דף צ\"ד ע\"ב פי' פסוק כי ששת ימים עשה ה' את השמי' ואת כו', נ\"ב (והוא מהרח\"ו), ו\"ק דז\"א דאצי', אי הכי אמאי אקרון ששת ימי החול אמאי חול, א\"ר יוסי השתא אתנהיג עלמא ע\"י דשלוחייהו בגין כך ימי חול אקרון, ונ\"ב שהוא מט\"ט ו\"ק דיצי' ששת ימי החול, עכ\"ל, וע' בפרד\"ס שער אבי\"ע פרק ה ע\"פ שער חצר הפנימית הפונה קדים סגור יהי' ששת ימי המעשה כו', חולין שנעשו על טהרת הקדש להמשיך ו\"ק דאצי' שיתלבשו במט\"ט<sup data-n=\"96\">8</sup>, והגם שהמק\"מ פי' שם על מ\"ש בשם הרח\"ו השתא אתנהיג עלמא ע\"י דשלוחייהו, שהוא מט\"ט ו\"ק דיצי', שזהו כמ\"ש הרב שבששת ימי החול יום א' דאצי' מתלבש בחסד דבריאה, וחסד דבריאה בחסד דיצירה ומשפיע באח\"פ<sup data-n=\"97\">9</sup>, ובח\"ל מתלבש חסד דיצי' בחסד דעשייה ומשפיע לח\"ל, לפי שאח\"פ יונקת מיצי' וח\"ל מעשייה וז\"ש ע\"י דשלוחייהו ולכן נק' חול עכ\"ל. כוונתו דשלוחייהו ל' רבי' היינו מט\"ט וסנדל שהם ו\"ק דיצי' וו\"ק דעשייה, א\"כ כ' לשון שמתלבש על יומין דחול, והיינו שהגם שיום א' דאצי' מתלבש בבי\"ע עכ\"ז חול הוא, ולפי פי' הפרדס כשממשיכין ו\"ק דאצי' שיתלבשו במט\"ט ו\"ק דיצי' ה\"ז חולין שנעשו ע\"ט הקדש, אמנם באמת י\"ל שיש כמה מיני התלבשות, אם העלם גמור, או גילוי, או דרך מעביר.\n<b>ויש</b> להעיר לענין חול, וחולין, ממ\"ש גבי נדרים לא יחל דברו, ושרש ענין הנדרים בקצרה<sup data-n=\"98\">10</sup> שנדרים סיג לפרישות, והיינו מפני כי לא יכול להעלות הניצוץ שבדבר הנדור, ע\"כ ההכרח לדחותן, ואוסר ע\"ע הדבר הנדור בנדר, ונודע כי הנדרים הם מבינה ששם הו\"ע הנדרים, וזהו שארז\"ל כל הנודר כאלו נודר בחיי המלך, מלך הוא ז\"א וחיי המלך הוא מבינה, בחי' אלקי' חיים ומלך עולם כו' כמ\"ש במ\"א<sup data-n=\"99\">11</sup>, וכשמקבל עליו בנדר, ע\"ז בא האזהרה שלא יחל דברו הוא דבר הנדר, כי ע\"י דבורו ממשיך על דבר הנדור מקיף דקדושה, דוגמת מקיף דלבונה זכה שאין קדש מתערב בחול, אמנם החכם שמתיר הנדר מיחל דברו שאסר ע\"ע ומתיר לו נדרו, והיינו מפני כי בחכ' אתברירו, ויכול לברר ולהעלות הניצוץ, ולדחות הרע, ואז החולין הם חולין שנעשו על טהרת הקדש, נמצא להוסיף מחול על הקדש, היינו לברר ולהעלות הניצוץ שהי' בדבר הנדור, זהו ע\"י בחכמה אתברירו, וזהו שא\"ל שמואל לרב יהודה (בפ\"ה דערובין דנ\"ד ע\"א) שיננא חטוף ואכול חטוף ואישתי דעלמא כו' כהילולא דמי, פי'",[["95","7","<b>והנה בזח\"ג פ' אמור</b>: הבא לקמן עד סוף המאמר מיוסד על אוה\"ת שמיני שם ע' נ."],["96","8","<b>להמשיך ו\"ק דאצי' שיתלבשו במט\"ט</b>: שם נוסף: כמ\"ש מזה במ\"א."],["97","9","<b>באח\"פ</b>: בארץ חפץ [ארץ ישראל]."],["98","10","<b>ושרש ענין הנדרים בקצרה</b>: ראה בארוכה לקמן ד\"ה וידבר גו' המטות. וש\"נ."],["99","11","<b>כאלו נודר בחיי המלך. . כמ\"ש במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316610223\" data-slug=\"or-hatorah-hb\" data-id=\"8316610223\">אוה\"ת</a> מטות ע' א'שכו ואילך. וראה אוה\"ת ויצא (כרך ד) תתנב, א ואילך. סה\"מ תרל\"ג ס\"ע תלה ואילך. ובכ\"מ. [ובהנסמן בהע' שלפנ\"ז]."]]],[2000460103,"ר\"ל שלא יאכל לתיאבון וישאר הניצוץ מקושר בק\"נ כמקדם אלא יחטוף אותו מק\"נ, והיינו ע\"י היותו שיננא, ובחכמה אתברירו כנ\"ל, ובערוך ערך שן הב' פי' שיננא מחודד בתלמוד מלשון חץ שנון עכ\"ל, ואפ\"ל שלכן רב יהודה כולא תנויי בנזקין הוה, בכדי לחטוף הנצוצות מד' אבות נזיקין, וכן ד\"מ הם בסדר נזיקין שהרוצה שיחכם יעסוק בדיני ממונות, וע\"י היותו מחכים הנה בחכמה אתברירו להציל העשוק מיד עושקו שזהו עיקר ענין דיני ממונות, שזהו מה שנק' סדר נזיקין ישועות כמ\"ש במ\"א<sup data-n=\"100\">12</sup>, ולכן א\"ל חטוף כו', משא\"כ ע\"ה אסור לאכול בשר לפי שאינו יכול לחוטפו מק\"נ כו', ולכן על שבת ארז\"ל במכילתא ע\"פ זכור את יוה\"ש, הובא בילקוט ע\"פ הנ\"ל זכור מלפניו ושמור מלאחריו משל לזאב שטורף מלפניו ומלאחריו, וטריפתו זהו שחוטף שה מהעדר, והיינו כי שבת הוא בחי' מוחין דאבא, ולכן צריכין להוסיף בו מחול על הקדש מלפניו ומלאחריו, כזאב שחוטף בשר הבהמה כן צריכי' לחטוף מן החול ולהוסיף בבחי' קדש דשבת, כי בחכמה דוקא אתברירו לחטוף מן החול שיוכלל בבחי' הקדש דשבת כו', וכמו החכם שמיחל הדבור ומתיר הנדר שהניצוץ שהי' בו יתעלה כו' מחול לקדש להיות בחי' חולין שנעשו על טהרת הקדש כו'. וגם י\"ל חול, חולין הוא ע\"ד דכתי' במשה ויחל משה, וארז\"ל ברבות פ' תשא פמ\"ג שעשה מהמר מתוק, כי ויחל פירושו ג\"כ לשון מתיקות, והיינו שכאשר בחכמה אתברירו מתגלה המתיקות ותענוג עליון שנפל בשבה\"כ ויוצא מק\"נ, וי\"ל שבשבת ע\"י זכור מלפניו ושמור מלאחריו עי\"ז נמשך תוס' בחי' תענוג עליון בסעודות דשבת, בחי' אז תתענג כו', וקראת לשבת ענג, ע\"י שחוטף מהחול כו'.\n<b>ועדיין</b> צ\"ל מה שלפעמי' משמע שששת ימי החול הם במט\"ט כמשנ\"ת לעיל ממאמר הזהר פ' אמור דצ\"ד ע\"ב, ולפעמים משמע שששת ימי החול הם מק\"נ, כמשנ\"ת לעיל שההבדלה שבין קדש לחול זהו בין עשייה לק\"נ, והוא מהזהר פ' פקודי דרכ\"ז הנ\"ל ולכאו' איך יתכן שניהם, ובאמת פי' שני מאמרי הזהר אלו הם בשם נ\"ב שהוא מהרח\"ו ז\"ל. אך הענין יובן ע\"פ מ\"ש בר\"ח שער הקדושה פ\"ב, אשר ביאר ע\"פ מאה\"ז פ' ויקהל דף ר\"ד ע\"א, ת\"ח אית ימים ואית ימים, ימי חול כמה דאתמר, ואלין קיימין לבר כו', ימי השבת דאינון ימי השבוע קיימין לישראל, וכוונתו שהם שלשה מיני ימים, האחד ימי חול דקיימין לבר, היינו שהם עומדים חוץ לקדושה, (וזהו אלף ימי' דחול שנת' בזח\"ב פקודי דרכ\"ז ע\"ב, והיינו כמו שפי' המק\"מ שם בשם נ\"ב שזהו ע\"ס דנוגה), והשליט על ישראל הנהגת קדושה ע\"י מט\"ט כו' וששת ימי החול ההנהגה ע\"י מט\"ט כו' דאיהו עבד דשליט בשיתא סדרי משנה כו', (וזהו ששת ימי החול דאתנהיג עלמא ע\"י דשלוחייהו שא' ר' יוסי בזח\"ג אמור דצ\"ד ע\"ב, שנת' לעיל שזהו בחי' ו\"ק דיצי' וגם ו\"ק דעשיי', שהם מט\"ט וסנדל כנ\"ל), אמנם בשבת שולט אור האצי' כו' והעוסקים בתומ\"צ הם קושרים בימי החול ו\"ק של שש היכלות (היינו היכלות דיצי', ואפשר גם דעשיי') בששה ספירות הבנין שבאצי'",[["100","12","<b>שזהו מה שנק' סדר נזיקין ישועות כמ\"ש במ\"א</b>: ראה אוה\"ת דרושים לשבועות ע' עג ואילך וע' פ' ואילך. סה\"מ תרכ\"ז ע' תצו ואילך (הוצאת תש\"ס). ועוד."]]],[2000460104,"שהם ששת ימי' עשה ה' את השמים ואת הארץ (שהם מחסד דאצי' עד יסוד שהם פעלו כל מעשה בראשית כדפי' בזהר פ' בראשית, כי ששת ימי' עשה בששה לא נאמר כו'), והיינו ע\"י כוונת התפילה, כמבואר בזהר פ' פקודי שע\"י כוונת ברכת ק\"ש ותפלת י\"ח מתקשרים ומאירים ההיכלות מאור האצילות, ובזה אנו מפרידים הטוב מהרע, והטוב מתקדש באור הטוב שבאצי' ובזה הם נשמרים מהרע, ע\"כ דברי הר\"ח.\n<b>ועפ\"ז</b> יובן מארז\"ל מט\"ט קושר כתרים<sup data-n=\"101\">13</sup> לקונו מתפילותיהם של ישראל, ופעם אמרו סנדל קושר כתרים (ע' בלק\"ת שה\"ש בד\"ה מה יפו<sup data-n=\"102\">14</sup> פעמי' בנעלים), שההפרש בין מט\"ט ובין סנדל זהו אם ההעלאה הוא ע\"י ההנהגה הנמשך מיצי', או אם ההעלאה הוא ע\"י שבח\"ל נמשך ההנהגה ע\"י ו\"ק דעשייה כנ\"ל, והם מעלים התפילות, שהוא הטוב הנז' לעיל שנפרד מהרע, והיינו כי האדם ניזן ממאכלים הגשמי' שגידולם וצמיחתם הוא מנוגה, שבה מעורב טו\"ר, וכאשר בכח האכילה לומד תורה ומקיים מצות, ומתפלל ק\"ש ושמ\"ע, ונודע כי עליית תומ\"צ של האדם מתעלים ע\"י התפילה, והמלאכי' הנ\"ל שמעלים התפילות הם קושרי' כתרים לקונו מאבנים טובות שהם האותיות שבתפילה שמאירים מאור ההתבוננות כו'. וענין קושר כתרים, לפי שמה שנפל בשה\"כ זהו מה שצריכי' לברר מיו\"ד כתרין דנוגה, וכנז' בתחילת הקונטרס<sup data-n=\"103\">15</sup> שמקבלים מאלף כו' כתר כו', לכן הטוב שמתעלה עושי' מזה כתרים כו'.\n<b>ונחזור</b> לעניננו, שז\"ע ג' מיני ימים היינו ימי החול דק\"נ, וימי החול דמט\"ט, וששת ימים דאצי', ובשבת שולט מל' דאצי' ומקבלת מהבינה שהיא נק' שביעאה כו', והשראתה בהיכל ק\"ק דבריאה שלמעלה ממט\"ט כו', וי\"ל התקשרות ו\"ק דמט\"ט בו\"ק דאצי' הוא ע\"י שיתא סדרי משנה, וזהו ששת ימים תעבוד כו'. ומכ\"ז יובן המכילתא זכור מלפניו ושמור מלאחריו מכאן שמוסיפין מחול על הקדש, כמו הזאב (שטורף) שחוטף מלפניו ומאחריו, היינו שחוטף מגבול ימי החול דק\"נ כי מברר ק\"נ ומפריד בין טוב לרע ע\"י עסק התורה, ואז מתקשר ומתעלה עד ו\"ק דאצי' כו', וע' במק\"מ ויקהל דר\"ד א' ג\"כ מזה, אך פי' הר\"ח מכוון יותר<sup data-n=\"e8\">*</sup>.",[["101","13","<b>מארז\"ל מט\"ט קושר כתרים</b>: ראה גם סה\"מ תרל\"ג ח\"א ע' ב. וש\"נ."],["102","14","<b>ע' בלק\"ת שה\"ש בד\"ה מה יפו</b>: מג, ג ואילך."],["103","15","<b>וכנז' בתחילת הקונטרס</b>: תחילת המשך זה לעיל ד\"ה כרמי כו' האלף לך שלמה."],["e8","*","<b>בשולי העמוד נרשם בגוכי\"ק</b>:\nבס' ויקרא, דט\"ל א' מפרש חזיר ק\"נ פנימיותה לתאוות גשמי', רק עורף לקדושה אחוריו, וביהודה ידך בעורף מד\"ר תולדות פס\"ה שהרג כו', כל גוים סבבוני תרגום מחזרין, י\"ל מקיפי' דק\"נ, מפריס פרסה רמאות איך מעשרין כו', ע\"ד דק\"נ מפתה לאתתא ואינו מעלה גרה כדפי' במד\"ר שמיני פי\"ג, ולכן מה שמפריס פרסה זה לרע לו ע\"ד לא זכה נעשי' לו התורה כו'."]]],[2000460105,"<h3>ולהבין כו' ג' בחי' ימים כו' (ד)</h3>\n<b>בס\"ד.</b>\nולהבין בתוס' ביאור<sup data-n=\"104\">1</sup> שרש ענין ההפרש בין ג' בחי' ימי' שנת' בדברי הר\"ח ז\"ל בביאור מאה\"ז ויקהל דר\"ד הנ\"ל, דאית ימים דקיימין לבר ואית ימים שהם ימי השבת דאינון ימי השבוע דקיימין כו', ז\"ל הר\"ח הנ\"ל בדף קמ\"ט ע\"א, הכוונה כי לאומות עע\"א להם נתן ל\"ט מלאכות שהם כנגד ל\"ט קללות שנתקללו אדם וחוה ונחש והארץ כדפי' ז\"ל, והאדם אלו לא חטא לא הי' צריך לרדת אל הפחיתות הזה שהוא בו שיצטרך לחרוש ולזרוע, והי' בג\"ע מקיים לעבדה ולשמרה בקיום המצות עשה ול\"ת בדרך רוחני, כמו שיהי' לעתיד אחר התחייה שהתורה היא ומצוותיה אחד לעולם, וכאשר ירד אדם בחטאו אל הקליפה (י\"ל ע\"ד שנת' בת\"א בשם האריז\"ל שאדה\"ר<sup data-n=\"105\">2</sup> הי' הולך בהיכלות כי בחי' אדם הוא למעלה כו' שהי' בערך אחר ממש שהרי הי' יציר כפיו של הקב\"ה, ובהיכלות הטומאה לא רצה להביט כלל, והשיאו הנחש שעכ\"פ יביט מה יש בהם, ועי\"ז נכשל ונפל בתאוה אליהן עכ\"ל), הוכרח אל המלאכות האלו, והקב\"ה לטהרנו ולקדשנו כדי שנהי' דבוקים בו העלנו מששה ימים החיצונים והשליט על ישראל הנהגת קדושה ע\"י מט\"ט שהוא שר העולם, (וע' בפרד\"ס שער אבי\"ע מענין מט\"ט שר הפנים, שהוא חנוך שנא' בו ויתהלך חנוך את האלקי' כו'), וכמו שנא' ליהושע (יהושע ה' י\"ד) אני שר צבא ה' עתה באתי, שאע\"פ שמרע\"ה דחהו הוא הוכרח לקבלו, וכ\"ש עתה כו' שההנהגה ע\"י, כדפי' בתיקוני' דצ\"ג וברע\"מ פנחס דרמ\"ג ע\"ב, עכ\"ל.\n<b>והנה</b> לפ\"ז צ\"ל<sup data-n=\"106\">3</sup> מארז\"ל במשנה דאבות שמעי' אומר אהוב את המלאכה כו', וכן ארז\"ל (ברכות דף ח' ע\"א) גדול הנהנה מיגיעו יותר מירא שמים דאילו גבי יר\"ש כתי' אשרי איש ירא את ה' (תילי' קי\"ב) ואלו גבי נהנה מיגיעו כתי' יגיע כפיך כו' אשריך וטוב לך (שם קך\"ח) אשריך בעוה\"ז וטוב לך לעוה\"ב, ולגבי יר\"ש וטוב לך לא כתי' ביה, וכן ארז\"ל ברבות ויצא פע\"ד ע\"פ את עניי ואת יגיע כפי, ר' ירמי' א' חביבה היא המלאכה מזכות אבות, שזכות אבות הצילה ממון, ומלאכה הצילה נפשות כו', וצ\"ל מהו מעלת המלאכה כ\"כ עד שחביבה כ\"כ יותר מזכות אבות, וגדול מיר\"ש, שזהו לכאו' פלא, וכ\"ש לפי משנ\"ת לעיל בענין ל\"ט מלאכות, יגדל הפלא ופלא יותר.\n<b>אך</b> הענין הוא דכתי' ואני אתנהלה לאטי לרגל המלאכה ולרגל הילדי' עד כו' ופי' בזח\"א דקע\"ב א' ולרגל הילדים דא הוא רזא דכרובים, ופי' המק\"מ רזא דכרובי' פי' מט\"ט וסנדל, והנה באמת לא מצינו שהלך יעקב לשעיר, אלא דקאי על מ\"ש",[["104","1","<b>ולהבין בתוס' ביאור</b>: מאמר זה הוא המשך להמאמרים שלפנ\"ז. לכללות המאמר ראה בהנסמן להלן בפיסקא: והנה לפ\"ז."],["105","2","<b>בת\"א בשם האריז\"ל שאדה\"ר</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370022\" data-slug=\"torah-or\" data-id=\"3901370022\">תו\"א בראשית ו, א</a>. [וע\"ש בהמ\"מ בסוף הספר]."],["106","3","<b>והנה לפ\"ז צ\"ל</b>: בכל הבא להלן — ראה גם ד\"ה אבות מלאכות, בסה\"מ תר\"ל ע' רמב ואילך. ד\"ה ויקח ה\"א בסה\"מ תרל\"א (נמצא בדפוס)."]]],[2000460106,"ועלו מושיעי' כו', וא\"כ לפ\"ז מובן שמה שאמר לו לרגל המלאכה קאי על כל אריכות זה\"ג שנק' בשם מלאכה, שלכאו' צ\"ל מפני מה יקרא בשם מלאכה, והענין הוא דמצינו בדרז\"ל במד\"ר ס\"פ י\"א ע\"פ כי בו שבת מכל מלאכתו, ממלאכת עולמו שבת, ולא שבת לא ממלאכת הרשעים ולא ממלאכת הצדיקים, אלא פועל עם אלו ועם אלו, ומביא מקראות ששניהם קרוים מלאכה, ולכאו' גם בזה צ\"ל מהו המלאכה, וגם מה שייך מלאכה זו לשבת, ואם מלאכה היא זו איך הותרה לעשות בשבת, הלא מה שהוא עושה הוא אומר לישראל לעשות כמ\"ש ברבות פ' משפטים ע\"פ מגיד דבריו ליעקב, וכשאסר עלינו בתורה כל המלאכות הנה השבת היא שביתה גמורה, ואיך עושה זאת בשבת (אם לא שנא' שמלאכה כזו אם הי' בחיק הנברא לפעול כזאת ג\"כ לא הי' נאסרת<sup data-n=\"107\">4</sup>).",[["107","4","<b>הי' נאסרת)</b>: ע\"כ נמצא בגוכי\"ק. — וראה המשך הענין בדרושים שנסמנו בהערה שלפנ\"ז."]]],[2000460107,"<h3>ראה ריח בני כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ תולדות, ט\"ל).</b>\n<b></b>רישא דעשו בעטפוי דיצחק כו' יו\"ד י\"א כו' טעם בריאת הקליפות כו' ברכות עשו כו' ריח\nתולדות\n<b>ראה</b> ריח בני<sup data-n=\"108\">1</sup> כריח שדה אשר ברכו ה', ויתן לך האלקי' מטל השמים כו', הנה יש כאן עשרה ברכות, כנגד עשרה מאמרות, וזהו שהברכות אלו הוא מעין עש\"מ מטל השמים ומשמני הארץ שהוא ענין יהי רקיע ותדשא הארץ כו', ובזה יובן מה שנא' ויתן לך האלקי' ולא נא' שם הוי', כי כל הברכות נמשך משם הוי' וכמ\"ש יברכך ה' מציון, יברכך ה' וישמרך, אלא לפי שהברכות אלו הוא כנגד עש\"מ, ובעש\"מ נא' שם אלקים וכמ\"ש בראשית ברא אלקי', ולזה נא' כאן שם אלקים, והנה בעש\"מ נא' אח\"כ ש' הוי' וכמ\"ש ביום עשות הוי' אלקי' ארץ ושמים, ששיתף שם הוי' בשם אלקים, לכך גם בברכות אלו נא' ג\"כ שם הוי' וכמ\"ש כריח שדה אשר ברכו ה'.\n<b>והנה</b> להבין ענין הברכות אלו<sup data-n=\"109\">2</sup> י\"ל מתחלה מה שיצחק הי' סבור שהוא עשו ורצה לברך את עשו דוקא, וגם י\"ל מה שפעם משמע שעשו הי' מרמה את יצחק",[["108","1","<b>ראה ריח בני</b>: מאמר זה מיוסד על ד\"ה זה ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370094\" data-slug=\"torah-or\" data-id=\"3901370094\">תו\"א תולדות כ, ב</a> ואילך [וע\"ש בהמ\"מ]. וד\"ה זה באוה\"ת תולדות קנו, א ואילך. וראה גם אוה\"ת תולדות שם קנא, ב ואילך. כרך ד' תתכט, ב ואילך. וראה תוכן המאמר בתוס' ביאורים כו': ד\"ה ויתן לך בסה\"מ תרנ\"ד ע' סה. תרפ\"ד ע' קג-קח. ד\"ה יפה שעה בסה\"מ תרפ\"ו ע' קעח. ד\"ה ויתן לך וד\"ה פתח אליהו בסה\"מ תש\"ב ע' 66 וע' 77. ד\"ה ויתן לך תשכ\"ח בסה\"מ מלוקט ח\"ד ע' סג.\nהמאמר נמצא ג\"כ בכת\"י 1063 עז, א [נק' בוך בראשית שמות ויקרא, וכולל הנחות ממאמרי אדמו\"ר הצ\"צ]. וכאן הוא בתוס' תיקונים והגהות בגוכי\"ק אדמו\"ר מהר\"ש.\nראה לקמן בהוספות, מאמר זה בהנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע [ומתחיל: ויתן לך]. וחלק השני במאמר שם (מע' קפא ואילך) הוא ענין נוסף שלא נרשם במאמר כאן."],["109","2","<b>והנה להבין ענין הברכות אלו</b>: בהבא לקמן (בפיסקא זו) ראה תו\"א תולדות שם (ושאר מקומות שנסמנו לעיל בתחילת המאמר)."]]],[2000460108,"ויצחק הי' סבור שהוא צדיק וכמ\"ש כי ציד בפיו ופרש\"י שהי' צד ומרמה אותו והי' שואל איך מעשרין את המלח ואת התבן והי' סבור יצחק שהוא מדקדק במצות, ופעם משמע להיפך שיצחק הי' יודע שאין ש\"ש שגור בפיו, וכמו שפרש\"י ע\"פ גשה נא ואמושך אמר יצחק בלבו אין דרך עשו להיות ש\"ש שגור בפיו, נמצא שיצחק ידע כו'. אך הענין הוא דהנה איתא בזהר שרישי' דעשו בעטפי' דיצחק דהנה יצחק הוא בחי' ומדרגת מעלת הזהב על הכסף, כסף הוא בחי' אהבה מלשון נכסוף נכספתי כו' שהוא מדריגת אברהם שהוא בחי' חסד גוון לבן, ויצחק הוא בחי' זהב בחי' גבורות קדושות שמעלת הזהב על הכסף, ועשו הוא סוספיתא דדהבא פסולת הגבורות דיצחק שמפסולת שלו יצא עשו ורישא דעשו בעטפי' דיצחק.\n<b>ולהבין</b> ענין רישא, הנה המשכן הי' מעשר יריעות, ועל המשכן הי' אחד עשר יריעות עיזים וכן הי' י\"א סממני הקטרת וכמשארז\"ל ואחד עשר סממנים היו בה, שהם כנגד י\"א כתרין דמסאבותא, ולכאורה אינו מובן שהרי בקדושה אינו כ\"א ע\"ס וכמ\"ש בת\"ז אנת הוא דאפיקת עשר תיקונין וכן איתא בס\"י ע\"ס בלי מה עשר ולא תשע עשר ולא אחד עשר שהם עשר דוקא, וזהו שבתורה נמצא הכל על חשבון עשר, עש\"מ, עשה\"ד, עשרה עשרה הכף שהם כנגד ע\"ס כו'<sup data-n=\"110\">3</sup>, ולמה בקטרת וביריעו' עיזים הם אחד עשר.\n<b>אך</b> הענין הוא דהנה איתא בת\"ז אנת הוא חד ולא בחושבן<sup data-n=\"111\">4</sup> ופי' ולא בחושבן היינו שאינו בגדר חשבון כלל, כי חשבון הוא כמו למשל שא' לגבי אלף הוא כמו אלף לגבי אלף אלפי' שזהו הכל בגדר חשבון אבל אנת הוא חד ולא בחושבן שאין ערוך אליו כלל, אנת הוא דאפיקת עשר תיקונין, והנה איתא בזהר הובא בעה\"ק ח\"א פ\"ד שהוא אינון ואינון הוא שכלא חד, ולכאורה אינו מובן א\"כ האיך הם במנין עשר שהרי אא\"ס אחד ומיוחד. אך הענין הוא דהנה אא\"ס הוא בחי' בלי גבול ותכלית וכמ\"ש אנת הוא חד ולא בחושבן, וכדי שיהי' מקור לעולמות בע\"ג הוצרך לצמצם בעצמו שיהי' מקור לעולמות בע\"ג שזהו הכח של אא\"ס לצמצם בעצמו שיהי' מקור לגבול לפי שהוא כל יכול ואנת שלימותא דכלא, וכמו שהוא בלי גבול, כמ\"כ יכול לצמצם א\"ע שיהי' מקור לגבול, והנה ענין הצמצום הזה זהו ענין מה שנמשך בחי' ע\"ס שהם בחי' שרש ומקור להיות אח\"כ בחי' עולמות בע\"ג ותכלית. והנה לפי שהם מקור לעולמות שהם בחי' ציור אדם ובאדם יש עשר בחי' ג' מוחין וז' מדות, לכך גם שרשן ומקורן נק' ג\"כ בחי' אדם וכמ\"ש ועל הכסא דמות כמראה אדם שהוא ענין ע\"ס, ומ\"מ הוא אינון ואינון הוא לפי שבאמת הוא כולא חד לפי שזהו הכח מאא\"ס עצמו שצמצם א\"ע בבחי' כמראה אדם כו', והנה בחי' זו נק' בחי' שם וכמ\"ש עד שלא נבה\"ע הי' הוא ושמו לבד, שמו הוא בחי' הכח שיש באא\"ס להתצמצם להיות",[["110","3","<b>ע\"ס כו'</b>: בכת\"י המעתיק כאן: ע\"ס ס\"י. ותוקן כאן בפנים ע\"פ כת\"י 1063."],["111","4","<b>אך הענין הוא דהנה איתא בת\"ז אנת הוא חד ולא בחושבן</b>: להבא להלן (בפיסקא זו) ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370061\" data-slug=\"torah-or\" data-id=\"3901370061\">תו\"א וירא יג, ג</a> ואילך."]]],[2000460109,"מקור לעולמות בע\"ג, וזהו שיש עשר שמות הגם שרק ז' שמות שאינן נמחקי' אעפ\"כ יש עשר שמות שהם בחי' ע\"ס<sup data-n=\"112\">5</sup> כו'.\n<b>והנה</b> כמו שיש ע\"ס בקדושה כמ\"כ יש בלעו\"ז בקליפה אהבה רעה וכמ\"ש ולא תתורו אחרי לבבכם כו' אשר אתם זונים אחריהם, וכן יש חכ' בלעו\"ז וכמ\"ש חכמים המה להרע כו', וכן בתענוג יש ג\"כ בלעו\"ז תענוג מדברים האסורי', שזהו ענין חלב שחלב הוא בחי' תענוג רק שהוא בחי' תענוג מדברים האסורים, ולכן על חלב חייב כרת שכרת הוא לעו\"ז נגד בחי' כתר ענג העליון, וזהו שברך יצחק ומשמני הארץ שהמ\"ם מקטין הענין דהיינו רק מקצת שמני ארץ ששומן הוא ג\"כ בחי' תענוג רק שהוא בחי' תענוג מדברי' המותרי' ולזה אמר משמני הארץ ולא כל השמני דהיינו למעט את בחי' חלב שהוא ג\"כ שומן לפי שהוא תענוג מדברים האסורי' אלא משמני דהיינו רק בחי' תענוג מדברי' המותרים יתענג להיות אז תתענג על הוי' וקראת לשבת ענג כו'.\n<b>אך</b> בקדושה הם עשר ולא תשע עשר ולא אחד עשר ובקליפה הם י\"א סממני הקטרת<sup data-n=\"113\">6</sup>, והענין כי ע\"י החיות שנמשך בקדושה הנה כתי' וצבא השמים לך משתחוי' שהם בטלי' מחמת שמשיגי' החיות שנמשך עליהם מקדושתו ית' משא\"כ הקליפות הם מגביהי' א\"ע כנשר בחוצפא, והיינו לפי שהחיות הנמשך אצלם הוא בסוד גלות, לפיכך הגם שנמשך עליהם חיות מקדושה אינם בטלים ואדרבה מגביהי' א\"ע כנשר כו', והחיות הנמשך להם הוא נבלע בתוכם.\n<b>אך</b> כיצד הם חיים וקיימים מהקדושה מאחר שהחיות נבלע בתוכם הנה זהו ענין לבונה שבי\"א סממני הקטרת שהוא אור המקיף עליהם מלמעלה ואינו נבלע בתוכם, וזהו לבונה זכה, זכה הוא בחי' ך\"ז אותיות<sup data-n=\"114\">7</sup> דהיינו שיש בחי' אותיות שהם מחיים רק בבחי' מקיף ע\"ד השבעת השמות כו', ולפי שהוא אור המקיף עליהם מלמעלה הם מתגאי' ומגביהי' א\"ע בחוצפא, ובחי' לבונה היא המחבר י\"ס דקדושה להאיר לע\"ס דמסאבותא והוא רישא דעשו דהיינו בחי' המקיף מלמעלה הוא נכלל בעטפי דיצחק ממש, ולכן מצד בחי' המקיף עשו שואל איך מעשרין את התבן ומצד הפנימי' אין ש\"ש שגור בפיו. והנה ע\"י סממני הקטרת מבררין את בחי' י\"א כתרין דמסאבותא, ועי\"ז שמבררי' אותם עי\"ז ממשיכי' שיהי' נמשך בחי' אנת הוא חד ולא בחושבן בבחי' ע\"ס כו'.",[["112","5","<b>עשר שמות שהם בחי' ע\"ס</b>: ראה גם לקו\"ת בחוקותי (הוספות) נא, ג. דרמ\"צ קטו, ב. סה\"מ תרל\"ב ח\"ב ע' תקד. תקסט."],["113","6","<b>אך בקדושה הם עשר. . ובקליפה הם י\"א סממני הקטרת</b>: ראה בכ\"ז גם (בנוסף להנסמן לעיל בתחילת המאמר): <a class=\"ft-cite\" href=\"#/read/torah-or/3901370020\" data-slug=\"torah-or\" data-id=\"3901370020\">תו\"א בראשית ה, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381159\" data-slug=\"likkutei-torah\" data-id=\"4001381159\">לקו\"ת שה\"ש ז, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381170\" data-slug=\"likkutei-torah\" data-id=\"4001381170\">י, ב</a>. מאמרי אדהאמ\"צ דברים ח\"ג ע' א'קטז (ובהמ\"מ שם). סה\"מ תרכ\"ז ע' שע. תרל\"ב ח\"א ע' קנו. שיא ואילך. ח\"ב ע' תקנ. תקעט. תקפג. תרלה. ובכ\"מ."],["114","7","<b>וזהו לבונה זכה. . בחי' ך\"ז אותיות</b>: ראה אוה\"ת וארא (כרך ז) ע' ב'תקסח."]]],[2000460110,"<b>אך</b> לכאורה י\"ל מאחר שהקליפות פנימיותם רע והעבודה לברר אותם למה נבראו כלל ויותר הי' טוב שלא לבראותם כלל ולא הי' צריכין לברר אותם כו', ועד\"ז י\"ל מארז\"ל שהמלאכי' בקשו את התורה תנה הודך על השמים, והשיב להם כלום יצה\"ר יש ביניכם, שמשמע מזה שעיקר התורה הוא כדי לברר את יצה\"ר דוקא, וגם זה אינו מובן למה נברא היצה\"ר.\n<b>אך</b> הענין הוא דהנה כתי' לויתן זה יצרת לשחק בו<sup data-n=\"115\">8</sup> וארז\"ל ג' שעות ראשונות הקדב\"ה יושב ועוסק בתורה שניות יושב ודן שלישית יושב וזן רביעית יושב ומשחק עם לויתן, שזהו בזמן תפלת המנחה, ויצחק תקן תפלת המנחה, וי\"ל מהו ענין השחוק שמשחק כו'. אך הענין הוא דהנה כתי' צחוק עשה לי אלקי', שם אלקי' הוא בחי' מגן ונרתק וכמ\"ש שמש ומגן הוי' אלקי' ששם אלקי' הוא בחי' העלם והסתר שמעלים ומסתיר על גילוי ש' הוי' עד שנעשה בחי' יש ודבר נפרד לגמרי בחי' אלקי' אחרי', אך אעפ\"כ עיקר הצחוק והתענוג נמשך דוקא מבחי' שם אלקי' שנעשה בחי' יש ודבר נפרד ואעפ\"כ נעשה בחי' ביטול היש לאין ומזה נמשך בחי' גילוי הצחוק והתענוג לפי שזהו דבר חדש שיהי' בחי' ביטול היש לאין כי משמיא מיהב יהבי משקל לא שקלי, מיהב הוא בחי' השתלשלות מאין ליש שאין זה דבר חדש, משקל לא שקלי שזהו ענין בחי' ביטול היש לאין, שזהו דבר חדש למעלה, ולפי שהוא דבר חדש לכן עי\"ז נמשך בחי' הצחוק והתענוג, וכמו שאנו רואי' למטה שהמשכת התענוג נמשך דוקא מהתחדשות איזו דבר כמו למשל הקניגיא שעושין לפני המלכים שהוא דבר חדש עי\"ז נמשך הצחוק והתענוג, וגם כי יתרון האור הוא מתוך החשך דוקא כד אתכפי' סט\"א אסתלק יקרא דקוב\"ה בכולהו עלמין, וזהו לויתן זה כו', כי לויתן הוא מל' הפעם ילוה אישי אלי שהוא ל' התחברות, אשה היא בחי' כנס\"י וכמ\"ש אשה יראת ה' היא תתהלל, ואיש זה הקוב\"ה וכמ\"ש ה' איש מלחמה, ביום ההוא תקראי לי אישי, וע\"י לויתן נעשה התחברו' אלקי' עם ישראל דהיינו ע\"י בחי' ביטול ממטה למעלה ומלמעלה למטה, כי בחי' ביטול היש לאין שהוא ממטלמ\"ע עי\"ז נמשך אח\"כ בחי' השחוק ותענוג מלמעלמ\"ט ע\"כ לויתן כפל הלשון מורה על בחי' ב' ההתחברות מלמטלמ\"ע ומלמעלמ\"ט, וזהו שג' שעות רביעית יושב ומשחק עם לויתן כי בשעות ראשונות עוסק בתורה ודן וזן שהוא הכל המשכה מלמעלמ\"ט ואח\"כ יושב ומשחק שנמשך מבחי' ביטול היש לאין שמלמטלמ\"ע.\n<b>וזהו</b> שארז\"ל לא גלו ישראל אלא כדי להוסיף עליהם גרים<sup data-n=\"116\">9</sup> ולכאורה אינו מובן שהרי בזמן הזה אינו בנמצא כלל גרים, וגם מה המעלה של גרים כ\"כ והרי ארז\"ל קשין גרים לישראל כספחת, אך הענין הוא דהנה פי' גרים קאי על בירורי",[["115","8","<b>דהנה כתי' לויתן זה יצרת לשחק בו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370084\" data-slug=\"torah-or\" data-id=\"3901370084\">תו\"א תולדות יז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380151\" data-slug=\"likkutei-torah\" data-id=\"4001380151\">לקו\"ת שמיני יח, ב</a>. פינחס עז, ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380690\" data-slug=\"likkutei-torah\" data-id=\"4001380690\">מסעי צא, ג</a>. שה\"ש כז, ב. ס' מאמרי אדה\"ז על מארז\"ל ע' קמג. סה\"מ תרל\"ג ח\"א ס\"ע עדר."],["116","9","<b>וזהו שארז\"ל לא גלו ישראל אלא כדי להוסיף עליהם גרים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370095\" data-slug=\"torah-or\" data-id=\"3901370095\">תו\"א תולדות שם כ, ג</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370022\" data-slug=\"torah-or\" data-id=\"3901370022\">תו\"א בראשית ו, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370048\" data-slug=\"torah-or\" data-id=\"3901370048\">לך יא, א</a>. לקו\"ת ואתחנן ט, ד. ובכ\"מ."]]],[2000460111,"נצוצות הנשמות שנפלו בשבירה וכשמבררי' אותם ונתעלו לקדושה נק' גרים כמו למשל הגר שהוא מארץ מרחק והי' רחוק מהקדושה ואח\"כ נתקרב לקדושה, כך הוא ענין נצוצי הנשמות שנפלו בשבירה והי' רחוקי' מהקדושה וכשמבררי' אותם מהקליפות נק' גרים, והנה ע\"י בירורי נצוצי הנשמות מהקליפה דוקא עי\"ז נמשך תוס' אורות יותר, וזהו כדי להוסיף עליהם גרים שעי\"ז נמשך תוס' אורות כו'.\n<b>ובזה</b> יתורץ הקושיא הנ\"ל למה הי' צריך לברוא את הקליפות ושיהי' צריכין לבררן יותר הי' טוב אם לא הי' נבראים כלל, ולפמ\"ש יתורץ היטב לפי שעי\"ז שנתבררו מהקליפה עי\"ז נמשך תוס' אורות לפי שזהו עיקר השחוק ותענוג עליון למעלה כשמבררין הקליפות, וכד אתכפי' סט\"א אסתלק יקרא דקוב\"ה בכולהו עלמין.\n<b>ולזה</b> יובן מה שרצה יצחק לברך את עשו<sup data-n=\"117\">10</sup>, והיינו לפי שראה שבעשו מלובש נצוצי נשמות קדושות ונפלו למטה בעשו וצריכי' להתברר ע\"כ רצה לברך את עשו שיוכל להתברר מצד עצמו שלא ע\"י יעקב דוקא, והיינו שרצה להמשיך בו תוס' אורות, וזהו שבירך אותו מטל השמים שהוא בחי' טלא דנטיף מע\"י, טל תחי', טל דעתיד בו להחיות את המתים, מתים הוא בחי' ז' מלכין קדמאין דתהו שנפלו בשבירה שנק' מתים ע\"ש שנא' וימלוך וימת, וע\"י טל דנטיף מע\"י עי\"ז יחי' המתים, וזהו שאנו אומרי' ברכת הטל בברכת אתה גבור, כי ענין גבורה אינו פי' גבורות וצמצומים אלא פי' גבורה היינו בחי' תגבורת החיות ע\"ד גבור כארי וע\"ד מ\"ש אל יתהלל כו' גבור בגבורתו כו' וכמו גבורות גשמים<sup data-n=\"118\">11</sup> שיורדין בגבורה שזה\"ע תגבורת החסד, וכן כי הדם הוא הנפש שהדם הוא חם בחי' גבורה, וזהו עיקר החיות כי המת הוא קר, ולכך לפי שטל עתיד להחיות בו את המתים לכך אומרי' אותו באתה גבור כו' לפי שזה\"ע תגבורת החיות כו', ולכן יצחק שהוא ג\"כ בחי' גבורו' בחי' שרש קו המדה בוצינא דקרדוניתא בחי' זהב, כמעלת הזהב על הכסף, כי כסף הוא בחי' אהבה וזהב הוא בחי' יראה בחי' גבורה תגבורת החיות ולכן זהב הוא ביוקר מהכסף ואעפ\"כ כסף הוא טבעא וזהב קונה את הכסף והיינו שהנהגת העולמות צ\"ל דוקא ע\"י בחי' חסדים כי באמת בתורה כתי' הנחמדים מזהב ומפז, ותורה היא בחי' יעקב וכמ\"ש ויקם עדות ביעקב ותורה שם בישראל שהוא בחי' בריח התיכון שמבריח מן הקצה כו', ולכן הנהגת העולמות צ\"ל דוקא ע\"י בחי' כסף בחי' חסדים מדריגת התורה שהיא בחי' חסד וכמ\"ש ותורת חסד על לשונה, ורצה יצחק להמשיך בעשו בחי' טל כדי שיוכלו נצוצי הנשמות שנבלעו בו להתעלות לקדושה שלא ע\"י יעקב אחיו, והגם שעשו אין ש\"ש שגור בפיו והי' יודע מזה, אך זהו מצד פנימיות שבפנימיותו הוא רע אבל מצד המקיף שלו שז\"ע רישא דעשו הוא בעטפי דיצחק",[["117","10","<b>ולזה יובן מה שרצה יצחק לברך את עשו</b>: בהבא להלן ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370095\" data-slug=\"torah-or\" data-id=\"3901370095\">תו\"א תולדות שם (כ, ג</a>). וסוף הפיסקא כאן הוא ע\"פ לשון התו\"א שם."],["118","11","<b>פי' גבורה היינו תגבורת החיות. . וכמו גבורות גשמים</b>: ראה גם סה\"מ תרכ\"ז ע' יג. טו. רמט. רסג. תרכ\"ט ע' רי. ובכ\"מ."]]],[2000460112,"שיש לו התחברות עם הקדושה שזה\"ע לבונה זכה, ולזה מצד המקיף שלו רצה להמשיך לו תוס' אורות כו' עד שאפי' הפנימית שלו יתבררו ג\"כ. אכן באמת טעה בזה כי אין עשו כדאי בבחי' זו כ\"א ע\"י יעקב דוקא, שלפי שאם הי' החיות נמשך על עשו יבלע ח\"ו כמקדם, או שלא יהי' מבחי' עשו כלום שיהי' בטל במציאות ממש ע\"ד הושיט אצבעו הקטנה ביניהם ושרפן, אבל שיהי' חשוכא לנהורא ומרירו למיתקא שיהי' יש ואעפ\"כ יהי' בחי' ביטול היש לאין א\"א כ\"א ע\"י יעקב ז\"א דקדושה שע\"י יתברר מעשו ויוכלל בקדושה, לכן הסכים יצחק ג\"כ לברכת יעקב אח\"כ ולעשו אמר הנה משמני הארץ כו' מקצת שמני (וליעקב אמר ומשמני בתוס' ואו) דהיינו מתמצית הנשאר משמן שנמשך אל הארץ שם יהי' מושביך בחי' פנימי', ומטל השמים של יעקב יומשך ג\"כ לך אבל אינו אלא מעל דהיינו בחי' מקיף בלבד, משא\"כ ביעקב ויתן לך, ובתנאי ואת אחיך תעבוד שתהי' בטל אל בחי' יעקב שע\"י יהי' עלי' דוקא כנ\"ל.\n<b>אך</b> לכאורה אינו מובן למה הי' צריך יעקב לברכת יצחק שהרי יעקב איש תם. אך הענין הוא דהנה האבות היו מרכבה והיו מקיימין את התורה ברוחניות, אבל כדי שיומשך התורה למטה בגשמיות וע\"י תו\"מ גשמי' יומשך המשכת עליונות למטה זה דוקא ע\"י הברכות שבירך אותו שיומשך ג\"כ למטה בתו\"מ גשמיים, וזשארז\"ל שמטל השמים הוא מקרא ומשמני הארץ זו משנה<sup data-n=\"119\">12</sup> ורוב דגן ותירוש זו הלכות ואגדות, והיינו שהברכה הי' כדי שיומשך בחי' תו\"מ בגשמיות ואעפ\"כ ע\"י מצוה גשמי' יומשך ג\"כ גילוי אא\"ס למטה כו'.\n<b>ועתה</b> יבואר הכתוב ראה ריח בני כו' כי ענין הריח הוא דבר שהנשמה נהנית ממנו<sup data-n=\"120\">13</sup> ולא הגוף, ולכאורה אינו מובן הלא ממאכל נהנית הנשמה ג\"כ שע\"י המאכל נעשה התחברו' הנשמה עם הגוף, וכמ\"כ מהריח נהנה הגוף ג\"כ, אמנם הענין הוא שיש ב' בחי' בנשמה א' המאירה בגוף והוא בחי' שכל ומדות, והב' מה שמאיר רק בבחי' מקיף לבד, והנה התחברות עשר בחי' הנפש עם הגוף הוא ע\"י המאכל כו', אכן כדי שיהי' התחברו' והמשכו' המקיף של הנשמה כמו כאשר האדם נתעלף ר\"ל או בשינה שאז הסתלקות המוחין מן הגוף, וצריך להמשיך מבחי' המקיף כו', אז לא יפעול המאכל חיבור הנפש עם הגוף, כי להמשכת מ\"ד של מקיף צריך להיות העלאת מ\"ן ג\"כ בבחי' מקיף, וזהו ענין הריח כי הריח משיב את הנפש דהיינו מה שהי' בתחלה בבחי' הסתלקות המוחי' חוזר ומאיר כאדם שהוא נרדם, וע\"י הריח חוזר ומקיץ<sup data-n=\"121\">14</sup>, דהיינו ע\"י שינה הי' השכל בהעלם ואח\"כ כשנעור",[["119","12","<b>וזשארז\"ל שמטל השמים הוא מקרא ומשמני הארץ זו משנה</b>: ראה גם סה\"מ תרכ\"ז ע' תעח. תפא. תרל\"ג ח\"ב ע' תקנא."],["120","13","<b>כי ענין הריח הוא דבר שהנשמה נהנית ממנו</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370096\" data-slug=\"torah-or\" data-id=\"3901370096\">תו\"א תולדות שם כ, ד</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370358\" data-slug=\"torah-or\" data-id=\"3901370358\">תו\"א תרומה פ, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380424\" data-slug=\"likkutei-torah\" data-id=\"4001380424\">לקו\"ת נשא כט, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381261\" data-slug=\"likkutei-torah\" data-id=\"4001381261\">שה\"ש לג, א</a>. סה\"מ תרל\"ב ח\"ב ע' תצה (ושם ג\"כ ע\"ד המבואר כאן בפיסקא זו)."],["121","14","<b>ומקיץ</b>: תוקן ע\"פ כת\"י 1063. ובכת\"י המעתיק כאן: ומקיף."]]],[2000460113,"משנתו הנה השכל מאיר בו בגילוי והכל נעשה ע\"י הריח שהוא אור החוזר ממטה למעלה, וז\"ע בחי' הריח שהנשמה נהנית ממנו ולא הגוף דהיינו שהריח מגיע לבחי' עצמו' הנפש כו'.\n<b>ועד\"ז</b> יובן ענין ריח בני כריח שדה דהנה בעבודה יש ג\"כ ב' בחי' העלאת מ\"ן, דהנה פעם אמרו מי כה' אלקינו בכל קראינו אליו וארז\"ל אליו ולא למדותיו, ופעם אמרו ובו תדבקון וארז\"ל וכי אפשר להדבק בהקב\"ה, אלא הדבק במדותיו מה הוא רחום כו', וארז\"ל מפני מה ישראל צועקין ואין נענין<sup data-n=\"122\">15</sup> מפני שאין יודעין לכוין בשם, ולע\"ל כתי' כי ידע שמי יקראני ואענהו שמשמע מזה שצריך שיכון בשם דוקא, אך הענין הוא דהנה איתא אנת הוא חד ולא בחושבן כו' אנת הוא דאפיקת עשר תיקונין והיינו כי יש ב' בחי' אהבה ומס\"נ, לאהבה את ה' כי הוא חייך הוא בחי' העלאה לבחי' ע\"ס, לפי שע\"ס הוא בחי' מקור החיות לכל העולמות שע\"י נמשך החיות מאא\"ס כו', אך אהבה דכל מאדך שהיא בחי' ק\"ש למסור נפשו באחד ע\"י בחי' אליו ולא למדותיו כו' ואח\"כ בשמ\"ע שהוא בחי' המשכה שנמשך ע\"י בחי' עשר תיקונין ע\"ס לכן צריך לכוין בשם דוקא. וזהו ראה ריח בני הוא בחי' העבודה שבבחי' מקיף שהוא בחי' ק\"ש כי ק\"ש נק' ריח וכמ\"ש בזהר חמינא בריחא דלבושייכו דלא קריתו ק\"ש, היא בחי' העלאה אליו ולא למדותיו, בחי' אנת חד כו', וזהו כריח שדה, דהנה כתי' מלך לשדה נעבד, כעבד שהשדה צריך שיהי' נעבד, וענין העבודה הוא כמ\"ש לעבדה ולשמרה רמ\"ח מ\"ע ומל\"ת, והנה ע\"י מ\"ע ממשיכי' אורו' בכלים שהוא בחי' המשכת או\"פ, אבל ע\"י מל\"ת ממשיכי' מבחי' המקיף כי שרש מל\"ת גבוהים ממ\"ע לפי שמל\"ת הוא בחי' אתכפיא, וכד אתכפי' סט\"א אסתלק יקרא דקוב\"ה בכולהו עלמין כו', וזהו ראה ריח בני שהוא בחי' המקיף הוא כריח שדה דהיינו כריח שיש בבחי' עבודה שבשדה, מלך לשדה נעבד, שהריח הוא מל\"ת שמגיע בבחי' מקיף כו' ועי\"ז ממשיכי' אשר ברכו הוי' כו'.\n<b>והנה</b> כ\"ז הוא הבנת הפסוק לפי דעתו של יצחק<sup data-n=\"123\">16</sup> שהי' סבור שעשו הי' לפניו, אך באמת הי' זה יעקב ואיך יבואר בחי' זו על יעקב. הנה איתא במדרש וירח את ריח בגדיו בוגדיו<sup data-n=\"124\">17</sup>, דיש ג' בחי' לבושי' כתנות אור בא' ואח\"כ כתנות עור בע', ואח\"כ לבושי' דלע\"ל. והענין הוא דהנה בחי' ריח בוגדיו הוא בחי' בע\"ת שהוא בחי' מקיף דמשכין לי' בחילא יתיר, שבזהר אמר ע\"פ ואברהם זקן בא בימים זכאין אינון מארי דתיובתא דמשכין לי' בחילא יתיר פי' למעלה מכדי שתוכל הנפש שאת שאין לו בחי' כלי להכיל וכמעשה דר\"א בן דורדיא משא\"כ באברהם כתי' בא",[["122","15","<b>וארז\"ל מפני מה ישראל צועקין ואין נענין</b>: ראה דרמ\"צ להצ\"צ קיז, א ואילך."],["123","16","<b>והנה כ\"ז הוא הבנת הפסוק לפי דעתו של יצחק</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370096\" data-slug=\"torah-or\" data-id=\"3901370096\">תו\"א תולדות שם כ, ד</a>."],["124","17","<b>וירח את ריח בגדיו בוגדיו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370524\" data-slug=\"torah-or\" data-id=\"3901370524\">תו\"א מג\"א קיז, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381125\" data-slug=\"likkutei-torah\" data-id=\"4001381125\">לקו\"ת ברכה צט, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381130\" data-slug=\"likkutei-torah\" data-id=\"4001381130\">ק, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381277\" data-slug=\"likkutei-torah\" data-id=\"4001381277\">שה\"ש לז, ב</a>. סה\"מ תרכ\"ט ע' קכ. תרל\"ב ח\"ב ע' תרלה ואילך. תרל\"ג ח\"א ע' מד. ועוד."]]],[2000460114,"בימים בחי' כלי ולבוש, ולכן מה שהי' אברהם בא בימים בבחי' העבודה כל ימיו הנה ע\"י התשובה נמשך בשעתא חדא וברגעא חדא כו' והיינו כי יתרון האור הוא מתוך החשך, וזה\"ע ריח בוגדיו שהוא בחי' תשובה כו', ואין פי' תשובה על העבירות דוקא, כי כל ימיו צריך להיות בתשובה ואפי' בבחי' צדיקי', אלא פי' תשובה שהיא בחי' צעקה על הפירוד כו'. וזהו משארז\"ל ראה ריח בני בזמן שבהמ\"ק קיים, כריח שדה בזמן הגלות, וכמ\"ש ציון שדה תחרש, אשר ברכו ה' לע\"ל כמ\"ש גדול יהי' כבוד הבית האחרון מן הראשון, והיינו כי בזמן הבית היו בחי' צדיקים, וזהו בחי' ריח בני, ובחורבן הוא בחי' שדה שהיא בחי' תפלה שכנגד קרבנות, והנה ארז\"ל גדולה תפלה יותר מן הקרבנות, ולכן ריח בני כריח שדה אשר ברכו ה' כו' לע\"ל.\n<b>וזהו</b> ג\"כ ענין ג' בחי' לבושים כתנות אור בא' היא בחי' גילוי אלקי', וע\"י חטא עה\"ד נעשה כתנות עור בע', בחי' משכא דחויא שהוא מעלים ומסתיר, אך הנה נא' מה יפו פעמיך בנעלים, והיינו ע\"י בחי' עובד אלקי' שהוא ע\"ד בחי' עורות עבודים, והיינו ע\"י שונה פרקו מאה פעמים וא' שהוא יותר מרגילותו עי\"ז נעשה עובד אלקי', וזהו מה יפו פעמייך בנעלים שע\"י נעלים שהיא בחי' כתנות עור בע', וכשהוא מעבד את הנעל בחי' עובד אלקי' עי\"ז נעשה מה יפו פעמייך כו' ועי\"ז נמשך לע\"ל אשר ברכו ה' כו' לבושי' דלע\"ל כו' שהוא בחי' לבושי' אחרים שהם באופן אחר ממש.\n<b>וזהו</b> ויתן לך האלקי' היינו שברכו שיהי' במדריגת אלקי' ע\"ד מ\"ש אני אמרתי אלקים אתם, רק ע\"י חטא העגל נא' אכן כאדם תמותון, ויצחק ברכו שיהי' במדרגת אלקים שמקבל מכל ע\"ס, וגם מה אלקי' קיים לעולם כך ישראל חיים וקיימים לעולם, מטל השמים בחי' טלא דנטיף מע\"י שהוא בחי' אתעדל\"ע, ויתן פרש\"י יתן ויחזור ויתן והיינו כי יש ב' בחי' אתדל\"ע, בחי' אתדל\"ע שמעורר אתעדל\"ת, ואתעדל\"ע שנמשך אח\"כ [ע\"י] אתעדל\"ת כו' וזהו ב' בחי' טל כו' טל הוא בחי' אתדל\"ע וכמ\"ש כטל השמים כו' אשר לא יקוה לאיש, וזהו ויתן לך יתן ויחזור ויתן שהוא ב' בחי' אתדל\"ע כנ\"ל וד\"ל."],[2000460115,"<h3>ויירא ויאמר מה נורא כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ ויצא, ט\"ל).</b>\nחולין עטה\"ק כו' אתר חול, הדיוט\nויצא\n<b>ויירא</b> ויאמר מה נורא<sup data-n=\"125\">1</sup> המקום הזה, אין זה כ\"א בית אלקים, ות\"א לית דין אתר הדיוט, אלהן אתר דרעוא בי' מן קדם הוי', ויונתן תרגם לית דין אתר חול, ארום אלהן בית מקדש לשמי' דהוי'. וצ\"ל אם חלוקים התרגומי' בפירושם או י\"ל ששניהם לדבר אחד נתכוונו.\n<b>והענין</b> הוא דבפי' חול יש בו שני פי', הא' כמש\"פ בזח\"ב פקודי דף רך\"ז ב' בפי' הפסוק ולהבדיל בין הקדש ובין החול שזהו בין הקדושה ובין סט\"א, ושם במק\"מ בשם נ\"ב (שהוא מהרח\"ו ז\"ל) בין הקדושה לק\"נ, ונמצא פי' חול היינו ק\"נ. ובזח\"ג אמור דצ\"ד ב' פי' שההבדלה שתיקנו חכמי' להבדיל במש\"ק המבדיל בין קדש לחול, שחול קאי על ההנהגה שנמשך ע\"י מט\"ט וסנדל, שהם ו\"ק דיצירה ודעשייה, וקדש הוא בחי' האצי', שהוא מה שמאיר בשבת, כי בשבת גם בחי' מט\"ט שנק' נער כמ\"ש נער הייתי שארז\"ל שרו של עולם אמרו, הנה בשבת נא' עליו גם זקנתי שפי' בזהר דסליק לסיבא ואתהדר כמלקדמין, והיינו שבשבת עולה למקום הזקנה ומקבל הארה מאצי', וגם מבחי' ע\"י שנק' סבא קדישא, או גם סבא דסבין כמ\"ש מזה במ\"א, וע' מענין סבא וסבא דסבין בהגהות לד\"ה בך\"ה בכסליו הארוכות קרוב לסופן<sup data-n=\"126\">2</sup>, ואתהדר כמלקדמין שאחר השבת שב להיות כמדרגתו בחול, שהוא ו\"ק דיצי', ולכן תקנו הבדלה במוש\"ק המבדיל בין קדש שמאיר בשבת, לחול שהוא ההנהגה שע\"י בחי' נער הנ\"ל<sup data-n=\"e9\">*</sup>, ונמצא פי' חול הוא ההנהגה ע\"י שלוחייהו היינו שרו של עולם.",[["125","1","<b>ויירא ויאמר מה נורא</b>: מאמר זה מלבד ההתחלה וסיום הוא מד\"ה ואמנם כו' האלף לך שלמה, הנדפס לעיל ע' כ וכאן בתוס' הגהות. להלן בהוספות נדפס ג\"כ מאמר זה בהנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע."],["126","2","<b>וע' מענין סבא דסבין בהגהות לד\"ה בך\"ה בכסליו הארוכות קרוב לסופן</b>: אוה\"ת חנוכה (כרך ב) רפט, ב ואילך."],["e9","*","<b>במהדו\"ק של המאמר, נרשם כאן בגוכי\"ק</b>:\nולפ\"ז י\"ל שהת\"י ות\"א אינם חלוקי' כלל בפירושם שמ\"ש הת\"י לית דין אתר חול הכוונה שבכאן אינו נמשך ע\"י מט\"ט שרו ש\"ע שהוא ו\"ק דיצי' אלא זהו מקום בהמ\"ק ששם היתה השראת שכינתו ית' וגילוי ש' הוי' שלכן במקדש היו קורין את השם ככתבו כנ\"ל, והת\"א ג\"כ כוונתו על מט\"ט שרו ש\"ע, רק שנתן סימן וקראו הדיוט, והיינו כאמרם ז\"ל הדיוט איהו לגבי מארי, ולכן א' לית דין אתר הדיוט פי' שנמשך ע\"י מט\"ט כמו בכל א\"י כ\"א מקום שרעוא בי' מן קדם הוי', שי\"ל הכוונה על בחי' מל' דאצי' ששרשה מבחי' רדל\"א כמ\"ש במק\"מ ולכן א' רעוא היינו בחי' רצה\"ע, מן קדם הוי', עלי' לפני הוי' שבסדר השתלשלות תטהרו כמ\"ש במ\"א תטהרו בגימ' כתר, ולכן אמר יעקב מה נורא המקום הזה, נורא הוא מקור היראה, ע\"ד נורא תהילות עושה פלא, שגם פליאות חכמה כעשי' גופנית נחשב לגבי בחי' עליונה שבכתר, או לגבי רדל\"א."]]],[2000460116,"<b>ותחלה</b> נבין לפי פי' הראשון דחול קאי על ק\"נ כו', מהו בחי' ההבדלה שבין קדש לבחי' חול זה דק\"נ, הנה נודע שבקטרת היו י\"א סממנים כמארז\"ל ואחד עשר סממנים היו כו' הצרי והצפורן כו' שנת' מזה במ\"א טעם היותם י\"א<sup data-n=\"127\">3</sup> מפני שהחיות המחי' י\"ס דנוגה הוא בבחי' מקיף עליהם, והוא בחי' מקיף דלבונה זכה שבעצם היא זכה עדיין. ונת' שם ששרש תי' זכה הוא זך, לרמז על ך\"ז אותיות שבאלפא ביתא, שאותיות אלו נעשה בחי' מקיף להחיות י\"ס דנוגה, ע\"ד השבעת השמות שעם היותם רק בחי' מקיף עכ\"ז פועלי' כו' ועד\"ז מחי' המקיף דלבונה ג\"כ את הי\"ס דנוגה, ומ\"מ אינו מעורב בהם כלל כ\"א בבחי' מקיף<sup data-n=\"128\">4</sup> לבד כו'.\n<b>והנה</b> בחי' לבונה זכה<sup data-n=\"129\">5</sup> הוא עצמו ההבדלה שבין קדש לחול, והיינו שכמו בקדושה שמל' דאצי' נעשית עתיק לבריאה כנודע ממ\"ש במ\"א בענין מלך יחיד<sup data-n=\"130\">6</sup> חי העולמי' שבחי' מלך שבאצי' נעשה יחיד בבריאה היינו בחי' עתיק דבריאה ומ\"מ בחי' מל' דאצי' עצמה היא הפרוכת והפרסא שבין אצי' לבי\"ע, כן ממל' דעשייה עצמה נעשה ההבדלה שבין העשייה לק\"נ, שזהו הבדלה שבין קדש לחול, והוא ע\"י שממל' דמל' דעשי' נעשית עתיק לק\"נ, וי\"ל שזהו המקיף דלבונה זכה שבי\"א סממני הקטרת שיש פי' שזהו מה שמל' דעשיי' נעשית עתיק לק\"נ, ולכן ע\"י י\"א סממני הקטרת שמבררי' בחי' אחד עשר כתרין דסט\"א עי\"ז נמשך תוס' אור בקדושה מבחי' חד ולא בחושבן בחי' עתיק יומין כתר דאצי' בבחי' עשר תיקונין שהם ע\"ס דאצי' כמ\"ש בהגהות לד\"ה ראה ריח בני<sup data-n=\"131\">7</sup>, והגם כי משם מובן שעיקר הבירור הוא ממה שנבלע בפנימיותן שזהו מה שפנימיותן הוא רע, משא\"כ מקיף דלבונה הוא מבחי' קדושה עדיין רק שמחבר ע\"ס דעשיי' עם עשר כתרין דנוגה, מ\"מ צ\"ל שהבירור הוא ע\"י המקיף דלבונה דוקא וכמו שרצה יצחק לפעול ע\"י המקיף, ואם כי טעה בזה שמעצמו א\"י להתברר כמש\"ש, כ\"א ע\"י יעקב ז\"א בעל עולם האצי' דוקא, מ\"מ בירור דיעקב ז\"א דאצי' ג\"כ מברר ע\"י המקיף דלבונה שהוא הנותן חיות בע\"ס דנוגה וע\"י מבררי' גם הניצוצות שנפלו בשה\"כ בע\"ס דנוגה בפנימיותן היינו מה שנבלע בהם להיות חיל בלע כו' ומבטנו יורישנו כו'",[["127","3","<b>שנת' מזה במ\"א טעם היותם י\"א</b>: ראה אוה\"ת וארא ע' ב'תקסח ואילך. לעיל ד\"ה ראה ריח בני (ע' כח). וש\"נ."],["128","4","<b>ע\"ד השבעת השמות. . בבחי' מקיף</b>: ראה לקמן ד\"ה ששים המה מלכות. וש\"נ."],["129","5","<b>והנה בחי' לבונה זכה</b>: מכאן (עד סוף פיסקא: ואמנם לתרץ) הוא מסד\"ה כרמי כו' האלף לך שלמה, הנדפס לעיל."],["130","6","<b>כנודע ממ\"ש במ\"א בענין מלך יחיד</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370183\" data-slug=\"torah-or\" data-id=\"3901370183\">תו\"א מקץ מ, ג</a>. מא, ב. סה\"מ תרכ\"ז ע' יח וע' ע. ובכ\"מ."],["131","7","<b>בהגהות לד\"ה ראה ריח בני</b>: אוה\"ת תולדות קנב, א ואילך. לעיל ד\"ה ראה ריח בני."]]],[2000460117,"שזהו מה שנבלע בפנימיותן, רק מ\"מ בירור זה הוא ע\"י המקיף דלבונה שהוא החיות דע\"ס שבנוגה שמחי' אותם בבחי' מקיף, וכשם שפועל להחיותן כן דרך בו פועלים שיתעלו הניצוצות שנבלעו בם שיתעלו ליכלל בבחי' הקדושה כו', ובאמת מוכרח להיות כן דוקא, שהרי אין המברר יכול לירד בפנימיות המתברר שלא יבלע ח\"ו כו', וא\"כ מוכרח להיות ע\"י מקיף דלבונה דוקא כו', וא\"כ לפ\"ז פי' המבדיל בין קדש לקדש זהו אפי' ההבדלה שבין יצי' לעשיי' ג\"כ, רק ההבדלה שבין עשייה לק\"נ זהו ההבדלה שבין קדש לחול ולמעלה מבחי' הבדלה זו הכל הם בחי' ההבדלות שבין קדש לקדש כו', רק שיש חילוקי מדריגות בבחי' בין קדש לקדש ג\"כ, שהרי י\"ג פרוכת היו במקדש כו'.\n<b>ואמנם</b> בזח\"ג פ' אמור דף צ\"ד ע\"ב פי' פסוק כי ששת ימים עשה ה' את השמים ואת כו', נ\"ב (והוא מהרח\"ו) ו\"ק דז\"א דאצי', אי הכי אמאי אקרון ששת ימי החול אמאי חול, א\"ר יוסי השתא אתנהיג עלמא ע\"י דשלוחייהו בגין כך ימי חול אקרון, ונ\"ב שהוא מט\"ט ו\"ק דיצי' ששת ימי החול עכ\"ל, וע' בפרד\"ס שער אבי\"ע פרק ה' ע\"פ שער החצר הפנימיות הפונה קדים סגור יהי' ששת ימי המעשה כו', ונמצא לפ\"ז גם ו\"ק דיצי' נק' ג\"כ חול, וכנ\"ל, וא\"כ ענין בחי' חולין שנעשו על טהרת הקדש הוא להמשיך ו\"ק דאצי' שיתלבשו במט\"ט, כמ\"ש מזה במ\"א<sup data-n=\"132\">8</sup>. והגם שהמק\"מ פי' שם על מ\"ש בשם הרח\"ו השתא אתנהיג עלמא ע\"י דשלוחייהו, שהוא מט\"ט ו\"ק דיצי', שזהו כמ\"ש הרב שבששת ימי החול יום א' דאצי' מתלבש בחסד דבריאה, וחסד דבריאה בחסד דיצי' ומשפיע באח\"פ<sup data-n=\"133\">9</sup>, ובחו\"ל מתלבש חסד דיצי' בחסד דעשיי' ומשפיע לחו\"ל, לפי שאח\"פ יונקת מיצי' וחו\"ל מעשיי' וז\"ש ע\"י דשלוחייהו ולכן נק' חול עכ\"ל, כוונתו דשלוחייהו ל' רבים היינו מט\"ט וסנדל שהם ו\"ק דיצי' וו\"ק דעשיי', א\"כ כ' לשון שמתלבש על יומין דחול, והיינו שהגם שיום א' דאצי' מתלבש בבי\"ע עכ\"ז חול הוא, ולפי מה שנת\"ל בפי' חולין שנעשו עטה\"ק הוא כשממשיכין ו\"ק דאצי' שיתלבשו במט\"ט ו\"ק דיצי' ה\"ז חולין שנעשו ע\"ט הקדש. אמנם באמת לא קשה מידי שי\"ל שיש כמה מיני התלבשות, אם העלם גמור, או גילוי, או דרך מעביר, שאם ההתלבשות הוא דרך מעביר לבד הרי עיקר הגילוי הוא מאצי' רק שעובר דרך מעביר דבי\"ע, וי\"ל שמה שנמשך דרך התלבשות גמור דעשיי' ה\"ז נק' העלם גמור, לפי שבעשי' השם המחי' הוא אל אד' בגימ' צ\"ו ואין צו אלא כו', ולכן גזרו טומאה על אוירא ואגושא (בפ\"ק דשבת דט\"ו א') ונק' לבוש שק שהוא בחי' אלביש כו' ושק אשים כסותם, וכשההתלבשות הוא דרך ו\"ק דיצי' לבד זהו הנק' גילוי כו' נגד ההתלבשות דלבוש שק שבעשי'. וזהו בכל אח\"פ, ויעקב שאמר מה נורא המקום הזה הוא לפי שהרגיש שבחי' מקום זה חלוק מבאר שבע,",[["132","8","<b>חולין שנעשו על טהרת הקדש. . שיתלבשו במט\"ט כמ\"ש מזה במ\"א</b>: ראה אוה\"ת נ\"ך ע' קעג. ובכ\"מ."],["133","9","<b>באח\"פ</b>: ארץ חפץ [ארץ ישראל]. [ועד\"ז לקמן בהמאמר]."]]]]});
